INSERT INTO tech_cards (card_number, dish_name, organization_id, approval_date, application_area, portion_norm, technology, technology_source, serving_requirements, total_output_kg, proteins_per_100g, fats_per_100g, carbs_per_100g, calories_per_100g, note, source_page) VALUES ('02293', 'Окрошка с ветчиной', (SELECT id FROM organizations WHERE name='Бранч'), '2023-05-06', 'Cake&Coffee', 1.000, 'Все овощи, белок и ветчину нарезать мелким, красивым кубиком,посолить, поперчить, смешать. Зелень измельчить.', 'original', 'В глубокую тарелку выложить смесь, раскрожить желток сверху, украсить рубленой зеленью. Квас подать отдельно в стакане, сметану в соусничке.', 0.23, 0, 0, 0, 0, 'технологическая карта составлена на основании акта проработки. По физико-химическим показателям соответствует требованиям ГОСТ РФ 50763-2007 "Кулинарная продукция, реализуемая населению". По микробиологическим показателям соответствует требованиям СанПиН 2.3.2 1078-01', 1);
INSERT INTO tech_cards (card_number, dish_name, organization_id, approval_date, application_area, portion_norm, technology, technology_source, serving_requirements, total_output_kg, proteins_per_100g, fats_per_100g, carbs_per_100g, calories_per_100g, note, source_page) VALUES ('03519', 'Паста с тартаром из тунца и страчателлой', (SELECT id FROM organizations WHERE name='Бранч'), '2023-05-05', 'Cake&Coffee', 1.000, 'Тунец нарезать мелким ровным кубиком, перцем. Пасту спиральки отварить, смешать с соусом песто, выложить в глубокую тарелку, сверху в центр выложить страчателлу, на страчателлу выложить тартар из тунца.', 'original', NULL, 0.2245, 0, 0, 0, 0, 'технологическая карта составлена на основании акта проработки. По физико-химическим показателям соответствует требованиям ГОСТ РФ 50763-2007 "Кулинарная продукция, реализуемая населению". По микробиологическим показателям соответствует требованиям СанПиН 2.3.2 1078-01', 2);
INSERT INTO tech_cards (card_number, dish_name, organization_id, approval_date, application_area, portion_norm, technology, technology_source, serving_requirements, total_output_kg, proteins_per_100g, fats_per_100g, carbs_per_100g, calories_per_100g, note, source_page) VALUES ('02594', 'Каркаде со специями 350', (SELECT id FROM organizations WHERE name='Бранч'), '2020-12-23', 'Cake&Coffee', 1.000, '(от ии) Заварочный чайник ополоснуть горячей водой. Положить заварку — Чай весовой. Залить водой температурой 92-95 °C из расчета 200 мл на порцию 350 мл (350 мл на порцию 600 мл). Добавить Цедра апельсина, Корица в палочках, Кардамон (раздавить зерна). В конце добавить Мед, размешать до растворения. Настаивать 5-7 минут под крышкой. Процедить через ситечко в подогретый стакан/чашку. Подавать при температуре 70-80 °C.', 'ai', NULL, 0.021, 1, 1, 17, 79, 'технологическая карта составлена на основании акта проработки. По физико-химическим показателям соответствует требованиям ГОСТ РФ 50763-2007 "Кулинарная продукция, реализуемая населению". По микробиологическим показателям соответствует требованиям СанПиН 2.3.2 1078-01', 3);
