INSERT INTO tech_cards (card_number, dish_name, organization_id, approval_date, application_area, portion_norm, technology, technology_source, serving_requirements, total_output_kg, proteins_per_100g, fats_per_100g, carbs_per_100g, calories_per_100g, note, source_page) VALUES ('00936', 'Чай с черной смородиной 350', (SELECT id FROM organizations WHERE name='Бранч'), '2022-12-01', 'Cake&Coffee', 1.000, '(от ии) Заварочный чайник ополоснуть горячей водой. Положить заварку — Чай весовой. Залить водой температурой 92-95 °C из расчета 200 мл на порцию 350 мл (350 мл на порцию 600 мл). Добавить Сахар-песок по вкусу. Настаивать 5-7 минут. Процедить, подавать горячим 75-80 °C. Настаивать 5-7 минут под крышкой. Процедить через ситечко в подогретый стакан/чашку. Подавать при температуре 70-80 °C.', 'ai', 'Черная смородина заморож.', 0.033, 0, 0, 0, 0, 'технологическая карта составлена на основании акта проработки. По физико-химическим показателям соответствует требованиям ГОСТ РФ 50763-2007 "Кулинарная продукция, реализуемая населению". По микробиологическим показателям соответствует требованиям СанПиН 2.3.2 1078-01', 9);
