INSERT INTO tech_cards (card_number, dish_name, organization_id, approval_date, application_area, portion_norm, technology, technology_source, serving_requirements, total_output_kg, proteins_per_100g, fats_per_100g, carbs_per_100g, calories_per_100g, note, source_page) VALUES ('00648', 'Алтайский 350 травяной', (SELECT id FROM organizations WHERE name='Бранч'), '2020-12-15', 'Cake&Coffee', 1.000, '(от ии) Заварочный чайник ополоснуть горячей водой. Положить Чай весовой (травяной сбор Алтайский). Залить водой температурой 90-95 °C. Настаивать 5-7 минут под крышкой. Процедить через ситечко в подогретый стакан/чашку. При подаче — Сахар-песок отдельно. Температура подачи 70-80 °C.', 'ai', NULL, 0.008, 0, 0, 0, 0, 'технологическая карта составлена на основании акта проработки. По физико-химическим показателям соответствует требованиям ГОСТ РФ 50763-2007 "Кулинарная продукция, реализуемая населению". По микробиологическим показателям соответствует требованиям СанПиН 2.3.2 1078-01', 11);
INSERT INTO tech_cards (card_number, dish_name, organization_id, approval_date, application_area, portion_norm, technology, technology_source, serving_requirements, total_output_kg, proteins_per_100g, fats_per_100g, carbs_per_100g, calories_per_100g, note, source_page) VALUES ('00649', 'Алтайский 600 травяной', (SELECT id FROM organizations WHERE name='Бранч'), '2020-12-15', 'Cake&Coffee', 1.000, '(от ии) Заварочный чайник ополоснуть горячей водой. Положить Чай весовой (травяной сбор Алтайский). Залить водой температурой 90-95 °C. Настаивать 5-7 минут под крышкой. Процедить через ситечко в подогретый стакан/чашку. При подаче — Сахар-песок отдельно. Температура подачи 70-80 °C.', 'ai', NULL, 0.01, 0, 0, 0, 1, 'технологическая карта составлена на основании акта проработки. По физико-химическим показателям соответствует требованиям ГОСТ РФ 50763-2007 "Кулинарная продукция, реализуемая населению". По микробиологическим показателям соответствует требованиям СанПиН 2.3.2 1078-01', 12);
