INSERT INTO tech_cards (card_number, dish_name, organization_id, approval_date, application_area, portion_norm, technology, technology_source, serving_requirements, total_output_kg, proteins_per_100g, fats_per_100g, carbs_per_100g, calories_per_100g, note, source_page) VALUES ('00063', 'Горячий шоколад', (SELECT id FROM organizations WHERE name='Бранч'), '2021-12-01', 'Cake&Coffee', 1.000, '(от ии) Сливки 10% (150 мл) нагреть в сотейнике до 70-75 °C, не доводя до кипения. Добавить шоколад (пористый/ломтиками), помешивать венчиком до полного растворения 2-3 минуты. Разлить в подогретую чашку. Сверху выложить шарик Мороженое. Температура подачи 65-70 °C.', 'ai', 'Шоколад мол. в И РЕАЛИЗАЦИИ галетах', 0.235, 4, 4, 11, 94, 'технологическая карта составлена на основании акта проработки. По физико-химическим показателям соответствует требованиям ГОСТ РФ 50763-2007 "Кулинарная продукция, реализуемая населению". По микробиологическим показателям соответствует требованиям СанПиН 2.3.2 1078-01', 30);
INSERT INTO tech_cards (card_number, dish_name, organization_id, approval_date, application_area, portion_norm, technology, technology_source, serving_requirements, total_output_kg, proteins_per_100g, fats_per_100g, carbs_per_100g, calories_per_100g, note, source_page) VALUES ('00062', 'Какао', (SELECT id FROM organizations WHERE name='Бранч'), '2016-12-22', 'Cake&Coffee', 1.000, '(от ии) Молоко 3,2% (180 мл) нагреть в сотейнике до 85-90 °C. Добавить Какао Несквик (25-30 г), перемешать венчиком до полного растворения, 1-2 минуты. Не кипятить. Разлить в подогретую чашку. Температура подачи 70-75 °C.', 'ai', NULL, 0.28, 3, 3, 9, 74, 'технологическая карта составлена на основании акта проработки. По физико-химическим показателям соответствует требованиям ГОСТ РФ 50763-2007 "Кулинарная продукция, реализуемая населению". По микробиологическим показателям соответствует требованиям СанПиН 2.3.2 1078-01', 31);
INSERT INTO tech_cards (card_number, dish_name, organization_id, approval_date, application_area, portion_norm, technology, technology_source, serving_requirements, total_output_kg, proteins_per_100g, fats_per_100g, carbs_per_100g, calories_per_100g, note, source_page) VALUES ('00067', 'Лимонад клубника - базилик', (SELECT id FROM organizations WHERE name='Бранч'), '2020-12-23', 'Cake&Coffee', 1.000, '(от ии) Клубника свежая (5-6 шт.) разрезать пополам. Базилик (3-4 листа) помять мадлером с клубникой для выделения сока. Добавить Сахарный сироп (30 мл) и Лед в шейкер. Взбить 10-15 секунд. Процедить в высокий стакан. Украсить целой клубникой и листом базилика. Подавать при 3-8 °C.', 'ai', 'Аква минерале розлив', 0.073, 0, 0, 0, 0, 'технологическая карта составлена на основании акта проработки. По физико-химическим показателям соответствует требованиям ГОСТ РФ 50763-2007 "Кулинарная продукция, реализуемая населению". По микробиологическим показателям соответствует требованиям СанПиН 2.3.2 1078-01', 32);
INSERT INTO tech_cards (card_number, dish_name, organization_id, approval_date, application_area, portion_norm, technology, technology_source, serving_requirements, total_output_kg, proteins_per_100g, fats_per_100g, carbs_per_100g, calories_per_100g, note, source_page) VALUES ('00066', 'Лимонад яблоко - имбирь', (SELECT id FROM organizations WHERE name='Бранч'), '2020-12-23', 'Cake&Coffee', 1.000, '(от ии) Яблоки (1 шт.) нарезать дольками. Имбирь корень (5 г) натереть на терке, помять с яблоками. Добавить Сахарный сироп (30 мл) и Лед в шейкер. Взбить 10-15 секунд. Процедить в высокий стакан. Украсить долькой яблока и ломтиком имбиря. Подавать при 3-8 °C.', 'ai', 'Аква минерале розлив', 0.092, 0, 0, 0, 0, 'технологическая карта составлена на основании акта проработки. По физико-химическим показателям соответствует требованиям ГОСТ РФ 50763-2007 "Кулинарная продукция, реализуемая населению". По микробиологическим показателям соответствует требованиям СанПиН 2.3.2 1078-01', 33);
