INSERT INTO tech_cards (card_number, dish_name, organization_id, approval_date, application_area, portion_norm, technology, technology_source, serving_requirements, total_output_kg, proteins_per_100g, fats_per_100g, carbs_per_100g, calories_per_100g, note, source_page) VALUES ('00103', 'Швепс', (SELECT id FROM organizations WHERE name='Бранч'), '2019-02-09', 'Cake&Coffee', 1000, '(от ии) Напиток подать в бутылке или перелить в стакан со Лед по запросу гостя. Хранить при 2-6 °C.', 'ai', NULL, NULL, 0, 0, 0, 0, 'технологическая карта составлена на основании акта проработки. По физико-химическим показателям соответствует требованиям ГОСТ РФ 50763-2007 "Кулинарная продукция, реализуемая населению". По микробиологическим показателям соответствует требованиям СанПиН 2.3.2 1078-01', 40);
INSERT INTO tech_cards (card_number, dish_name, organization_id, approval_date, application_area, portion_norm, technology, technology_source, serving_requirements, total_output_kg, proteins_per_100g, fats_per_100g, carbs_per_100g, calories_per_100g, note, source_page) VALUES ('00609', 'Американо', (SELECT id FROM organizations WHERE name='Бранч'), '2020-12-15', 'Cake&Coffee', 1.000, '(от ии) В кофемашине прогреть портafiльтр (15-20 секунд). Отмерить Эспрессо кейк/кук 18-20 г в холдер, утрамбовать тампером давлением ~15 кг. Экстракция при 9 бар, температура воды 90-94 °C, время экстракции 25-30 секунд. Объем одной порции эспрессо ~30 мл. Дополнительно пропустить 150-180 мл горячей воды (90-95 °C) через эспрессо или добавить в чашку. Общий объем ~200-220 мл. Подавать сразу при 65-70 °C.', 'ai', NULL, 0.04, 1, 1, 1, 15, 'технологическая карта составлена на основании акта проработки. По физико-химическим показателям соответствует требованиям ГОСТ РФ 50763-2007 "Кулинарная продукция, реализуемая населению". По микробиологическим показателям соответствует требованиям СанПиН 2.3.2 1078-01', 41);
INSERT INTO tech_cards (card_number, dish_name, organization_id, approval_date, application_area, portion_norm, technology, technology_source, serving_requirements, total_output_kg, proteins_per_100g, fats_per_100g, carbs_per_100g, calories_per_100g, note, source_page) VALUES ('00091', 'Апельсиновый раф size M', (SELECT id FROM organizations WHERE name='Бранч'), '2019-04-20', 'Cake&Coffee', 1.000, '(от ии) В кофемашине прогреть портafiльтр (15-20 секунд). Отмерить Эспрессо кейк/кук 18-20 г в холдер, утрамбовать тампером давлением ~15 кг. Экстракция при 9 бар, температура воды 90-94 °C, время экстракции 25-30 секунд. Объем одной порции эспрессо ~30 мл. Сливки 10% подогреть до 60-65 °C, взбить ручным венчиком или капучинатором до мягкой пены. Не перегревать выше 70 °C — сливки могут расслоиться.Эспрессо (30 мл) соединить со взбитыми Сливки 10%, добавить Цедра апельсина (натереть на мелкой терке) и Сахар ванильный. Перемешать. Подавать в подогретой чашке, украсить полоской цедры. Температура подачи 60-65 °C.', 'ai', NULL, 0.34, 0, 0, 0, 0, 'технологическая карта составлена на основании акта проработки. По физико-химическим показателям соответствует требованиям ГОСТ РФ 50763-2007 "Кулинарная продукция, реализуемая населению". По микробиологическим показателям соответствует требованиям СанПиН 2.3.2 1078-01', 42);
INSERT INTO tech_cards (card_number, dish_name, organization_id, approval_date, application_area, portion_norm, technology, technology_source, serving_requirements, total_output_kg, proteins_per_100g, fats_per_100g, carbs_per_100g, calories_per_100g, note, source_page) VALUES ('00092', 'Апельсиновый раф size S', (SELECT id FROM organizations WHERE name='Бранч'), '2019-04-20', 'Cake&Coffee', 1.000, '(от ии) В кофемашине прогреть портafiльтр (15-20 секунд). Отмерить Эспрессо кейк/кук 18-20 г в холдер, утрамбовать тампером давлением ~15 кг. Экстракция при 9 бар, температура воды 90-94 °C, время экстракции 25-30 секунд. Объем одной порции эспрессо ~30 мл. Сливки 10% подогреть до 60-65 °C, взбить ручным венчиком или капучинатором до мягкой пены. Не перегревать выше 70 °C — сливки могут расслоиться.Эспрессо (30 мл) соединить со взбитыми Сливки 10%, добавить Цедра апельсина (натереть на мелкой терке) и Сахар ванильный. Перемешать. Подавать в подогретой чашке, украсить полоской цедры. Температура подачи 60-65 °C.', 'ai', NULL, 0.3, 0, 0, 0, 0, 'технологическая карта составлена на основании акта проработки. По физико-химическим показателям соответствует требованиям ГОСТ РФ 50763-2007 "Кулинарная продукция, реализуемая населению". По микробиологическим показателям соответствует требованиям СанПиН 2.3.2 1078-01', 43);
INSERT INTO tech_cards (card_number, dish_name, organization_id, approval_date, application_area, portion_norm, technology, technology_source, serving_requirements, total_output_kg, proteins_per_100g, fats_per_100g, carbs_per_100g, calories_per_100g, note, source_page) VALUES ('00096', 'Арахисовый латте size M', (SELECT id FROM organizations WHERE name='Бранч'), '2022-10-19', 'Cake&Coffee', 1.000, '(от ии) В кофемашине прогреть портafiльтр (15-20 секунд). Отмерить Эспрессо кейк/кук 18-20 г в холдер, утрамбовать тампером давлением ~15 кг. Экстракция при 9 бар, температура воды 90-94 °C, время экстракции 25-30 секунд. Объем одной порции эспрессо ~30 мл. В чашку положить Арахисовая паста. Налить горячий эспрессо (30 мл), перемешать до растворения пасты. Молоко 3,2% взбить капучинатором (паровой стержень) до температуры 65 °C, микропена — однородная глянцевая текстура без крупных пузырей. Взбивать погружая сопло на 1 см ниже поверхности молока до появления микропены, затем опустить глубже для нагрева. Добавить взбитое молоко. Температура подачи 60-65 °C.', 'ai', NULL, 0.36, 1, 1, 1, 18, 'технологическая карта составлена на основании акта проработки. По физико-химическим показателям соответствует требованиям ГОСТ РФ 50763-2007 "Кулинарная продукция, реализуемая населению". По микробиологическим показателям соответствует требованиям СанПиН 2.3.2 1078-01', 44);
INSERT INTO tech_cards (card_number, dish_name, organization_id, approval_date, application_area, portion_norm, technology, technology_source, serving_requirements, total_output_kg, proteins_per_100g, fats_per_100g, carbs_per_100g, calories_per_100g, note, source_page) VALUES ('00095', 'Арахисовый латте size S', (SELECT id FROM organizations WHERE name='Бранч'), '2019-04-19', 'Cake&Coffee', 1.000, '(от ии) В кофемашине прогреть портafiльтр (15-20 секунд). Отмерить Эспрессо кейк/кук 18-20 г в холдер, утрамбовать тампером давлением ~15 кг. Экстракция при 9 бар, температура воды 90-94 °C, время экстракции 25-30 секунд. Объем одной порции эспрессо ~30 мл. В чашку положить Арахисовая паста. Налить горячий эспрессо (30 мл), перемешать до растворения пасты. Молоко 3,2% взбить капучинатором (паровой стержень) до температуры 65 °C, микропена — однородная глянцевая текстура без крупных пузырей. Взбивать погружая сопло на 1 см ниже поверхности молока до появления микропены, затем опустить глубже для нагрева. Добавить взбитое молоко. Сверху посыпать рубленым Арахис. Температура подачи 60-65 °C.', 'ai', NULL, 0.306, 0, 0, 0, 0, 'технологическая карта составлена на основании акта проработки. По физико-химическим показателям соответствует требованиям ГОСТ РФ 50763-2007 "Кулинарная продукция, реализуемая населению". По микробиологическим показателям соответствует требованиям СанПиН 2.3.2 1078-01', 45);
INSERT INTO tech_cards (card_number, dish_name, organization_id, approval_date, application_area, portion_norm, technology, technology_source, serving_requirements, total_output_kg, proteins_per_100g, fats_per_100g, carbs_per_100g, calories_per_100g, note, source_page) VALUES ('03249', 'Арахисовый РАФ', (SELECT id FROM organizations WHERE name='Бранч'), '2022-08-31', 'Cake&Coffee', 1.000, '(от ии) В кофемашине прогреть портafiльтр (15-20 секунд). Отмерить Эспрессо кейк/кук 18-20 г в холдер, утрамбовать тампером давлением ~15 кг. Экстракция при 9 бар, температура воды 90-94 °C, время экстракции 25-30 секунд. Объем одной порции эспрессо ~30 мл. В подогретую чашку положить Арахисовая паста, налить эспрессо (30 мл), перемешать. Сливки 10% подогреть до 60-65 °C, взбить ручным венчиком или капучинатором до мягкой пены. Не перегревать выше 70 °C — сливки могут расслоиться. Добавить взбитые сливки. Перемешать. Температура подачи 60-65 °C.', 'ai', NULL, 0.392, 0, 0, 0, 0, 'технологическая карта составлена на основании акта проработки. По физико-химическим показателям соответствует требованиям ГОСТ РФ 50763-2007 "Кулинарная продукция, реализуемая населению". По микробиологическим показателям соответствует требованиям СанПиН 2.3.2 1078-01', 46);
INSERT INTO tech_cards (card_number, dish_name, organization_id, approval_date, application_area, portion_norm, technology, technology_source, serving_requirements, total_output_kg, proteins_per_100g, fats_per_100g, carbs_per_100g, calories_per_100g, note, source_page) VALUES ('00099', 'Гляссе', (SELECT id FROM organizations WHERE name='Бранч'), '2021-12-23', 'Cake&Coffee', 1.000, '(от ии) Приготовить Доппио (60 мл эспрессо двойной экстракции, 90-94 °C, 9 бар, 25-30 сек). В высокий стакан положить шарик Мороженое (ванильное). Сверху аккуратно налить горячий доппио. Подавать сразу — контраст горячего кофе и холодного мороженого. Температура подачи 40-50 °C.', 'ai', NULL, 0.09, 4, 3, 19, 119, 'технологическая карта составлена на основании акта проработки. По физико-химическим показателям соответствует требованиям ГОСТ РФ 50763-2007 "Кулинарная продукция, реализуемая населению". По микробиологическим показателям соответствует требованиям СанПиН 2.3.2 1078-01', 47);
INSERT INTO tech_cards (card_number, dish_name, organization_id, approval_date, application_area, portion_norm, technology, technology_source, serving_requirements, total_output_kg, proteins_per_100g, fats_per_100g, carbs_per_100g, calories_per_100g, note, source_page) VALUES ('00098', 'Доппио', (SELECT id FROM organizations WHERE name='Бранч'), '2023-04-07', 'Cake&Coffee', 1.000, '(от ии) В кофемашине прогреть портafiльтр (15-20 секунд). Отмерить Эспрессо кейк/кук 18-20 г в холдер, утрамбовать тампером давлением ~15 кг. Экстракция при 9 бар, температура воды 90-94 °C, время экстракции 25-30 секунд. Объем одной порции эспрессо ~30 мл. Использовать двойную дозу кофе 18-20 г на двойной спешелти-холдер. Экстракция 25-30 секунд, объем ~60 мл. Подавать в подогретой чашке при 65-70 °C.', 'ai', NULL, 0.024, 1, 1, 1, 17, 'технологическая карта составлена на основании акта проработки. По физико-химическим показателям соответствует требованиям ГОСТ РФ 50763-2007 "Кулинарная продукция, реализуемая населению". По микробиологическим показателям соответствует требованиям СанПиН 2.3.2 1078-01', 48);
INSERT INTO tech_cards (card_number, dish_name, organization_id, approval_date, application_area, portion_norm, technology, technology_source, serving_requirements, total_output_kg, proteins_per_100g, fats_per_100g, carbs_per_100g, calories_per_100g, note, source_page) VALUES ('01123', 'Имбирный латте size M', (SELECT id FROM organizations WHERE name='Бранч'), '2019-04-19', 'Cake&Coffee', 1.000, '(от ии) В кофемашине прогреть портafiльтр (15-20 секунд). Отмерить Эспрессо кейк/кук 18-20 г в холдер, утрамбовать тампером давлением ~15 кг. Экстракция при 9 бар, температура воды 90-94 °C, время экстракции 25-30 секунд. Объем одной порции эспрессо ~30 мл. Молоко 3,2% взбить капучинатором (паровой стержень) до температуры 65 °C, микропена — однородная глянцевая текстура без крупных пузырей. Взбивать погружая сопло на 1 см ниже поверхности молока до появления микропены, затем опустить глубже для нагрева.Имбирь корень (3-5 г) натереть на мелкой терке или нарезать тонкими слайсами. Поместить в чашку, залить эспрессо (30 мл). Добавить Корица молотая и щепотку Мускатный орех на кончике ножа. Добавить взбитое молоко. Перемешать. Температура подачи 60-65 °C.', 'ai', NULL, 0.349, 0, 0, 0, 0, 'технологическая карта составлена на основании акта проработки. По физико-химическим показателям соответствует требованиям ГОСТ РФ 50763-2007 "Кулинарная продукция, реализуемая населению". По микробиологическим показателям соответствует требованиям СанПиН 2.3.2 1078-01', 49);
INSERT INTO tech_cards (card_number, dish_name, organization_id, approval_date, application_area, portion_norm, technology, technology_source, serving_requirements, total_output_kg, proteins_per_100g, fats_per_100g, carbs_per_100g, calories_per_100g, note, source_page) VALUES ('01124', 'Имбирный латте size S', (SELECT id FROM organizations WHERE name='Бранч'), '2019-04-19', 'Cake&Coffee', 1.000, '(от ии) В кофемашине прогреть портafiльтр (15-20 секунд). Отмерить Эспрессо кейк/кук 18-20 г в холдер, утрамбовать тампером давлением ~15 кг. Экстракция при 9 бар, температура воды 90-94 °C, время экстракции 25-30 секунд. Объем одной порции эспрессо ~30 мл. Молоко 3,2% взбить капучинатором (паровой стержень) до температуры 65 °C, микропена — однородная глянцевая текстура без крупных пузырей. Взбивать погружая сопло на 1 см ниже поверхности молока до появления микропены, затем опустить глубже для нагрева.Имбирь корень (3-5 г) натереть на мелкой терке или нарезать тонкими слайсами. Поместить в чашку, залить эспрессо (30 мл). Добавить Корица молотая и щепотку Мускатный орех на кончике ножа. Добавить взбитое молоко. Перемешать. Температура подачи 60-65 °C.', 'ai', NULL, 0.265, 0, 0, 0, 0, 'технологическая карта составлена на основании акта проработки. По физико-химическим показателям соответствует требованиям ГОСТ РФ 50763-2007 "Кулинарная продукция, реализуемая населению". По микробиологическим показателям соответствует требованиям СанПиН 2.3.2 1078-01', 50);
INSERT INTO tech_cards (card_number, dish_name, organization_id, approval_date, application_area, portion_norm, technology, technology_source, serving_requirements, total_output_kg, proteins_per_100g, fats_per_100g, carbs_per_100g, calories_per_100g, note, source_page) VALUES ('03007', 'Капучино M', (SELECT id FROM organizations WHERE name='Бранч'), '2021-12-22', 'Cake&Coffee', 1.000, '(от ии) В кофемашине прогреть портafiльтр (15-20 секунд). Отмерить Эспрессо кейк/кук 18-20 г в холдер, утрамбовать тампером давлением ~15 кг. Экстракция при 9 бар, температура воды 90-94 °C, время экстракции 25-30 секунд. Объем одной порции эспрессо ~30 мл. Молоко 3,2% взбить капучинатором (паровой стержень) до температуры 65 °C, микропена — однородная глянцевая текстура без крупных пузырей. Взбивать погружая сопло на 1 см ниже поверхности молока до появления микропены, затем опустить глубже для нагрева. В подогретую чашку налить эспрессо (30 мл). Добавить взбитое молоко, перемещая кувшин для создания слоя крема. Общий объем 240-300 мл. Температура подачи 60-65 °C. Соотношение эспрессо/молоко/пена — 1/3-1/4.', 'ai', NULL, 0.012, 0, 0, 0, 0, 'технологическая карта составлена на основании акта проработки. По физико-химическим показателям соответствует требованиям ГОСТ РФ 50763-2007 "Кулинарная продукция, реализуемая населению". По микробиологическим показателям соответствует требованиям СанПиН 2.3.2 1078-01', 51);
INSERT INTO tech_cards (card_number, dish_name, organization_id, approval_date, application_area, portion_norm, technology, technology_source, serving_requirements, total_output_kg, proteins_per_100g, fats_per_100g, carbs_per_100g, calories_per_100g, note, source_page) VALUES ('03008', 'Капучино S', (SELECT id FROM organizations WHERE name='Бранч'), '2021-12-22', 'Cake&Coffee', 1.000, '(от ии) В кофемашине прогреть портafiльтр (15-20 секунд). Отмерить Эспрессо кейк/кук 18-20 г в холдер, утрамбовать тампером давлением ~15 кг. Экстракция при 9 бар, температура воды 90-94 °C, время экстракции 25-30 секунд. Объем одной порции эспрессо ~30 мл. Молоко 3,2% взбить капучинатором (паровой стержень) до температуры 65 °C, микропена — однородная глянцевая текстура без крупных пузырей. Взбивать погружая сопло на 1 см ниже поверхности молока до появления микропены, затем опустить глубже для нагрева. В подогретую чашку налить эспрессо (30 мл). Добавить взбитое молоко, перемещая кувшин для создания слоя крема. Общий объем 150-180 мл. Температура подачи 60-65 °C. Соотношение эспрессо/молоко/пена — 1/3-1/4.', 'ai', NULL, 0.012, 0, 0, 0, 0, 'технологическая карта составлена на основании акта проработки. По физико-химическим показателям соответствует требованиям ГОСТ РФ 50763-2007 "Кулинарная продукция, реализуемая населению". По микробиологическим показателям соответствует требованиям СанПиН 2.3.2 1078-01', 52);
INSERT INTO tech_cards (card_number, dish_name, organization_id, approval_date, application_area, portion_norm, technology, technology_source, serving_requirements, total_output_kg, proteins_per_100g, fats_per_100g, carbs_per_100g, calories_per_100g, note, source_page) VALUES ('02915', 'Кофе в зернах', (SELECT id FROM organizations WHERE name='Бранч'), '2021-07-21', 'Cake&Coffee', 1000, '(от ии) Кофе в зернах — продать в пакете. Хранить в герметичной упаковке при комнатной температуре, вдали от влаги и запахов.', 'ai', NULL, NULL, 1, 1, 1, 15, 'технологическая карта составлена на основании акта проработки. По физико-химическим показателям соответствует требованиям ГОСТ РФ 50763-2007 "Кулинарная продукция, реализуемая населению". По микробиологическим показателям соответствует требованиям СанПиН 2.3.2 1078-01', 53);
INSERT INTO tech_cards (card_number, dish_name, organization_id, approval_date, application_area, portion_norm, technology, technology_source, serving_requirements, total_output_kg, proteins_per_100g, fats_per_100g, carbs_per_100g, calories_per_100g, note, source_page) VALUES ('03401', 'Лавандовый раф 340мл', (SELECT id FROM organizations WHERE name='Бранч'), '2023-02-08', 'Cake&Coffee', 1.000, '(от ии) В кофемашине прогреть портafiльтр (15-20 секунд). Отмерить Эспрессо кейк/кук 18-20 г в холдер, утрамбовать тампером давлением ~15 кг. Экстракция при 9 бар, температура воды 90-94 °C, время экстракции 25-30 секунд. Объем одной порции эспрессо ~30 мл. Сливки 10% подогреть до 60-65 °C, взбить ручным венчиком или капучинатором до мягкой пены. Не перегревать выше 70 °C — сливки могут расслоиться.В подогретую чашку налить Сироп Herbarista (лавандовый, 15 мл). Налить эспрессо (30 мл), перемешать. Добавить взбитые Сливки 10%. Температура подачи 60-65 °C.', 'ai', NULL, 0.275, 0, 0, 0, 0, 'технологическая карта составлена на основании акта проработки. По физико-химическим показателям соответствует требованиям ГОСТ РФ 50763-2007 "Кулинарная продукция, реализуемая населению". По микробиологическим показателям соответствует требованиям СанПиН 2.3.2 1078-01', 54);
INSERT INTO tech_cards (card_number, dish_name, organization_id, approval_date, application_area, portion_norm, technology, technology_source, serving_requirements, total_output_kg, proteins_per_100g, fats_per_100g, carbs_per_100g, calories_per_100g, note, source_page) VALUES ('03400', 'Латте "Пряные специи"', (SELECT id FROM organizations WHERE name='Бранч'), '2023-02-08', 'Cake&Coffee', 1.000, '(от ии) В кофемашине прогреть портafiльтр (15-20 секунд). Отмерить Эспрессо кейк/кук 18-20 г в холдер, утрамбовать тампером давлением ~15 кг. Экстракция при 9 бар, температура воды 90-94 °C, время экстракции 25-30 секунд. Объем одной порции эспрессо ~30 мл. Молоко 3,2% взбить капучинатором (паровой стержень) до температуры 65 °C, микропена — однородная глянцевая текстура без крупных пузырей. Взбивать погружая сопло на 1 см ниже поверхности молока до появления микропены, затем опустить глубже для нагрева.Бадьян (1 звезда) и Гвоздика целая (2-3 бутона) слегка раздавить. Поместить в чашку, налить эспрессо (30 мл), добавить Сахар ванильный. Настоять 1 минуту. Добавить Корица молотая. Влить взбитое молоко. Процедить при подаче. Температура подачи 60-65 °C.', 'ai', NULL, 0.3095, 0, 0, 0, 0, 'технологическая карта составлена на основании акта проработки. По физико-химическим показателям соответствует требованиям ГОСТ РФ 50763-2007 "Кулинарная продукция, реализуемая населению". По микробиологическим показателям соответствует требованиям СанПиН 2.3.2 1078-01', 55);
INSERT INTO tech_cards (card_number, dish_name, organization_id, approval_date, application_area, portion_norm, technology, technology_source, serving_requirements, total_output_kg, proteins_per_100g, fats_per_100g, carbs_per_100g, calories_per_100g, note, source_page) VALUES ('03005', 'Латте M', (SELECT id FROM organizations WHERE name='Бранч'), '2021-12-22', 'Cake&Coffee', 1.000, '(от ии) В кофемашине прогреть портafiльтр (15-20 секунд). Отмерить Эспрессо кейк/кук 18-20 г в холдер, утрамбовать тампером давлением ~15 кг. Экстракция при 9 бар, температура воды 90-94 °C, время экстракции 25-30 секунд. Объем одной порции эспрессо ~30 мл. Молоко 3,2% взбить капучинатором (паровой стержень) до температуры 65 °C, микропена — однородная глянцевая текстура без крупных пузырей. Взбивать погружая сопло на 1 см ниже поверхности молока до появления микропены, затем опустить глубже для нагрева. В высокий стакан налить эспрессо (30 мл). Добавить взбитое молоко тонкой струей, перемещая кувшин для создания латте-арт. Общий объем 300-360 мл. Температура подачи 60-65 °C. Пена — тонкий слой 1-1,5 см.', 'ai', NULL, 0.012, 0, 0, 0, 0, 'технологическая карта составлена на основании акта проработки. По физико-химическим показателям соответствует требованиям ГОСТ РФ 50763-2007 "Кулинарная продукция, реализуемая населению". По микробиологическим показателям соответствует требованиям СанПиН 2.3.2 1078-01', 56);
INSERT INTO tech_cards (card_number, dish_name, organization_id, approval_date, application_area, portion_norm, technology, technology_source, serving_requirements, total_output_kg, proteins_per_100g, fats_per_100g, carbs_per_100g, calories_per_100g, note, source_page) VALUES ('03006', 'Латте S', (SELECT id FROM organizations WHERE name='Бранч'), '2021-12-22', 'Cake&Coffee', 1.000, '(от ии) В кофемашине прогреть портafiльтр (15-20 секунд). Отмерить Эспрессо кейк/кук 18-20 г в холдер, утрамбовать тампером давлением ~15 кг. Экстракция при 9 бар, температура воды 90-94 °C, время экстракции 25-30 секунд. Объем одной порции эспрессо ~30 мл. Молоко 3,2% взбить капучинатором (паровой стержень) до температуры 65 °C, микропена — однородная глянцевая текстура без крупных пузырей. Взбивать погружая сопло на 1 см ниже поверхности молока до появления микропены, затем опустить глубже для нагрева. В высокий стакан налить эспрессо (30 мл). Добавить взбитое молоко тонкой струей, перемещая кувшин для создания латте-арт. Общий объем 200-240 мл. Температура подачи 60-65 °C. Пена — тонкий слой 1-1,5 см.', 'ai', NULL, 0.012, 0, 0, 0, 0, 'технологическая карта составлена на основании акта проработки. По физико-химическим показателям соответствует требованиям ГОСТ РФ 50763-2007 "Кулинарная продукция, реализуемая населению". По микробиологическим показателям соответствует требованиям СанПиН 2.3.2 1078-01', 57);
INSERT INTO tech_cards (card_number, dish_name, organization_id, approval_date, application_area, portion_norm, technology, technology_source, serving_requirements, total_output_kg, proteins_per_100g, fats_per_100g, carbs_per_100g, calories_per_100g, note, source_page) VALUES ('02167', 'Матча латте M', (SELECT id FROM organizations WHERE name='Бранч'), '2021-12-01', 'Cake&Coffee', 1.000, '(от ии) Матча (2-3 г) просеять через мелкое сито в чашку. Добавить 30 мл воды температурой 80 °C. Взбить часенем (бамбуковым венчиком) до однородной массы без комочков — густая паста. Молоко 3,2% взбить капучинатором (паровой стержень) до температуры 65 °C, микропена — однородная глянцевая текстура без крупных пузырей. Взбивать погружая сопло на 1 см ниже поверхности молока до появления микропены, затем опустить глубже для нагрева.Долить взбитое молоко, аккуратно перемешать. Добавить Мед по вкусу. Подавать при 60-65 °C. Не использовать воду выше 80 °C — горчит.', 'ai', 'Растительное молоко', 0.369, 0, 0, 0, 0, 'технологическая карта составлена на основании акта проработки. По физико-химическим показателям соответствует требованиям ГОСТ РФ 50763-2007 "Кулинарная продукция, реализуемая населению". По микробиологическим показателям соответствует требованиям СанПиН 2.3.2 1078-01', 58);
