INSERT INTO tech_cards (card_number, dish_name, organization_id, approval_date, application_area, portion_norm, technology, technology_source, serving_requirements, total_output_kg, proteins_per_100g, fats_per_100g, carbs_per_100g, calories_per_100g, note, source_page) VALUES ('01798', 'Морковный латте S', (SELECT id FROM organizations WHERE name='Бранч'), '2019-04-19', 'Cake&Coffee', 1.000, '(от ии) В кофемашине прогреть портafiльтр (15-20 секунд). Отмерить Эспрессо кейк/кук 18-20 г в холдер, утрамбовать тампером давлением ~15 кг. Экстракция при 9 бар, температура воды 90-94 °C, время экстракции 25-30 секунд. Объем одной порции эспрессо ~30 мл. Молоко 3,2% взбить капучинатором (паровой стержень) до температуры 65 °C, микропена — однородная глянцевая текстура без крупных пузырей. Взбивать погружая сопло на 1 см ниже поверхности молока до появления микропены, затем опустить глубже для нагрева.В чашку налить Сок морковный (20-30 мл), добавить Сироп монин ваниль (10 мл). Налить эспрессо (30 мл), перемешать. Добавить взбитое молоко. Подавать при 60-65 °C.', 'ai', NULL, 0.205, 0, 0, 0, 0, 'технологическая карта составлена на основании акта проработки. По физико-химическим показателям соответствует требованиям ГОСТ РФ 50763-2007 "Кулинарная продукция, реализуемая населению". По микробиологическим показателям соответствует требованиям СанПиН 2.3.2 1078-01', 60);
