INSERT INTO tech_cards (card_number, dish_name, organization_id, approval_date, application_area, portion_norm, technology, technology_source, serving_requirements, total_output_kg, proteins_per_100g, fats_per_100g, carbs_per_100g, calories_per_100g, note, source_page) VALUES ('00094', 'Соленая карамель size S', (SELECT id FROM organizations WHERE name='Бранч'), '2019-04-19', 'Cake&Coffee', 1.000, '(от ии) В кофемашине прогреть портafiльтр (15-20 секунд). Отмерить Эспрессо кейк/кук 18-20 г в холдер, утрамбовать тампером давлением ~15 кг. Экстракция при 9 бар, температура воды 90-94 °C, время экстракции 25-30 секунд. Объем одной порции эспрессо ~30 мл. Молоко 3,2% взбить капучинатором (паровой стержень) до температуры 65 °C, микропена — однородная глянцевая текстура без крупных пузырей. Взбивать погружая сопло на 1 см ниже поверхности молока до появления микропены, затем опустить глубже для нагрева.В чашку налить Сироп карамель, добавить щепотку Соль морская. Налить эспрессо (30 мл), перемешать. Добавить взбитое молоко. Температура подачи 60-65 °C.', 'ai', NULL, 0.27, 0, 0, 0, 0, 'технологическая карта составлена на основании акта проработки. По физико-химическим показателям соответствует требованиям ГОСТ РФ 50763-2007 "Кулинарная продукция, реализуемая населению". По микробиологическим показателям соответствует требованиям СанПиН 2.3.2 1078-01', 65);
INSERT INTO tech_cards (card_number, dish_name, organization_id, approval_date, application_area, portion_norm, technology, technology_source, serving_requirements, total_output_kg, proteins_per_100g, fats_per_100g, carbs_per_100g, calories_per_100g, note, source_page) VALUES ('03172', 'Флэт', (SELECT id FROM organizations WHERE name='Бранч'), '2022-06-14', 'Cake&Coffee', 1.000, '(от ии) Приготовить двойной эспрессо (Доппио, 18-20 г кофе, 90-94 °C, 9 бар, 25-30 сек, ~60 мл). Молоко 3,2% взбить микропеной до 60-65 °C — более плотная и мелкая пена, чем для капучино. В чашку налить эспрессо, добавить молоко с микропеной. Объем ~200-220 мл. Температура подачи 60-65 °C. Соотношение кофе к молоку выше, чем в латте.', 'ai', NULL, 0.23, 0, 0, 0, 0, 'технологическая карта составлена на основании акта проработки. По физико-химическим показателям соответствует требованиям ГОСТ РФ 50763-2007 "Кулинарная продукция, реализуемая населению". По микробиологическим показателям соответствует требованиям СанПиН 2.3.2 1078-01', 66);
INSERT INTO tech_cards (card_number, dish_name, organization_id, approval_date, application_area, portion_norm, technology, technology_source, serving_requirements, total_output_kg, proteins_per_100g, fats_per_100g, carbs_per_100g, calories_per_100g, note, source_page) VALUES ('00097', 'Эспрессо', (SELECT id FROM organizations WHERE name='Бранч'), '2020-12-15', 'Cake&Coffee', 1.000, '(от ии) В кофемашине прогреть портafiльтр (15-20 секунд). Отмерить Эспрессо кейк/кук 18-20 г в холдер, утрамбовать тампером давлением ~15 кг. Экстракция при 9 бар, температура воды 90-94 °C, время экстракции 25-30 секунд. Объем одной порции эспрессо ~30 мл. Подавать в подогретой чашке эспрессо (60-80 мл) при температуре 65-70 °C. Время подачи — не более 30 секунд после экстракции.', 'ai', NULL, 0.012, 1, 1, 1, 11, 'технологическая карта составлена на основании акта проработки. По физико-химическим показателям соответствует требованиям ГОСТ РФ 50763-2007 "Кулинарная продукция, реализуемая населению". По микробиологическим показателям соответствует требованиям СанПиН 2.3.2 1078-01', 67);
INSERT INTO tech_cards (card_number, dish_name, organization_id, approval_date, application_area, portion_norm, technology, technology_source, serving_requirements, total_output_kg, proteins_per_100g, fats_per_100g, carbs_per_100g, calories_per_100g, note, source_page) VALUES ('01083', 'Морс ягодный 1 литр', (SELECT id FROM organizations WHERE name='Бранч'), '2020-12-04', 'Cake&Coffee', 1.000, '(от ии) Ягодный морс (готовый) налить в кувшин. При подаче — разлить в стаканы со Лед. Подавать при 8-12 °C. При желании добавить свежие ягоды для украшения.', 'ai', NULL, 1.0, 0, 0, 0, 0, 'технологическая карта составлена на основании акта проработки. По физико-химическим показателям соответствует требованиям ГОСТ РФ 50763-2007 "Кулинарная продукция, реализуемая населению". По микробиологическим показателям соответствует требованиям СанПиН 2.3.2 1078-01', 68);
INSERT INTO tech_cards (card_number, dish_name, organization_id, approval_date, application_area, portion_norm, technology, technology_source, serving_requirements, total_output_kg, proteins_per_100g, fats_per_100g, carbs_per_100g, calories_per_100g, note, source_page) VALUES ('01089', 'Ягодный морс стакан', (SELECT id FROM organizations WHERE name='Бранч'), '2017-12-23', 'Cake&Coffee', 1.000, '(от ии) Ягодный морс налить в стакан, добавить Лед (2-3 кубика). Подавать при 8-12 °C.', 'ai', NULL, 0.3125, 0, 0, 0, 0, 'технологическая карта составлена на основании акта проработки. По физико-химическим показателям соответствует требованиям ГОСТ РФ 50763-2007 "Кулинарная продукция, реализуемая населению". По микробиологическим показателям соответствует требованиям СанПиН 2.3.2 1078-01', 69);
INSERT INTO tech_cards (card_number, dish_name, organization_id, approval_date, application_area, portion_norm, technology, technology_source, serving_requirements, total_output_kg, proteins_per_100g, fats_per_100g, carbs_per_100g, calories_per_100g, note, source_page) VALUES ('00082', 'Мол. кок. клубничный', (SELECT id FROM organizations WHERE name='Бранч'), '2018-05-03', 'Cake&Coffee', 1.000, '(от ии) В блендер положить 2 шарика Мороженое (по 50 г). Добавить Молоко 3,2% (100-120 мл). Добавить Сироп Hersheys (клубничный, 20 мл). Взбивать на высокой скорости 20-30 секунд до однородной массы. Разлить в высокий стакан со Лед (по желанию). Подавать при 2-5 °C с трубочкой.', 'ai', 'клубничный', 0.28, 4, 14, 21, 226, 'технологическая карта составлена на основании акта проработки. По физико-химическим показателям соответствует требованиям ГОСТ РФ 50763-2007 "Кулинарная продукция, реализуемая населению". По микробиологическим показателям соответствует требованиям СанПиН 2.3.2 1078-01', 70);
INSERT INTO tech_cards (card_number, dish_name, organization_id, approval_date, application_area, portion_norm, technology, technology_source, serving_requirements, total_output_kg, proteins_per_100g, fats_per_100g, carbs_per_100g, calories_per_100g, note, source_page) VALUES ('00083', 'Мол. кок. шоколадный', (SELECT id FROM organizations WHERE name='Бранч'), '2019-07-31', 'Cake&Coffee', 1.000, '(от ии) В блендер положить 2 шарика Мороженое (по 50 г). Добавить Молоко 3,2% (100-120 мл). Добавить Сироп Hersheys (шоколадный, 20 мл). Взбивать на высокой скорости 20-30 секунд до однородной массы. Разлить в высокий стакан со Лед (по желанию). Подавать при 2-5 °C с трубочкой.', 'ai', 'шоколадный', 0.26, 4, 13, 18, 204, 'технологическая карта составлена на основании акта проработки. По физико-химическим показателям соответствует требованиям ГОСТ РФ 50763-2007 "Кулинарная продукция, реализуемая населению". По микробиологическим показателям соответствует требованиям СанПиН 2.3.2 1078-01', 71);
INSERT INTO tech_cards (card_number, dish_name, organization_id, approval_date, application_area, portion_norm, technology, technology_source, serving_requirements, total_output_kg, proteins_per_100g, fats_per_100g, carbs_per_100g, calories_per_100g, note, source_page) VALUES ('00080', 'Мол.кок. банановый', (SELECT id FROM organizations WHERE name='Бранч'), '2017-12-16', 'Cake&Coffee', 1.000, '(от ии) В блендер положить 2 шарика Мороженое (по 50 г). Добавить Молоко 3,2% (100-120 мл). Бананы (половину, ~50 г) нарезать кусочками, заморозить заранее. Взбивать на высокой скорости 20-30 секунд до однородной массы. Разлить в высокий стакан со Лед (по желанию). Подавать при 2-5 °C с трубочкой.', 'ai', NULL, 0.32, 4, 10, 23, 193, 'технологическая карта составлена на основании акта проработки. По физико-химическим показателям соответствует требованиям ГОСТ РФ 50763-2007 "Кулинарная продукция, реализуемая населению". По микробиологическим показателям соответствует требованиям СанПиН 2.3.2 1078-01', 72);
INSERT INTO tech_cards (card_number, dish_name, organization_id, approval_date, application_area, portion_norm, technology, technology_source, serving_requirements, total_output_kg, proteins_per_100g, fats_per_100g, carbs_per_100g, calories_per_100g, note, source_page) VALUES ('00079', 'Молочный классический', (SELECT id FROM organizations WHERE name='Бранч'), '2017-12-16', 'Cake&Coffee', 1.000, '(от ии) В блендер положить 2 шарика Мороженое (по 50 г). Добавить Молоко 3,2% (100-120 мл). Без добавок — классический ванильный. Взбивать на высокой скорости 20-30 секунд до однородной массы. Разлить в высокий стакан со Лед (по желанию). Подавать при 2-5 °C с трубочкой.', 'ai', NULL, 0.25, 4, 14, 20, 224, 'технологическая карта составлена на основании акта проработки. По физико-химическим показателям соответствует требованиям ГОСТ РФ 50763-2007 "Кулинарная продукция, реализуемая населению". По микробиологическим показателям соответствует требованиям СанПиН 2.3.2 1078-01', 73);
INSERT INTO tech_cards (card_number, dish_name, organization_id, approval_date, application_area, portion_norm, technology, technology_source, serving_requirements, total_output_kg, proteins_per_100g, fats_per_100g, carbs_per_100g, calories_per_100g, note, source_page) VALUES ('00084', 'Молочный кок. с Орео', (SELECT id FROM organizations WHERE name='Бранч'), '2017-12-16', 'Cake&Coffee', 1.000, '(от ии) В блендер положить 2 шарика Мороженое (по 50 г). Добавить Молоко 3,2% (100-120 мл). Печенье Орео (2-3 штуки) поломать на кусочки, добавить в блендер. Взбивать на высокой скорости 20-30 секунд до однородной массы. Разлить в высокий стакан со Лед (по желанию). Подавать при 2-5 °C с трубочкой.', 'ai', 'Посыпка кондитерская', 0.32, 0, 0, 0, 0, 'технологическая карта составлена на основании акта проработки. По физико-химическим показателям соответствует требованиям ГОСТ РФ 50763-2007 "Кулинарная продукция, реализуемая населению". По микробиологическим показателям соответствует требованиям СанПиН 2.3.2 1078-01', 74);
INSERT INTO tech_cards (card_number, dish_name, organization_id, approval_date, application_area, portion_norm, technology, technology_source, serving_requirements, total_output_kg, proteins_per_100g, fats_per_100g, carbs_per_100g, calories_per_100g, note, source_page) VALUES ('01060', 'Апельсин-грейпфрут', (SELECT id FROM organizations WHERE name='Бранч'), '2016-12-27', 'Cake&Coffee', 1.000, '(от ии) Подготовить Апельсин и Грейпфрут (помыть, при необходимости очистить). Апельсины (2 шт.) и Грейпфрут (1 шт.) разрезать пополам, выжать сок. Пропустить через шнековую соковыжималку (или центробежную) при комнатной температуре. Сразу разлить в стакан со Лед. Подавать немедленно при 3-8 °C. Сок хранить не более 5 минут.', 'ai', NULL, 0.35, 0, 0, 0, 0, 'технологическая карта составлена на основании акта проработки. По физико-химическим показателям соответствует требованиям ГОСТ РФ 50763-2007 "Кулинарная продукция, реализуемая населению". По микробиологическим показателям соответствует требованиям СанПиН 2.3.2 1078-01', 75);
INSERT INTO tech_cards (card_number, dish_name, organization_id, approval_date, application_area, portion_norm, technology, technology_source, serving_requirements, total_output_kg, proteins_per_100g, fats_per_100g, carbs_per_100g, calories_per_100g, note, source_page) VALUES ('00068', 'Апельсиновый', (SELECT id FROM organizations WHERE name='Бранч'), '2016-09-12', 'Cake&Coffee', 1.000, '(от ии) Подготовить Апельсин (2-3 шт.) (помыть, при необходимости очистить). Разрезать пополам, выжать сок. Пропустить через шнековую соковыжималку (или центробежную) при комнатной температуре. Сразу разлить в стакан со Лед. Подавать немедленно при 3-8 °C. Сок хранить не более 5 минут.', 'ai', NULL, 0.37, 1, 0, 8, 38, 'технологическая карта составлена на основании акта проработки. По физико-химическим показателям соответствует требованиям ГОСТ РФ 50763-2007 "Кулинарная продукция, реализуемая населению". По микробиологическим показателям соответствует требованиям СанПиН 2.3.2 1078-01', 76);
INSERT INTO tech_cards (card_number, dish_name, organization_id, approval_date, application_area, portion_norm, technology, technology_source, serving_requirements, total_output_kg, proteins_per_100g, fats_per_100g, carbs_per_100g, calories_per_100g, note, source_page) VALUES ('01061', 'Апельсин-яблоко', (SELECT id FROM organizations WHERE name='Бранч'), '2016-12-27', 'Cake&Coffee', 1.000, '(от ии) Подготовить Яблоки и Апельсин (помыть, при необходимости очистить). Яблоки (1-2 шт.) нарезать дольками, удалить семена. Апельсин (1 шт.) разрезать пополам. Пропустить через шнековую соковыжималку (или центробежную) при комнатной температуре. Сразу разлить в стакан со Лед. Подавать немедленно при 3-8 °C. Сок хранить не более 5 минут.', 'ai', NULL, 0.35, 0, 0, 0, 0, 'технологическая карта составлена на основании акта проработки. По физико-химическим показателям соответствует требованиям ГОСТ РФ 50763-2007 "Кулинарная продукция, реализуемая населению". По микробиологическим показателям соответствует требованиям СанПиН 2.3.2 1078-01', 77);
INSERT INTO tech_cards (card_number, dish_name, organization_id, approval_date, application_area, portion_norm, technology, technology_source, serving_requirements, total_output_kg, proteins_per_100g, fats_per_100g, carbs_per_100g, calories_per_100g, note, source_page) VALUES ('00071', 'Грейпфрутовый', (SELECT id FROM organizations WHERE name='Бранч'), '2018-11-30', 'Cake&Coffee', 1.000, '(от ии) Подготовить Грейпфрут (2 шт.) (помыть, при необходимости очистить). Разрезать пополам, выжать сок. Процедить через ситечко для удаления косточек. Пропустить через шнековую соковыжималку (или центробежную) при комнатной температуре. Сразу разлить в стакан со Лед. Подавать немедленно при 3-8 °C. Сок хранить не более 5 минут.', 'ai', NULL, 0.2846, 1, 0, 5, 24, 'технологическая карта составлена на основании акта проработки. По физико-химическим показателям соответствует требованиям ГОСТ РФ 50763-2007 "Кулинарная продукция, реализуемая населению". По микробиологическим показателям соответствует требованиям СанПиН 2.3.2 1078-01', 78);
INSERT INTO tech_cards (card_number, dish_name, organization_id, approval_date, application_area, portion_norm, technology, technology_source, serving_requirements, total_output_kg, proteins_per_100g, fats_per_100g, carbs_per_100g, calories_per_100g, note, source_page) VALUES ('00075', 'Микс', (SELECT id FROM organizations WHERE name='Бранч'), '2016-09-12', 'Cake&Coffee', 1.000, '(от ии) Свежевыжатый сок-микс из доступных сезонных фруктов и овощей. Подготовить ингредиенты, пропустить через соковыжималку. Сразу подавать при 3-8 °C.', 'ai', NULL, 0.0, 0, 0, 0, 0, 'технологическая карта составлена на основании акта проработки. По физико-химическим показателям соответствует требованиям ГОСТ РФ 50763-2007 "Кулинарная продукция, реализуемая населению". По микробиологическим показателям соответствует требованиям СанПиН 2.3.2 1078-01', 79);
INSERT INTO tech_cards (card_number, dish_name, organization_id, approval_date, application_area, portion_norm, technology, technology_source, serving_requirements, total_output_kg, proteins_per_100g, fats_per_100g, carbs_per_100g, calories_per_100g, note, source_page) VALUES ('00070', 'Морковный', (SELECT id FROM organizations WHERE name='Бранч'), '2016-09-12', 'Cake&Coffee', 1.000, '(от ии) Подготовить Морковь (3-4 шт.) (помыть, при необходимости очистить). Очистить, нарезать брусочками. Пропустить через соковыжималку. Пропустить через шнековую соковыжималку (или центробежную) при комнатной температуре. Сразу разлить в стакан со Лед. Подавать немедленно при 3-8 °C. Сок хранить не более 5 минут.', 'ai', NULL, 0.37, 1, 0, 7, 34, 'технологическая карта составлена на основании акта проработки. По физико-химическим показателям соответствует требованиям ГОСТ РФ 50763-2007 "Кулинарная продукция, реализуемая населению". По микробиологическим показателям соответствует требованиям СанПиН 2.3.2 1078-01', 80);
INSERT INTO tech_cards (card_number, dish_name, organization_id, approval_date, application_area, portion_norm, technology, technology_source, serving_requirements, total_output_kg, proteins_per_100g, fats_per_100g, carbs_per_100g, calories_per_100g, note, source_page) VALUES ('00072', 'Яблоко-морковь', (SELECT id FROM organizations WHERE name='Бранч'), '2016-09-12', 'Cake&Coffee', 1.000, '(от ии) Подготовить Яблоки и Морковь (помыть, при необходимости очистить). Морковь (2 шт.) очистить, нарезать. Яблоко (1 шт.) нарезать дольками, удалить семена. Чередовать в соковыжималке. Пропустить через шнековую соковыжималку (или центробежную) при комнатной температуре. Сразу разлить в стакан со Лед. Подавать немедленно при 3-8 °C. Сок хранить не более 5 минут.', 'ai', NULL, 0.35, 0, 0, 0, 0, 'технологическая карта составлена на основании акта проработки. По физико-химическим показателям соответствует требованиям ГОСТ РФ 50763-2007 "Кулинарная продукция, реализуемая населению". По микробиологическим показателям соответствует требованиям СанПиН 2.3.2 1078-01', 81);
INSERT INTO tech_cards (card_number, dish_name, organization_id, approval_date, application_area, portion_norm, technology, technology_source, serving_requirements, total_output_kg, proteins_per_100g, fats_per_100g, carbs_per_100g, calories_per_100g, note, source_page) VALUES ('02476', 'Яблоко-сельдерей', (SELECT id FROM organizations WHERE name='Бранч'), '2020-05-18', 'Cake&Coffee', 1.000, '(от ии) Подготовить Яблоки и Сельдерей стебель (помыть, при необходимости очистить). Яблоко (1 шт.) нарезать дольками. Сельдерей стебель (2-3 шт.) нарезать. Пропустить через шнековую соковыжималку (или центробежную) при комнатной температуре. Сразу разлить в стакан со Лед. Подавать немедленно при 3-8 °C. Сок хранить не более 5 минут.', 'ai', NULL, 0.55, 0, 0, 0, 0, 'технологическая карта составлена на основании акта проработки. По физико-химическим показателям соответствует требованиям ГОСТ РФ 50763-2007 "Кулинарная продукция, реализуемая населению". По микробиологическим показателям соответствует требованиям СанПиН 2.3.2 1078-01', 82);
INSERT INTO tech_cards (card_number, dish_name, organization_id, approval_date, application_area, portion_norm, technology, technology_source, serving_requirements, total_output_kg, proteins_per_100g, fats_per_100g, carbs_per_100g, calories_per_100g, note, source_page) VALUES ('00069', 'Яблочный', (SELECT id FROM organizations WHERE name='Бранч'), '2016-09-12', 'Cake&Coffee', 1.000, '(от ии) Подготовить Яблоки (2-3 шт.) (помыть, при необходимости очистить). Нарезать дольками, удалить семечки. Пропустить через шнековую соковыжималку (или центробежную) при комнатной температуре. Сразу разлить в стакан со Лед. Подавать немедленно при 3-8 °C. Сок хранить не более 5 минут.', 'ai', NULL, 0.37, 0, 0, 10, 44, 'технологическая карта составлена на основании акта проработки. По физико-химическим показателям соответствует требованиям ГОСТ РФ 50763-2007 "Кулинарная продукция, реализуемая населению". По микробиологическим показателям соответствует требованиям СанПиН 2.3.2 1078-01', 83);
INSERT INTO tech_cards (card_number, dish_name, organization_id, approval_date, application_area, portion_norm, technology, technology_source, serving_requirements, total_output_kg, proteins_per_100g, fats_per_100g, carbs_per_100g, calories_per_100g, note, source_page) VALUES ('03171', 'Айс-латте', (SELECT id FROM organizations WHERE name='Бранч'), '2022-06-14', 'Cake&Coffee', 1.000, '(от ии) В кофемашине прогреть портafiльтр (15-20 секунд). Отмерить Эспрессо кейк/кук 18-20 г в холдер, утрамбовать тампером давлением ~15 кг. Экстракция при 9 бар, температура воды 90-94 °C, время экстракции 25-30 секунд. Объем одной порции эспрессо ~30 мл.В высокий стакан наполнить Лед на 2/3 объема. Налить холодное Молоко 3,2% (100-120 мл). Аккуратно сверху налить эспрессо (30 мл) — образуется слой. Подавать с трубочкой при 3-8 °C.', 'ai', NULL, 0.24, 0, 0, 0, 0, 'технологическая карта составлена на основании акта проработки. По физико-химическим показателям соответствует требованиям ГОСТ РФ 50763-2007 "Кулинарная продукция, реализуемая населению". По микробиологическим показателям соответствует требованиям СанПиН 2.3.2 1078-01', 84);
INSERT INTO tech_cards (card_number, dish_name, organization_id, approval_date, application_area, portion_norm, technology, technology_source, serving_requirements, total_output_kg, proteins_per_100g, fats_per_100g, carbs_per_100g, calories_per_100g, note, source_page) VALUES ('00064', 'Апельсиновый лимонад', (SELECT id FROM organizations WHERE name='Бранч'), '2022-06-15', 'Cake&Coffee', 1.000, '(от ии) Апельсин (1 шт.) нарезать кружочками, выдавить сок. Лимон (половину) нарезать дольками. Мята (3-4 веточки) помять мадлером. Добавить Сахарный сироп (30 мл), сок апельсина, Лед в шейкер. Взбить 10-15 секунд. Процедить в высокий стакан. Украсить дольками апельсина и лимона, веточкой мяты. Подавать при 3-8 °C.', 'ai', 'Аква минерале розлив', 0.145, 0, 0, 0, 0, 'технологическая карта составлена на основании акта проработки. По физико-химическим показателям соответствует требованиям ГОСТ РФ 50763-2007 "Кулинарная продукция, реализуемая населению". По микробиологическим показателям соответствует требованиям СанПиН 2.3.2 1078-01', 85);
INSERT INTO tech_cards (card_number, dish_name, organization_id, approval_date, application_area, portion_norm, technology, technology_source, serving_requirements, total_output_kg, proteins_per_100g, fats_per_100g, carbs_per_100g, calories_per_100g, note, source_page) VALUES ('00065', 'Лимонад классический', (SELECT id FROM organizations WHERE name='Бранч'), '2022-06-15', 'Cake&Coffee', 1.000, '(от ии) Лимон (1 шт.) нарезать кружочками, выдавить сок в шейкер. Добавить Мята (3-4 веточки), слегка помять мадлером для выделения аромата. Добавить Сахарный сироп (30 мл) и Лед (до верха шейкера). Взбить шейкером 10-15 секунд. Процедить в высокий стакан через ситечко. Долить газированной водой до верха. Украсить веточкой мяты и кружочком лимона. Подавать при 3-8 °C.', 'ai', 'Аква минерале розлив', 0.095, 0, 0, 0, 0, 'технологическая карта составлена на основании акта проработки. По физико-химическим показателям соответствует требованиям ГОСТ РФ 50763-2007 "Кулинарная продукция, реализуемая населению". По микробиологическим показателям соответствует требованиям СанПиН 2.3.2 1078-01', 86);
INSERT INTO tech_cards (card_number, dish_name, organization_id, approval_date, application_area, portion_norm, technology, technology_source, serving_requirements, total_output_kg, proteins_per_100g, fats_per_100g, carbs_per_100g, calories_per_100g, note, source_page) VALUES ('03245', 'Морс облепиха бут.', (SELECT id FROM organizations WHERE name='Бранч'), '2022-10-27', 'Cake&Coffee', 1.000, '(от ии) Морс облепиха (готовый, бутылочный) — открыть бутылку, разлить в стакан со Лед. Подавать при 8-12 °C.', 'ai', NULL, 0.25, 0, 0, 0, 0, 'технологическая карта составлена на основании акта проработки. По физико-химическим показателям соответствует требованиям ГОСТ РФ 50763-2007 "Кулинарная продукция, реализуемая населению". По микробиологическим показателям соответствует требованиям СанПиН 2.3.2 1078-01', 87);
INSERT INTO tech_cards (card_number, dish_name, organization_id, approval_date, application_area, portion_norm, technology, technology_source, serving_requirements, total_output_kg, proteins_per_100g, fats_per_100g, carbs_per_100g, calories_per_100g, note, source_page) VALUES ('03246', 'Морс смородина бут.', (SELECT id FROM organizations WHERE name='Бранч'), '2022-10-27', 'Cake&Coffee', 1.000, '(от ии) Морс смородина (готовый, бутылочный) — открыть бутылку, разлить в стакан со Лед. Подавать при 8-12 °C.', 'ai', NULL, 0.25, 0, 0, 0, 0, 'технологическая карта составлена на основании акта проработки. По физико-химическим показателям соответствует требованиям ГОСТ РФ 50763-2007 "Кулинарная продукция, реализуемая населению". По микробиологическим показателям соответствует требованиям СанПиН 2.3.2 1078-01', 88);
INSERT INTO tech_cards (card_number, dish_name, organization_id, approval_date, application_area, portion_norm, technology, technology_source, serving_requirements, total_output_kg, proteins_per_100g, fats_per_100g, carbs_per_100g, calories_per_100g, note, source_page) VALUES ('01361', 'Мохито', (SELECT id FROM organizations WHERE name='Бранч'), '2022-06-15', 'Cake&Coffee', 1.000, '(от ии) Лайм (1 шт.) нарезать на дольки (4-6 частей). Поместить в стакан, добавить Сахарный сироп (20 мл), помять мадлером до выделения сока. Мята (5-6 веточек) слегка похлопать мадлером — не разминая полностью, чтобы не горчило. Заполнить стакан Лед доверху. Долить Аква минерале (газированная вода, 200 мл). Перемешать барной ложкой, подняв лед вверх. Украсить веточкой мяты. Подавать при 3-8 °C.', 'ai', 'розлив', 0.108, 0, 0, 0, 0, 'технологическая карта составлена на основании акта проработки. По физико-химическим показателям соответствует требованиям ГОСТ РФ 50763-2007 "Кулинарная продукция, реализуемая населению". По микробиологическим показателям соответствует требованиям СанПиН 2.3.2 1078-01', 89);
INSERT INTO tech_cards (card_number, dish_name, organization_id, approval_date, application_area, portion_norm, technology, technology_source, serving_requirements, total_output_kg, proteins_per_100g, fats_per_100g, carbs_per_100g, calories_per_100g, note, source_page) VALUES ('03252', 'Стакан воды', (SELECT id FROM organizations WHERE name='Бранч'), '2022-11-07', 'Cake&Coffee', 1.000, '(от ии) Вода в бутылке подать в стакане со Лед по запросу. Температура хранения 2-6 °C.', 'ai', NULL, 0.0, 0, 0, 0, 0, 'технологическая карта составлена на основании акта проработки. По физико-химическим показателям соответствует требованиям ГОСТ РФ 50763-2007 "Кулинарная продукция, реализуемая населению". По микробиологическим показателям соответствует требованиям СанПиН 2.3.2 1078-01', 90);
INSERT INTO tech_cards (card_number, dish_name, organization_id, approval_date, application_area, portion_norm, technology, technology_source, serving_requirements, total_output_kg, proteins_per_100g, fats_per_100g, carbs_per_100g, calories_per_100g, note, source_page) VALUES ('00673', 'Стакан молока', (SELECT id FROM organizations WHERE name='Бранч'), '2023-04-11', 'Cake&Coffee', 1.000, '(от ии) Молоко 3,2% подать в стакане, подогретое до 40-45 °C или холодным (2-6 °C) — по запросу гостя.', 'ai', NULL, 0.25, 0, 0, 0, 0, 'технологическая карта составлена на основании акта проработки. По физико-химическим показателям соответствует требованиям ГОСТ РФ 50763-2007 "Кулинарная продукция, реализуемая населению". По микробиологическим показателям соответствует требованиям СанПиН 2.3.2 1078-01', 91);
INSERT INTO tech_cards (card_number, dish_name, organization_id, approval_date, application_area, portion_norm, technology, technology_source, serving_requirements, total_output_kg, proteins_per_100g, fats_per_100g, carbs_per_100g, calories_per_100g, note, source_page) VALUES ('03173', 'Эспрессо-тоник', (SELECT id FROM organizations WHERE name='Бранч'), '2022-06-14', 'Cake&Coffee', 1.000, '(от ии) В кофемашине прогреть портafiльтр (15-20 секунд). Отмерить Эспрессо кейк/кук 18-20 г в холдер, утрамбовать тампером давлением ~15 кг. Экстракция при 9 бар, температура воды 90-94 °C, время экстракции 25-30 секунд. Объем одной порции эспрессо ~30 мл.В высокий стакан наполнить Лед на 2/3. Налить Швепс (тоник, 100-120 мл). Сверху аккуратно налить эспрессо (30 мл). Подавать с трубочкой при 3-8 °C. Слои не перемешивать перед подачей.', 'ai', NULL, 0.08, 0, 0, 0, 0, 'технологическая карта составлена на основании акта проработки. По физико-химическим показателям соответствует требованиям ГОСТ РФ 50763-2007 "Кулинарная продукция, реализуемая населению". По микробиологическим показателям соответствует требованиям СанПиН 2.3.2 1078-01', 92);
INSERT INTO tech_cards (card_number, dish_name, organization_id, approval_date, application_area, portion_norm, technology, technology_source, serving_requirements, total_output_kg, proteins_per_100g, fats_per_100g, carbs_per_100g, calories_per_100g, note, source_page) VALUES ('03389', 'Бенедикт с индейкой', (SELECT id FROM organizations WHERE name='Бранч'), '2023-02-06', 'Cake&Coffee', 1.000, 'Бриошь обжарить на сливочном масле, на кремера маленькую тарелку выложить бриошь, полить зеленым маслом и посыпать', 'original', NULL, 0.2, 0, 0, 0, 0, 'технологическая карта составлена на основании акта проработки. По физико-химическим показателям соответствует требованиям ГОСТ РФ 50763-2007 "Кулинарная продукция, реализуемая населению". По микробиологическим показателям соответствует требованиям СанПиН 2.3.2 1078-01', 93);
INSERT INTO tech_cards (card_number, dish_name, organization_id, approval_date, application_area, portion_norm, technology, technology_source, serving_requirements, total_output_kg, proteins_per_100g, fats_per_100g, carbs_per_100g, calories_per_100g, note, source_page) VALUES ('03516', 'Бенедикт с лососем', (SELECT id FROM organizations WHERE name='Бранч'), '2023-04-30', 'Cake&Coffee', 1.000, 'Бриошь обжарить на сливочном масле, на кремера маленькую тарелку выложить бриошь,лосось, яйцо, голландез, полить зеленым маслом и посыпать сушеным', 'original', NULL, 0.2353, 0, 0, 0, 0, 'технологическая карта составлена на основании акта проработки. По физико-химическим показателям соответствует требованиям ГОСТ РФ 50763-2007 "Кулинарная продукция, реализуемая населению". По микробиологическим показателям соответствует требованиям СанПиН 2.3.2 1078-01', 94);
INSERT INTO tech_cards (card_number, dish_name, organization_id, approval_date, application_area, portion_norm, technology, technology_source, serving_requirements, total_output_kg, proteins_per_100g, fats_per_100g, carbs_per_100g, calories_per_100g, note, source_page) VALUES ('03515', 'Бенедикт с пармой', (SELECT id FROM organizations WHERE name='Бранч'), '2023-04-30', 'Cake&Coffee', 1.000, 'Бриошь обжарить на сливочном масле, на маленькую тарелку выложить бриошь, пармскую ветчину, яйцо, голландез, полить кремера зеленым маслом и посыпать сушеным', 'original', NULL, 0.2203, 0, 0, 0, 0, 'технологическая карта составлена на основании акта проработки. По физико-химическим показателям соответствует требованиям ГОСТ РФ 50763-2007 "Кулинарная продукция, реализуемая населению". По микробиологическим показателям соответствует требованиям СанПиН 2.3.2 1078-01', 95);
INSERT INTO tech_cards (card_number, dish_name, organization_id, approval_date, application_area, portion_norm, technology, technology_source, serving_requirements, total_output_kg, proteins_per_100g, fats_per_100g, carbs_per_100g, calories_per_100g, note, source_page) VALUES ('03372', 'Бриошь с мороженым и карамелью', (SELECT id FROM organizations WHERE name='Бранч'), '2023-01-21', 'Cake&Coffee', 1.000, '(от ии) Тесто Бриошь разрезать пополам горизонтально. Разогреть сковороду, растопить Масло сливочное (10 г) на среднем огне (160-170 °C). Обжарить нижнюю половину бриоши срезом вниз 1-2 минуты до золотистого цвета. Перевернуть, обжарить 1 минуту. Аналогично обжарить верхнюю половину. На поджаренную нижнюю половину выложить шарик Мороженое (1-2 шарика). Полить карамельным соусом. Посыпать рублеными Фундук и Фисташки. Накрыть верхней половиной. Подавать немедленно.', 'ai', 'Глазурь Карамельная', 0.185, 0, 0, 0, 0, 'технологическая карта составлена на основании акта проработки. По физико-химическим показателям соответствует требованиям ГОСТ РФ 50763-2007 "Кулинарная продукция, реализуемая населению". По микробиологическим показателям соответствует требованиям СанПиН 2.3.2 1078-01', 96);
INSERT INTO tech_cards (card_number, dish_name, organization_id, approval_date, application_area, portion_norm, technology, technology_source, serving_requirements, total_output_kg, proteins_per_100g, fats_per_100g, carbs_per_100g, calories_per_100g, note, source_page) VALUES ('03373', 'Бриошь с прошутто и спаржей', (SELECT id FROM organizations WHERE name='Бранч'), '2023-01-21', 'Cake&Coffee', 1.000, '(от ии) Тесто Бриошь разрезать пополам. Масло сливочное (10 г) растопить на сковороде, 160-170 °C. Обжарить половинки бриоши с обеих сторон до золотистого цвета, по 1-2 минуты каждой стороной. Спаржа заморозка (30 г) — отварить в кипящей подсоленной воде 3-4 минуты, откинуть на дуршлаг. Шпинат свежий (20 г) бланшировать 30 секунд в кипятке, отжать. Яйцо куриное — приготовить пашот: в кипящую воду с добавлением уксуса (1 ст.л.) создать воронку, аккуратно влить яйцо, варить 3-3,5 минуты при 90-95 °C. На нижнюю половину бриоши выложить шпинат, затем спаржу, сверху — яйцо пашот. Накрыть верхней половиной. Подавать при 60-65 °C.', 'ai', 'Сыровяленная свинина Горчично-медовая завправка', 0.24, 0, 0, 0, 0, 'технологическая карта составлена на основании акта проработки. По физико-химическим показателям соответствует требованиям ГОСТ РФ 50763-2007 "Кулинарная продукция, реализуемая населению". По микробиологическим показателям соответствует требованиям СанПиН 2.3.2 1078-01', 97);
INSERT INTO tech_cards (card_number, dish_name, organization_id, approval_date, application_area, portion_norm, technology, technology_source, serving_requirements, total_output_kg, proteins_per_100g, fats_per_100g, carbs_per_100g, calories_per_100g, note, source_page) VALUES ('03178', 'Брускетта с ростбифом на бородинском хлебе', (SELECT id FROM organizations WHERE name='Бранч'), '2022-07-04', 'Cake&Coffee', 1.000, 'Кусочек бородинского хлеба подсушить на маслом. Ростбиф нарезать тонкими томаты мелко нарезать. Палочки укропа нарезать колечками, залить зеленым маслом.', 'original', 'На десертную тарелку нанести немного чесночного крема, на крем положить хлеб, что бы он не катался по тарелке. На хлеб объемно ростбиф, отсадить на ростбиф томаты и колечки укропа, сбрызнуть перцем при необходимости.', 0.15, 0, 0, 0, 0, 'технологическая карта составлена на основании акта проработки. По физико-химическим показателям соответствует требованиям ГОСТ РФ 50763-2007 "Кулинарная продукция, реализуемая населению". По микробиологическим показателям соответствует требованиям СанПиН 2.3.2 1078-01', 98);
INSERT INTO tech_cards (card_number, dish_name, organization_id, approval_date, application_area, portion_norm, technology, technology_source, serving_requirements, total_output_kg, proteins_per_100g, fats_per_100g, carbs_per_100g, calories_per_100g, note, source_page) VALUES ('03286', 'Будда боул', (SELECT id FROM organizations WHERE name='Бранч'), '2022-11-22', 'Cake&Coffee', 1.000, 'С краю тарелки положить два квадратика нори, на дно тарелки выложить киноа, рядом отсадить морковный хумус, рядом выложить огурцы, чукку, черри половинки. По середине положить половинку яйца в смятку, посыпать его семенами чиа и полить соусом унаги. украсить луком фото в чате.', 'original', NULL, 0.252, 0, 0, 0, 0, 'технологическая карта составлена на основании акта проработки. По физико-химическим показателям соответствует требованиям ГОСТ РФ 50763-2007 "Кулинарная продукция, реализуемая населению". По микробиологическим показателям соответствует требованиям СанПиН 2.3.2 1078-01', 99);
INSERT INTO tech_cards (card_number, dish_name, organization_id, approval_date, application_area, portion_norm, technology, technology_source, serving_requirements, total_output_kg, proteins_per_100g, fats_per_100g, carbs_per_100g, calories_per_100g, note, source_page) VALUES ('03182', 'Гаспачо', (SELECT id FROM organizations WHERE name='Бранч'), '2022-07-07', 'Cake&Coffee', 1.000, 'Кинзу промыть, обсушить, мелко нарезать. Палочки укропа нарезать колечками и залить зеленым маслом.', 'original', 'В шляпу налить 250 грамм гаспачо, в центр выложить кинзу, вокруг выложить соломкой нарезаные вяленые томаты. Украсить корзинке.', 0.297, 0, 0, 0, 0, 'технологическая карта составлена на основании акта проработки. По физико-химическим показателям соответствует требованиям ГОСТ РФ 50763-2007 "Кулинарная продукция, реализуемая населению". По микробиологическим показателям соответствует требованиям СанПиН 2.3.2 1078-01', 100);
INSERT INTO tech_cards (card_number, dish_name, organization_id, approval_date, application_area, portion_norm, technology, technology_source, serving_requirements, total_output_kg, proteins_per_100g, fats_per_100g, carbs_per_100g, calories_per_100g, note, source_page) VALUES ('03115', 'Глазированая морковь с хумусом', (SELECT id FROM organizations WHERE name='Бранч'), '2022-03-11', 'Cake&Coffee', 1.000, '(от ии) Морковь очищеная (100 г) нарезать крупными брусочками. Разогреть сковороду с Масло оливковое на среднем огне (160-170 °C). Обжарить морковь 4-5 минут, помешивая, до легкой карамелизации. Добавить Мед (10 г), перемешать. Глазировать 1-2 минуты до глянцевого блеска. Выложить на тарелку. Рядом выложить Хумус морковный (50 г). Украсить микрозеленью. Подавать при 50-60 °C.', 'ai', 'Семечки подсолнечника', 0.195, 0, 0, 0, 0, 'технологическая карта составлена на основании акта проработки. По физико-химическим показателям соответствует требованиям ГОСТ РФ 50763-2007 "Кулинарная продукция, реализуемая населению". По микробиологическим показателям соответствует требованиям СанПиН 2.3.2 1078-01', 101);
INSERT INTO tech_cards (card_number, dish_name, organization_id, approval_date, application_area, portion_norm, technology, technology_source, serving_requirements, total_output_kg, proteins_per_100g, fats_per_100g, carbs_per_100g, calories_per_100g, note, source_page) VALUES ('03168', 'Грибной суп с карамелеированным беконом и чиабаттой', (SELECT id FROM organizations WHERE name='Бранч'), '2022-04-29', 'Cake&Coffee', 1.000, 'Лук и шампиньоны (100гр) обжарить на растительном масле, добавить молоко, сливки и картофельное пюре, прогреть и обжарить до коллера. Выложить суп в тарелку, сверху выложить грибы, посыпать грибы карамелизированным беконом.', 'original', 'Карамелизированны й бекон', 0.4353, 0, 0, 0, 0, 'технологическая карта составлена на основании акта проработки. По физико-химическим показателям соответствует требованиям ГОСТ РФ 50763-2007 "Кулинарная продукция, реализуемая населению". По микробиологическим показателям соответствует требованиям СанПиН 2.3.2 1078-01', 102);
INSERT INTO tech_cards (card_number, dish_name, organization_id, approval_date, application_area, portion_norm, technology, technology_source, serving_requirements, total_output_kg, proteins_per_100g, fats_per_100g, carbs_per_100g, calories_per_100g, note, source_page) VALUES ('03166', 'Кесадилья с томленой говядиной', (SELECT id FROM organizations WHERE name='Бранч'), '2022-04-28', 'Cake&Coffee', 1.000, '(от ии) Тортилья (2 шт.) — разогреть на сухой сковороде при 180 °C по 30 секунд с каждой стороны. Лук репчатый (20 г), Перец болгарский (20 г), Морковь очищеная (15 г) — нарезать соломкой. Обжарить овощи на Масло подсолнечное (5 г) при 180 °C 3-4 минуты. Добавить Телячьи щечки пф (томленые, 60 г), разогреть. На половину тортильи выложить начинку (овощи + мясо + Сыр, 20 г). Сложить пополам. Обжарить на сковороде при 180 °C 1-2 минуты с каждой стороны до золотистой корочки и расплавления сыра. Разрезать на секторы. Подавать с соусом (сметана/сальса). Температура подачи 55-65 °C.', 'ai', 'Моцарелла для', 0.3, 0, 0, 0, 0, 'технологическая карта составлена на основании акта проработки. По физико-химическим показателям соответствует требованиям ГОСТ РФ 50763-2007 "Кулинарная продукция, реализуемая населению". По микробиологическим показателям соответствует требованиям СанПиН 2.3.2 1078-01', 103);
INSERT INTO tech_cards (card_number, dish_name, organization_id, approval_date, application_area, portion_norm, technology, technology_source, serving_requirements, total_output_kg, proteins_per_100g, fats_per_100g, carbs_per_100g, calories_per_100g, note, source_page) VALUES ('03114', 'Котлета из куриной грудки и цукини', (SELECT id FROM organizations WHERE name='Бранч'), '2022-03-11', 'Cake&Coffee', 1.000, '140 грамм куриного фарша обжарить до', 'original', 'Выложить котлету на тарелку, вокруг отсадить из кондитерского мешка по три капли свекольного и морковного хумуса, выложить гарнир.', 0.165, 0, 0, 0, 0, 'технологическая карта составлена на основании акта проработки. По физико-химическим показателям соответствует требованиям ГОСТ РФ 50763-2007 "Кулинарная продукция, реализуемая населению". По микробиологическим показателям соответствует требованиям СанПиН 2.3.2 1078-01', 104);
INSERT INTO tech_cards (card_number, dish_name, organization_id, approval_date, application_area, portion_norm, technology, technology_source, serving_requirements, total_output_kg, proteins_per_100g, fats_per_100g, carbs_per_100g, calories_per_100g, note, source_page) VALUES ('03289', 'Мидии в кокосовом соусе', (SELECT id FROM organizations WHERE name='Бранч'), '2022-11-25', 'Cake&Coffee', 1.000, 'Кокосовые сливки и креметту растопить до состояния соуса, добавить мелко нарезанный перец чили. Мидии почистить, отколотые панцири, поместить в соус. Выложить мидии в кострюльку на листья бамбука посыпать пармезаном, украсить ломтиками поджаренной чиабатты и', 'original', 'Сыр творожный креметта', 0.56, 0, 0, 0, 0, 'технологическая карта составлена на основании акта проработки. По физико-химическим показателям соответствует требованиям ГОСТ РФ 50763-2007 "Кулинарная продукция, реализуемая населению". По микробиологическим показателям соответствует требованиям СанПиН 2.3.2 1078-01', 105);
INSERT INTO tech_cards (card_number, dish_name, organization_id, approval_date, application_area, portion_norm, technology, technology_source, serving_requirements, total_output_kg, proteins_per_100g, fats_per_100g, carbs_per_100g, calories_per_100g, note, source_page) VALUES ('03276', 'Мидии в соусе горганзола', (SELECT id FROM organizations WHERE name='Бранч'), '2022-11-19', 'Cake&Coffee', 1.000, 'Лук поррей соломкой слегка обжарить, добавить сливки, сыр с голубой плесенью, подсолить до вкуса.Мидии почистить, отколотые панцири, поместить в соус. креметта Выложить мидии в кострюльку на листья бамбука, полить устричным соусом, ломтиками поджаренной чиабатты и', 'original', NULL, 0.435, 0, 0, 0, 0, 'технологическая карта составлена на основании акта проработки. По физико-химическим показателям соответствует требованиям ГОСТ РФ 50763-2007 "Кулинарная продукция, реализуемая населению". По микробиологическим показателям соответствует требованиям СанПиН 2.3.2 1078-01', 106);
INSERT INTO tech_cards (card_number, dish_name, organization_id, approval_date, application_area, portion_norm, technology, technology_source, serving_requirements, total_output_kg, proteins_per_100g, fats_per_100g, carbs_per_100g, calories_per_100g, note, source_page) VALUES ('03288', 'Мидии в соусе Том Ям', (SELECT id FROM organizations WHERE name='Бранч'), '2022-11-25', 'Cake&Coffee', 1.000, 'В слмвках растворить пасту том ям, прогреть в кипятке, слить воду, удалить Выложить мидии в кострюльку на листья бамбука, полить устричным соусом, накрыть крышкой. подавать с двумя долькой лимона.', 'original', NULL, 0.38, 0, 0, 0, 0, 'технологическая карта составлена на основании акта проработки. По физико-химическим показателям соответствует требованиям ГОСТ РФ 50763-2007 "Кулинарная продукция, реализуемая населению". По микробиологическим показателям соответствует требованиям СанПиН 2.3.2 1078-01', 107);
INSERT INTO tech_cards (card_number, dish_name, organization_id, approval_date, application_area, portion_norm, technology, technology_source, serving_requirements, total_output_kg, proteins_per_100g, fats_per_100g, carbs_per_100g, calories_per_100g, note, source_page) VALUES ('03370', 'Оливье с крабом', (SELECT id FROM organizations WHERE name='Бранч'), '2023-01-20', 'Cake&Coffee', 1.000, '(от ии) Морковь очищеная (30 г) и Картофель отварной (60 г) — нарезать кубиком 0,5 см. Огурец (30 г) — мелкий кубик. Горошек заморозка (20 г) — разморозить. Яйцо куриное (1 шт.) — сварить вкрутую (10 мин в кипятке), нарезать кубиком. Крабовые палочки/мясо (40 г) — нарезать кубиком. Лук зеленый (10 г) — мелко нарезать. Смешать все ингредиенты. Заправить Домашний майонез (30 г) и Сметана 30% (10 г). Соль, Перец по вкусу. Выложить на тарелку горкой. Украсить зеленью. Подавать при 5-10 °C, предварительно охладив.', 'ai', 'Филе краба заморозка', 0.206, 0, 0, 0, 0, 'технологическая карта составлена на основании акта проработки. По физико-химическим показателям соответствует требованиям ГОСТ РФ 50763-2007 "Кулинарная продукция, реализуемая населению". По микробиологическим показателям соответствует требованиям СанПиН 2.3.2 1078-01', 108);
INSERT INTO tech_cards (card_number, dish_name, organization_id, approval_date, application_area, portion_norm, technology, technology_source, serving_requirements, total_output_kg, proteins_per_100g, fats_per_100g, carbs_per_100g, calories_per_100g, note, source_page) VALUES ('03371', 'Оливье с пастрами из индейки', (SELECT id FROM organizations WHERE name='Бранч'), '2023-01-21', 'Cake&Coffee', 1.000, '(от ии) Морковь очищеная (30 г) и Картофель отварной (60 г) — нарезать кубиком 0,5 см. Огурец (30 г) — мелкий кубик. Горошек заморозка (20 г) — разморозить. Яйцо куриное (1 шт.) — сварить вкрутую (10 мин), кубиком. Лук репчатый (10 г) — мелкий кубик, замочить в воде 5 мин. Пастрами из индейки (40 г) — нарезать кубиком. Смешать. Заправить Домашний майонез (30 г). Соль, Перец. Выложить горкой. Украсить зеленью. Подавать при 5-10 °C, охладив.', 'ai', NULL, 0.226, 0, 0, 0, 0, 'технологическая карта составлена на основании акта проработки. По физико-химическим показателям соответствует требованиям ГОСТ РФ 50763-2007 "Кулинарная продукция, реализуемая населению". По микробиологическим показателям соответствует требованиям СанПиН 2.3.2 1078-01', 109);
INSERT INTO tech_cards (card_number, dish_name, organization_id, approval_date, application_area, portion_norm, technology, technology_source, serving_requirements, total_output_kg, proteins_per_100g, fats_per_100g, carbs_per_100g, calories_per_100g, note, source_page) VALUES ('03367', 'Омлет Пуляр с крабом', (SELECT id FROM organizations WHERE name='Бранч'), '2023-01-01', 'Cake&Coffee', 1.000, '(от ии) Яйцо куриное (3 шт.) взбить вилкой со Сливки 22% (20 мл), Соль пищевая и Перец горошек (молотый) по вкусу. Шпинат свежий (20 г) бланшировать 30 секунд в кипятке, отжать. Нарезать. Добавить в яичную смесь вместе с крабовым мясом (30 г). Разогреть сковороду с Масло подсолнечное (5 г) на среднем огне (160-180 °C). Вылить яичную смесь, убавить огонь до среднего-слабого (140-160 °C). Готовить 2-3 минуты, приподнимая края лопаткой, чтобы сырое яйцо стекало вниз. Когда нижняя сторона зажарится до золотистого цвета, а верхняя почти схватится — сложить омлет пополам. Температура подачи 65-70 °C.', 'ai', 'Филе краба заморозка', 0.175, 0, 0, 0, 0, 'технологическая карта составлена на основании акта проработки. По физико-химическим показателям соответствует требованиям ГОСТ РФ 50763-2007 "Кулинарная продукция, реализуемая населению". По микробиологическим показателям соответствует требованиям СанПиН 2.3.2 1078-01', 110);
INSERT INTO tech_cards (card_number, dish_name, organization_id, approval_date, application_area, portion_norm, technology, technology_source, serving_requirements, total_output_kg, proteins_per_100g, fats_per_100g, carbs_per_100g, calories_per_100g, note, source_page) VALUES ('03368', 'Омлет Пуляр с пастрами', (SELECT id FROM organizations WHERE name='Бранч'), '2023-01-20', 'Cake&Coffee', 1.000, '(от ии) Яйцо куриное (3 шт.) взбить вилкой со Сливки 22% (20 мл), Соль пищевая и Перец горошек (молотый) по вкусу. Филе индейки (пастрами, 30 г) нарезать тонкими ломтиками. Шпинат свежий (20 г) бланшировать. Добавить в яичную смесь. При подаче полить Икорный айоли (10 г). Разогреть сковороду с Масло подсолнечное (5 г) на среднем огне (160-180 °C). Вылить яичную смесь, убавить огонь до среднего-слабого (140-160 °C). Готовить 2-3 минуты, приподнимая края лопаткой, чтобы сырое яйцо стекало вниз. Когда нижняя сторона зажарится до золотистого цвета, а верхняя почти схватится — сложить омлет пополам. Температура подачи 65-70 °C.', 'ai', NULL, 0.2017, 0, 0, 0, 0, 'технологическая карта составлена на основании акта проработки. По физико-химическим показателям соответствует требованиям ГОСТ РФ 50763-2007 "Кулинарная продукция, реализуемая населению". По микробиологическим показателям соответствует требованиям СанПиН 2.3.2 1078-01', 111);
INSERT INTO tech_cards (card_number, dish_name, organization_id, approval_date, application_area, portion_norm, technology, technology_source, serving_requirements, total_output_kg, proteins_per_100g, fats_per_100g, carbs_per_100g, calories_per_100g, note, source_page) VALUES ('03369', 'Омлет Пуляр с Прошутто', (SELECT id FROM organizations WHERE name='Бранч'), '2023-01-20', 'Cake&Coffee', 1.000, '(от ии) Яйцо куриное (3 шт.) взбить вилкой со Сливки 22% (20 мл), Соль пищевая и Перец горошек (молотый) по вкусу. Прошутто (20 г) нарезать тонкими ломтиками. Шпинат свежий (20 г) бланшировать 30 сек, отжать. Выложить прошутто и шпинат на половину омлета перед складыванием. Разогреть сковороду с Масло подсолнечное (5 г) на среднем огне (160-180 °C). Вылить яичную смесь, убавить огонь до среднего-слабого (140-160 °C). Готовить 2-3 минуты, приподнимая края лопаткой, чтобы сырое яйцо стекало вниз. Когда нижняя сторона зажарится до золотистого цвета, а верхняя почти схватится — сложить омлет пополам. Температура подачи 65-70 °C.', 'ai', 'Сыровяленная свинина Горчично-медовая завправка', 0.1715, 0, 0, 0, 0, 'технологическая карта составлена на основании акта проработки. По физико-химическим показателям соответствует требованиям ГОСТ РФ 50763-2007 "Кулинарная продукция, реализуемая населению". По микробиологическим показателям соответствует требованиям СанПиН 2.3.2 1078-01', 112);
INSERT INTO tech_cards (card_number, dish_name, organization_id, approval_date, application_area, portion_norm, technology, technology_source, serving_requirements, total_output_kg, proteins_per_100g, fats_per_100g, carbs_per_100g, calories_per_100g, note, source_page) VALUES ('03284', 'Пита с уткой', (SELECT id FROM organizations WHERE name='Бранч'), '2022-11-22', 'Cake&Coffee', 1.000, 'Раскатать питу, обжарить ее на сливочном полить соусом хойсин равномерно из обжарить вместе с нарубленным филе, посолить, поперчить, выложить на лепешку плоскую тарелку налить немного зеленого посередине положить два литса бамбука,', 'original', NULL, 0.2106, 0, 0, 0, 0, 'технологическая карта составлена на основании акта проработки. По физико-химическим показателям соответствует требованиям ГОСТ РФ 50763-2007 "Кулинарная продукция, реализуемая населению". По микробиологическим показателям соответствует требованиям СанПиН 2.3.2 1078-01', 113);
INSERT INTO tech_cards (card_number, dish_name, organization_id, approval_date, application_area, portion_norm, technology, technology_source, serving_requirements, total_output_kg, proteins_per_100g, fats_per_100g, carbs_per_100g, calories_per_100g, note, source_page) VALUES ('03429', 'Рамен с креветкой', (SELECT id FROM organizations WHERE name='Бранч'), '2023-02-15', 'Cake&Coffee', 1.000, 'На дно тарелки выложить отвареную яичную лапшу , по кругу выложить чукку, фасоль, зеленый горошет, обжаренные смятку целиком, залить горячим бульоном, посыпать зеленым луком, перцем. отдельно подать нори, нарезанные на небольшие', 'original', 'Фасоль стручковая морожен.', 0.526, 0, 0, 0, 0, 'технологическая карта составлена на основании акта проработки. По физико-химическим показателям соответствует требованиям ГОСТ РФ 50763-2007 "Кулинарная продукция, реализуемая населению". По микробиологическим показателям соответствует требованиям СанПиН 2.3.2 1078-01', 114);
INSERT INTO tech_cards (card_number, dish_name, organization_id, approval_date, application_area, portion_norm, technology, technology_source, serving_requirements, total_output_kg, proteins_per_100g, fats_per_100g, carbs_per_100g, calories_per_100g, note, source_page) VALUES ('03275', 'Рамен с курицей', (SELECT id FROM organizations WHERE name='Бранч'), '2022-11-19', 'Cake&Coffee', 1.000, 'На дно тарелки выложить отвареную яичную лапшу , по кругу выложить чукку, фасоль, зеленый горошет, нарезанную шампиньоны, яйцо в смятку целиком, залить горячим бульоном, посыпать зеленым луком, перцем. отдельно подать 3х3 см', 'original', 'Фасоль стручковая морожен.', 0.576, 0, 0, 0, 0, 'технологическая карта составлена на основании акта проработки. По физико-химическим показателям соответствует требованиям ГОСТ РФ 50763-2007 "Кулинарная продукция, реализуемая населению". По микробиологическим показателям соответствует требованиям СанПиН 2.3.2 1078-01', 115);
INSERT INTO tech_cards (card_number, dish_name, organization_id, approval_date, application_area, portion_norm, technology, technology_source, serving_requirements, total_output_kg, proteins_per_100g, fats_per_100g, carbs_per_100g, calories_per_100g, note, source_page) VALUES ('03155', 'Рыбные котлетки', (SELECT id FROM organizations WHERE name='Бранч'), '2022-04-14', 'Cake&Coffee', 1.000, 'В рыбный фарш(пикша/лосось обрезь) добавить лук, пюре, соль и перец по вкусу. Сформовать две круглых котлеты, обжарить и допечь в пароконвектомате при 180-200 градусах. Лук кубиком, спаржу поперек тонко, обжарить и добавить сливки, выпарить до загущения.', 'original', 'Выложить соус в шляпу, по центру тарелки гарниром - соус в соусничку, котлеты', 0.257, 0, 0, 0, 0, 'технологическая карта составлена на основании акта проработки. По физико-химическим показателям соответствует требованиям ГОСТ РФ 50763-2007 "Кулинарная продукция, реализуемая населению". По микробиологическим показателям соответствует требованиям СанПиН 2.3.2 1078-01', 116);
INSERT INTO tech_cards (card_number, dish_name, organization_id, approval_date, application_area, portion_norm, technology, technology_source, serving_requirements, total_output_kg, proteins_per_100g, fats_per_100g, carbs_per_100g, calories_per_100g, note, source_page) VALUES ('03285', 'Салат с уткой', (SELECT id FROM organizations WHERE name='Бранч'), '2022-11-22', 'Cake&Coffee', 1.000, 'Айсберг, рукколу, компрессионные огурцы, пекински б/к черри смешать в миске, посолить и выложить на дно тарелки. подогретое филе утки нарибить и выложить на микссалат, по центру выложить половинку яйца в смятку, посыпать его семенами чиа и полить соусом хойсин.', 'original', NULL, 0.181, 0, 0, 0, 0, 'технологическая карта составлена на основании акта проработки. По физико-химическим показателям соответствует требованиям ГОСТ РФ 50763-2007 "Кулинарная продукция, реализуемая населению". По микробиологическим показателям соответствует требованиям СанПиН 2.3.2 1078-01', 117);
INSERT INTO tech_cards (card_number, dish_name, organization_id, approval_date, application_area, portion_norm, technology, technology_source, serving_requirements, total_output_kg, proteins_per_100g, fats_per_100g, carbs_per_100g, calories_per_100g, note, source_page) VALUES ('03180', 'Сашими из тунца с лаймовой эспумой', (SELECT id FROM organizations WHERE name='Бранч'), '2022-07-06', 'Cake&Coffee', 1.000, 'Сырой тунец нарезать тонко ровными укропа нарезать колечками и залить', 'original', 'На плоскую тарелку выложить по центру слайсы туна внахлест, полить соевым соусом и кнужутным маслом, слегка опалить горелкой, ТУНЕЦ ДОЛЖЕН ОСТАТЬСЯ СЫРЫМ, поперчить, в трех местах украсить колечками укропа с лаймовую эспуму в трех местах, сторого Подать незамедлительно.', 0.1021, 0, 0, 0, 0, 'технологическая карта составлена на основании акта проработки. По физико-химическим показателям соответствует требованиям ГОСТ РФ 50763-2007 "Кулинарная продукция, реализуемая населению". По микробиологическим показателям соответствует требованиям СанПиН 2.3.2 1078-01', 118);
INSERT INTO tech_cards (card_number, dish_name, organization_id, approval_date, application_area, portion_norm, technology, technology_source, serving_requirements, total_output_kg, proteins_per_100g, fats_per_100g, carbs_per_100g, calories_per_100g, note, source_page) VALUES ('03112', 'Свекольный и морковный хумус с крутонами', (SELECT id FROM organizations WHERE name='Бранч'), '2022-03-11', 'Cake&Coffee', 1.000, 'Два хумуса отсадить из мешка на ровными горками. посыпать семенами льна и подсолнуха, рядом с хумусом выложить крутоны. Сбрызнуть блюдо зеленым', 'original', 'подсолнечника', 0.214, 0, 0, 0, 0, 'технологическая карта составлена на основании акта проработки. По физико-химическим показателям соответствует требованиям ГОСТ РФ 50763-2007 "Кулинарная продукция, реализуемая населению". По микробиологическим показателям соответствует требованиям СанПиН 2.3.2 1078-01', 119);
INSERT INTO tech_cards (card_number, dish_name, organization_id, approval_date, application_area, portion_norm, technology, technology_source, serving_requirements, total_output_kg, proteins_per_100g, fats_per_100g, carbs_per_100g, calories_per_100g, note, source_page) VALUES ('03183', 'Соба с тунцом татаки', (SELECT id FROM organizations WHERE name='Бранч'), '2022-07-07', 'Cake&Coffee', 1.000, 'Собу положить в кипящую подсоленую воду и варить 3 минуты, после сразу достать из воды. Шампиньоны нашинковать, перец нарезать тонкой соломкой, обжарить, добавить отварную собу и соус унаги, бруском, обжечь горелкой со всех сторон и нарезать вдоль на 4 кусочка.', 'original', 'Собу с овощами выложить в шляпу, сверху выложить нарезаный тунец ровно сложенный в нахлест. Посыпать перцем.', 0.197, 0, 0, 0, 0, 'технологическая карта составлена на основании акта проработки. По физико-химическим показателям соответствует требованиям ГОСТ РФ 50763-2007 "Кулинарная продукция, реализуемая населению". По микробиологическим показателям соответствует требованиям СанПиН 2.3.2 1078-01', 120);
INSERT INTO tech_cards (card_number, dish_name, organization_id, approval_date, application_area, portion_norm, technology, technology_source, serving_requirements, total_output_kg, proteins_per_100g, fats_per_100g, carbs_per_100g, calories_per_100g, note, source_page) VALUES ('03431', 'Сэндвич бенедикт с индейкой', (SELECT id FROM organizations WHERE name='Бранч'), '2023-02-16', 'Cake&Coffee', 1.000, '(от ии) Тесто Бриошь разрезать пополам горизонтально. Обжарить на Масло сливочное (5 г) с двух сторон на среднем огне 160-170 °C до золотистого цвета. Филе индейки (пастрами, 50 г) обжарить на сухой сковороде 1-2 минуты с каждой стороны при 180 °C до подрумянивания. Яйцо куриное — пашот: в кипящую воду с уксусом (1 ст.л. на 1 л) создать воронку, аккуратно влить яйцо, варить 3-3,5 минуты при 90-95 °C. Горчично-медовая — подогреть соус. На нижнюю половину бриоши нанести соус, выложить индейку, затем яйцо пашот, полить соусом. Посыпать Лук реп суш. Накрыть верхней половиной. Подавать при 60-65 °C.', 'ai', 'завправка Голландез из кремера', 0.251, 0, 0, 0, 0, 'технологическая карта составлена на основании акта проработки. По физико-химическим показателям соответствует требованиям ГОСТ РФ 50763-2007 "Кулинарная продукция, реализуемая населению". По микробиологическим показателям соответствует требованиям СанПиН 2.3.2 1078-01', 121);
INSERT INTO tech_cards (card_number, dish_name, organization_id, approval_date, application_area, portion_norm, technology, technology_source, serving_requirements, total_output_kg, proteins_per_100g, fats_per_100g, carbs_per_100g, calories_per_100g, note, source_page) VALUES ('03192', 'Тартар из тунца на подушке из авокадо', (SELECT id FROM organizations WHERE name='Бранч'), '2022-07-12', 'Cake&Coffee', 1.000, '(от ии) Авокадо (1 шт.) разрезать пополам, удалить косточку. Мякоть нарезать кубиком 1х1 см. Тунец желтохвост (80 г, сашими-качество) нарезать кубиком 1х1 см. Лук репчатый (10 г) мелко нашинковать, замочить в холодной воде на 5 минут, отжать. Перец чили (2 г) мелко нарезать. Смешать тунец с луком, чили, Соль пищевая, Сок лайма (5 мл), Масло оливковое (5 мл). На тарелку выложить половинки авокадо, сверху — тартар из тунца. Украсить микрозеленью и кунжутом. Подавать немедленно при температуре 5-10 °C. Блюдо не подлежит хранению.', 'ai', NULL, 0.1615, 0, 0, 0, 0, 'технологическая карта составлена на основании акта проработки. По физико-химическим показателям соответствует требованиям ГОСТ РФ 50763-2007 "Кулинарная продукция, реализуемая населению". По микробиологическим показателям соответствует требованиям СанПиН 2.3.2 1078-01', 122);
INSERT INTO tech_cards (card_number, dish_name, organization_id, approval_date, application_area, portion_norm, technology, technology_source, serving_requirements, total_output_kg, proteins_per_100g, fats_per_100g, carbs_per_100g, calories_per_100g, note, source_page) VALUES ('03274', 'Том Ям', (SELECT id FROM organizations WHERE name='Бранч'), '2022-11-19', 'Cake&Coffee', 1.000, 'Шампиньоны дольками обжарить, добавить креветки, обжарить. Залить бульоном, добавить рыбный, устричный и том ям соуса, добавить кальмары и мидии, прокипятить. В глубокую белую тарелку положить два листа бамбука, выложить все, кроме мидий и бульона, аккуратно влить бульон, возле торчащих листьев выложить мидии, украсить соломой из порея.', 'original', NULL, 0.45, 0, 0, 0, 0, 'технологическая карта составлена на основании акта проработки. По физико-химическим показателям соответствует требованиям ГОСТ РФ 50763-2007 "Кулинарная продукция, реализуемая населению". По микробиологическим показателям соответствует требованиям СанПиН 2.3.2 1078-01', 123);
INSERT INTO tech_cards (card_number, dish_name, organization_id, approval_date, application_area, portion_norm, technology, technology_source, serving_requirements, total_output_kg, proteins_per_100g, fats_per_100g, carbs_per_100g, calories_per_100g, note, source_page) VALUES ('03391', 'Большой Завтрак', (SELECT id FROM organizations WHERE name='Бранч'), '2023-02-08', 'Cake&Coffee', 1.000, 'выкладка по фото, голландез на яйца, посыпать хрустящим луком', 'original', 'Индейка 40 гр Бекон 50гр лосось сс 40гр цукини и болгарский перец по 30гр пармская ветчина 20гр ростбиф мариновонный 40гр Сыр творожный креметта Голландез из кремера', 0.2563, 0, 0, 0, 0, 'технологическая карта составлена на основании акта проработки. По физико-химическим показателям соответствует требованиям ГОСТ РФ 50763-2007 "Кулинарная продукция, реализуемая населению". По микробиологическим показателям соответствует требованиям СанПиН 2.3.2 1078-01', 124);
INSERT INTO tech_cards (card_number, dish_name, organization_id, approval_date, application_area, portion_norm, technology, technology_source, serving_requirements, total_output_kg, proteins_per_100g, fats_per_100g, carbs_per_100g, calories_per_100g, note, source_page) VALUES ('03109', 'Большой завтрак с беконом и грибами', (SELECT id FROM organizations WHERE name='Бранч'), '2022-03-10', 'Cake&Coffee', 1.000, 'Бекон целой полоской и шампиньоны (мелкие на 4 части, крупные на 6) обжарить, подготовить яйцо на выбор гостя, черри целиком, огурец слайсом поперек, Чиабатту жарим на гриле, сливочный сыр и', 'original', 'Выкладываем на самую большую тарелку в таком порядке по кругу: Чиабатта, сыр, фасоль, салат, глазированная морковь, яйцо на выбор, в центр тарелки - бекон и грибы. Салат посыпать семенами льна.', 0.4666, 0, 0, 0, 0, 'технологическая карта составлена на основании акта проработки. По физико-химическим показателям соответствует требованиям ГОСТ РФ 50763-2007 "Кулинарная продукция, реализуемая населению". По микробиологическим показателям соответствует требованиям СанПиН 2.3.2 1078-01', 125);
INSERT INTO tech_cards (card_number, dish_name, organization_id, approval_date, application_area, portion_norm, technology, technology_source, serving_requirements, total_output_kg, proteins_per_100g, fats_per_100g, carbs_per_100g, calories_per_100g, note, source_page) VALUES ('03162', 'Большой завтрак с горячим росбифом', (SELECT id FROM organizations WHERE name='Бранч'), '2022-04-18', 'Cake&Coffee', 1.000, 'Росбиф слайсами и шампиньоны(мелкие на подготовить яйцо на выбор гостя, черри целиком, огурец слайсом поперек, Чиабатту жарим на гриле, сливочный сыр и', 'original', 'Выкладываем на самую большую тарелку в таком порядке по кругу: Чиабатта, сыр, фасоль, салат, глазированная морковь, яйцо на выбор, в центр тарелки - ростбиф и грибы. Салат посыпаем семенами льна. Говядина внутренняя вырезка', 0.4626, 0, 0, 0, 0, 'технологическая карта составлена на основании акта проработки. По физико-химическим показателям соответствует требованиям ГОСТ РФ 50763-2007 "Кулинарная продукция, реализуемая населению". По микробиологическим показателям соответствует требованиям СанПиН 2.3.2 1078-01', 126);
INSERT INTO tech_cards (card_number, dish_name, organization_id, approval_date, application_area, portion_norm, technology, technology_source, serving_requirements, total_output_kg, proteins_per_100g, fats_per_100g, carbs_per_100g, calories_per_100g, note, source_page) VALUES ('03111', 'Большой завтрак с овощами аль дэнтэ', (SELECT id FROM organizations WHERE name='Бранч'), '2022-03-11', 'Cake&Coffee', 1.000, 'Цукини дольками, болгарский перец части, крупные на 6) обжарить, подготовить салата рвем руками айсберг, 2 черри оливковое масло + соль и перец. Чиабатту соуснички.', 'original', 'Выкладываем на самую большую тарелку в таком порядке по кругу: Чиабатта, сыр, фасоль, салат, глазированная морковь, яйцо на выбор, в центр тарелки -овощи альденте.Салат посыпать семенами льна.', 0.5366, 0, 0, 0, 0, 'технологическая карта составлена на основании акта проработки. По физико-химическим показателям соответствует требованиям ГОСТ РФ 50763-2007 "Кулинарная продукция, реализуемая населению". По микробиологическим показателям соответствует требованиям СанПиН 2.3.2 1078-01', 127);
INSERT INTO tech_cards (card_number, dish_name, organization_id, approval_date, application_area, portion_norm, technology, technology_source, serving_requirements, total_output_kg, proteins_per_100g, fats_per_100g, carbs_per_100g, calories_per_100g, note, source_page) VALUES ('00034', 'Глазунья с авокадо', (SELECT id FROM organizations WHERE name='Бранч'), '2022-07-06', 'Cake&Coffee', 1.000, 'На холодную сковороду с антипригарным плиту и жарим яйца до готовности так, что Авокадо нарезаем слайсом. Чиабатту', 'original', 'На тарелку выкладываем чиабатту и гуакамолле в соусничке, глазунью, рядом авокадо, на авокадо рукколу. сбрызнуть оливковым маслом и посыпать молотым перцем.', 0.2331, 3, 10, 14, 159, 'технологическая карта составлена на основании акта проработки. По физико-химическим показателям соответствует требованиям ГОСТ РФ 50763-2007 "Кулинарная продукция, реализуемая населению". По микробиологическим показателям соответствует требованиям СанПиН 2.3.2 1078-01', 128);
INSERT INTO tech_cards (card_number, dish_name, organization_id, approval_date, application_area, portion_norm, technology, technology_source, serving_requirements, total_output_kg, proteins_per_100g, fats_per_100g, carbs_per_100g, calories_per_100g, note, source_page) VALUES ('00035', 'Глазунья с беконом', (SELECT id FROM organizations WHERE name='Бранч'), '2022-07-06', 'Cake&Coffee', 1.000, 'На холодную сковороду с антипригарным плиту и жарим яйца до готовности так, что Бекон целыми слайсами обжариваем.', 'original', 'На тарелку выкладываем хлеб и сливочный сыр в соусничке, глазунью, сверху айсберг, на айсберг - поджареный бекон. Сбрызгиваем оливковым маслом и посыпаем перцем.', 0.2431, 7, 16, 13, 223, 'технологическая карта составлена на основании акта проработки. По физико-химическим показателям соответствует требованиям ГОСТ РФ 50763-2007 "Кулинарная продукция, реализуемая населению". По микробиологическим показателям соответствует требованиям СанПиН 2.3.2 1078-01', 129);
INSERT INTO tech_cards (card_number, dish_name, organization_id, approval_date, application_area, portion_norm, technology, technology_source, serving_requirements, total_output_kg, proteins_per_100g, fats_per_100g, carbs_per_100g, calories_per_100g, note, source_page) VALUES ('01564', 'Драники с беконом', (SELECT id FROM organizations WHERE name='Бранч'), '2022-01-08', 'Cake&Coffee', 1.000, 'Отварной картофель натереть на мелкой терке, добавить яйцо, соль и перец, покрытием три ровных дранника, обжарить до готовности. Бекон поджарить целыми гостя.', 'original', 'На плоскую тарелку выложить три дранника внахлест по линии, рядом выложить яйцо, на драники - бекон и рукколу, посыпать', 0.218, 0, 0, 0, 0, 'технологическая карта составлена на основании акта проработки. По физико-химическим показателям соответствует требованиям ГОСТ РФ 50763-2007 "Кулинарная продукция, реализуемая населению". По микробиологическим показателям соответствует требованиям СанПиН 2.3.2 1078-01', 130);
INSERT INTO tech_cards (card_number, dish_name, organization_id, approval_date, application_area, portion_norm, technology, technology_source, serving_requirements, total_output_kg, proteins_per_100g, fats_per_100g, carbs_per_100g, calories_per_100g, note, source_page) VALUES ('01565', 'Завтрак с креветками', (SELECT id FROM organizations WHERE name='Бранч'), '2022-01-08', 'Cake&Coffee', 1.000, '40 гр креветок обжарить, добавить фунчозу и прогреть, добавить кунжутное масло, соль и перец. Подготовить яйцо на выбор гостя.', 'original', 'В шляпу по центру выложить фунчозу, вокруг креветки, на фунчозу выложить яйцо, посыпать зеленым луком.', 0.1408, 0, 0, 0, 0, 'технологическая карта составлена на основании акта проработки. По физико-химическим показателям соответствует требованиям ГОСТ РФ 50763-2007 "Кулинарная продукция, реализуемая населению". По микробиологическим показателям соответствует требованиям СанПиН 2.3.2 1078-01', 131);
INSERT INTO tech_cards (card_number, dish_name, organization_id, approval_date, application_area, portion_norm, technology, technology_source, serving_requirements, total_output_kg, proteins_per_100g, fats_per_100g, carbs_per_100g, calories_per_100g, note, source_page) VALUES ('03004', 'Омлет порция', (SELECT id FROM organizations WHERE name='Бранч'), '2021-12-22', 'Cake&Coffee', 1.000, '(от ии) Яйцо куриное (3 шт.) взбить вилкой со Сливки 33% (20 мл), Соль пищевая и Перец горошек (молотый) по вкусу. Разогреть сковороду с Масло подсолнечное (5 г) на среднем огне (160-180 °C). Вылить яичную смесь, убавить огонь до среднего-слабого (140-160 °C). Готовить 2-3 минуты, приподнимая края лопаткой, чтобы сырое яйцо стекало вниз. Когда нижняя сторона зажарится до золотистого цвета, а верхняя почти схватится — сложить омлет пополам. Температура подачи 65-70 °C.', 'ai', NULL, 0.1303, 0, 0, 0, 0, 'технологическая карта составлена на основании акта проработки. По физико-химическим показателям соответствует требованиям ГОСТ РФ 50763-2007 "Кулинарная продукция, реализуемая населению". По микробиологическим показателям соответствует требованиям СанПиН 2.3.2 1078-01', 132);
INSERT INTO tech_cards (card_number, dish_name, organization_id, approval_date, application_area, portion_norm, technology, technology_source, serving_requirements, total_output_kg, proteins_per_100g, fats_per_100g, carbs_per_100g, calories_per_100g, note, source_page) VALUES ('00036', 'Омлет с авокадо', (SELECT id FROM organizations WHERE name='Бранч'), '2022-07-06', 'Cake&Coffee', 1.000, 'На готовый омлет выложить авокадо четвертикнки, листья базилика. Сложить омлет пополам. Чиабатту поджарить на гриле.', 'original', 'На тарелку выложить чиабатту и гуакамоле в соусничке, омлет, украсить рукколой и посыпать молотым перцем.', 0.3162, 3, 12, 13, 174, 'технологическая карта составлена на основании акта проработки. По физико-химическим показателям соответствует требованиям ГОСТ РФ 50763-2007 "Кулинарная продукция, реализуемая населению". По микробиологическим показателям соответствует требованиям СанПиН 2.3.2 1078-01', 133);
INSERT INTO tech_cards (card_number, dish_name, organization_id, approval_date, application_area, portion_norm, technology, technology_source, serving_requirements, total_output_kg, proteins_per_100g, fats_per_100g, carbs_per_100g, calories_per_100g, note, source_page) VALUES ('00037', 'Омлет с грибами', (SELECT id FROM organizations WHERE name='Бранч'), '2022-07-06', 'Cake&Coffee', 1.000, 'На готовый омлет выложить обжаренные грибы и посыпать пармезаном. Сложить омлет пополам. Чиабатту жарим на гриле.', 'original', 'На тарелку выкладываем чиабатту и сливочный сыр в соусничке, омлет. Украшаем рукколой, посыпаем молотым Сыр творожный креметта', 0.2887, 6, 12, 11, 168, 'технологическая карта составлена на основании акта проработки. По физико-химическим показателям соответствует требованиям ГОСТ РФ 50763-2007 "Кулинарная продукция, реализуемая населению". По микробиологическим показателям соответствует требованиям СанПиН 2.3.2 1078-01', 134);
INSERT INTO tech_cards (card_number, dish_name, organization_id, approval_date, application_area, portion_norm, technology, technology_source, serving_requirements, total_output_kg, proteins_per_100g, fats_per_100g, carbs_per_100g, calories_per_100g, note, source_page) VALUES ('00038', 'Пашот с авокадо', (SELECT id FROM organizations WHERE name='Бранч'), '2022-07-06', 'Cake&Coffee', 1.000, 'Пашот сувид 2шт аккуратно разбиваем в прогреться 2-3минуты. Чиабатту жарим на делаем в хлебе ложкой углубление для', 'original', 'На тарелку выкладываем рядом друг с другом хлеб со сливочным сыром, в углубления выкладываем пашот, меду пашотом кладем авокадо и рукколу, посыпаем перцем и сбрызгиваем оливковым маслом.', 0.233, 0, 0, 0, 0, 'технологическая карта составлена на основании акта проработки. По физико-химическим показателям соответствует требованиям ГОСТ РФ 50763-2007 "Кулинарная продукция, реализуемая населению". По микробиологическим показателям соответствует требованиям СанПиН 2.3.2 1078-01', 135);
INSERT INTO tech_cards (card_number, dish_name, organization_id, approval_date, application_area, portion_norm, technology, technology_source, serving_requirements, total_output_kg, proteins_per_100g, fats_per_100g, carbs_per_100g, calories_per_100g, note, source_page) VALUES ('01569', 'Роял пашот', (SELECT id FROM organizations WHERE name='Бранч'), '2023-05-13', 'Cake&Coffee', 1.000, 'Чиабатту поджарить, намазать сливочным кипящую воду аккуратно разбить 1 яйцо прогреться 2-3минуты.', 'original', 'Выложить хлеб со сливочным сыром на плоскую тарелку, в углубдение выложить прогретое яйцо, на яйцо выложить тонко Сыр творожный креметта горелкой. Рядом с хлебом выложить рукколой, посыпать перцем, сбырзнуть', 0.198, 0, 0, 0, 0, 'технологическая карта составлена на основании акта проработки. По физико-химическим показателям соответствует требованиям ГОСТ РФ 50763-2007 "Кулинарная продукция, реализуемая населению". По микробиологическим показателям соответствует требованиям СанПиН 2.3.2 1078-01', 136);
INSERT INTO tech_cards (card_number, dish_name, organization_id, approval_date, application_area, portion_norm, technology, technology_source, serving_requirements, total_output_kg, proteins_per_100g, fats_per_100g, carbs_per_100g, calories_per_100g, note, source_page) VALUES ('00032', 'Скрембл с беконом и грибами', (SELECT id FROM organizations WHERE name='Бранч'), '2022-07-07', 'Cake&Coffee', 1.000, 'Яйца взболтать со сливками, посолить, готовить помешивая, так, что бы не и однородный. полоски бекона нарезать', 'original', 'На тарелку выложить чиабатту и сливочный сыр в соусничке, выложить скрембл, на скрембл выложить бекон с грибами, украсить рукколой, посыпать перцем.', 0.3463, 8, 25, 12, 301, 'технологическая карта составлена на основании акта проработки. По физико-химическим показателям соответствует требованиям ГОСТ РФ 50763-2007 "Кулинарная продукция, реализуемая населению". По микробиологическим показателям соответствует требованиям СанПиН 2.3.2 1078-01', 137);
INSERT INTO tech_cards (card_number, dish_name, organization_id, approval_date, application_area, portion_norm, technology, technology_source, serving_requirements, total_output_kg, proteins_per_100g, fats_per_100g, carbs_per_100g, calories_per_100g, note, source_page) VALUES ('00025', 'Каша 4 злака', (SELECT id FROM organizations WHERE name='Бранч'), '2021-12-23', 'Cake&Coffee', 1.000, '(от ии) Хлопья 4 злака (60 г) засыпать в кипящее молоко (150 мл), непрерывно помешивая. Варить на слабом огне при 90 °C, периодически помешивая, 5-7 минут. В конце добавить Масло сливочное (10 г) и Сахар-песок/Соль пищевая по вкусу. Накрыть крышкой, дать настояться 2-3 минуты. Подавать при 60-65 °C.', 'ai', NULL, 0.0565, 4, 5, 16, 127, 'технологическая карта составлена на основании акта проработки. По физико-химическим показателям соответствует требованиям ГОСТ РФ 50763-2007 "Кулинарная продукция, реализуемая населению". По микробиологическим показателям соответствует требованиям СанПиН 2.3.2 1078-01', 138);
INSERT INTO tech_cards (card_number, dish_name, organization_id, approval_date, application_area, portion_norm, technology, technology_source, serving_requirements, total_output_kg, proteins_per_100g, fats_per_100g, carbs_per_100g, calories_per_100g, note, source_page) VALUES ('00027', 'Каша гречневая', (SELECT id FROM organizations WHERE name='Бранч'), '2021-12-23', 'Cake&Coffee', 1.000, '(от ии) Хлопья гречневые (60 г) засыпать в кипящую воду (100 мл), варить 3 мин. Добавить молоко (50 мл). Варить на слабом огне при 90 °C, периодически помешивая, еще 5 минут. В конце добавить Масло сливочное (10 г) и Сахар-песок/Соль пищевая по вкусу. Накрыть крышкой, дать настояться 2-3 минуты. Подавать при 60-65 °C.', 'ai', NULL, 0.054, 4, 3, 19, 123, 'технологическая карта составлена на основании акта проработки. По физико-химическим показателям соответствует требованиям ГОСТ РФ 50763-2007 "Кулинарная продукция, реализуемая населению". По микробиологическим показателям соответствует требованиям СанПиН 2.3.2 1078-01', 139);
INSERT INTO tech_cards (card_number, dish_name, organization_id, approval_date, application_area, portion_norm, technology, technology_source, serving_requirements, total_output_kg, proteins_per_100g, fats_per_100g, carbs_per_100g, calories_per_100g, note, source_page) VALUES ('02411', 'Каша пшенная', (SELECT id FROM organizations WHERE name='Бранч'), '2021-12-23', 'Cake&Coffee', 1.000, '(от ии) Хлопья пшенные (60 г) промыть теплой водой. Засыпать в кипящую воду (150 мл), варить 10 мин, помешивая. Варить на слабом огне при 90 °C, периодически помешивая, еще 3-5 минут до загустения. В конце добавить Масло сливочное (10 г) и Сахар-песок/Соль пищевая по вкусу. Накрыть крышкой, дать настояться 2-3 минуты. Подавать при 60-65 °C.', 'ai', NULL, 0.055, 0, 0, 0, 0, 'технологическая карта составлена на основании акта проработки. По физико-химическим показателям соответствует требованиям ГОСТ РФ 50763-2007 "Кулинарная продукция, реализуемая населению". По микробиологическим показателям соответствует требованиям СанПиН 2.3.2 1078-01', 140);
INSERT INTO tech_cards (card_number, dish_name, organization_id, approval_date, application_area, portion_norm, technology, technology_source, serving_requirements, total_output_kg, proteins_per_100g, fats_per_100g, carbs_per_100g, calories_per_100g, note, source_page) VALUES ('00026', 'Каша рисовая', (SELECT id FROM organizations WHERE name='Бранч'), '2021-12-23', 'Cake&Coffee', 1.000, '(от ии) Хлопья рисовые (60 г) засыпать в кипящее молоко (150 мл), помешивая. Варить на слабом огне при 90 °C, периодически помешивая, 7-10 минут до мягкости. В конце добавить Масло сливочное (10 г) и Сахар-песок/Соль пищевая по вкусу. Накрыть крышкой, дать настояться 2-3 минуты. Подавать при 60-65 °C.', 'ai', NULL, 0.055, 3, 4, 4, 66, 'технологическая карта составлена на основании акта проработки. По физико-химическим показателям соответствует требованиям ГОСТ РФ 50763-2007 "Кулинарная продукция, реализуемая населению". По микробиологическим показателям соответствует требованиям СанПиН 2.3.2 1078-01', 141);
INSERT INTO tech_cards (card_number, dish_name, organization_id, approval_date, application_area, portion_norm, technology, technology_source, serving_requirements, total_output_kg, proteins_per_100g, fats_per_100g, carbs_per_100g, calories_per_100g, note, source_page) VALUES ('00024', 'Овсяная каша', (SELECT id FROM organizations WHERE name='Бранч'), '2021-12-23', 'Cake&Coffee', 1.000, '(от ии) Хлопья овсяные (60 г) засыпать в кипящее Молоко 3,2% (150 мл) или воду, помешивая венчиком. Варить на слабом огне при 90 °C, периодически помешивая, 5-7 минут. В конце добавить Масло сливочное (10 г) и Сахар-песок/Соль пищевая по вкусу. Накрыть крышкой, дать настояться 2-3 минуты. Подавать при 60-65 °C.', 'ai', NULL, 0.055, 5, 6, 15, 132, 'технологическая карта составлена на основании акта проработки. По физико-химическим показателям соответствует требованиям ГОСТ РФ 50763-2007 "Кулинарная продукция, реализуемая населению". По микробиологическим показателям соответствует требованиям СанПиН 2.3.2 1078-01', 142);
INSERT INTO tech_cards (card_number, dish_name, organization_id, approval_date, application_area, portion_norm, technology, technology_source, serving_requirements, total_output_kg, proteins_per_100g, fats_per_100g, carbs_per_100g, calories_per_100g, note, source_page) VALUES ('03076', 'Вафля', (SELECT id FROM organizations WHERE name='Бранч'), '2022-07-07', 'Cake&Coffee', 1.000, 'Нагреть вафельницу, режим Класика 3,', 'original', 'Выложить вафлю на тарелку, на вафлю положить 3 маршмеллоу, слегка опалить гарелкой, посыпать пудрой, соус положить в соусничку.', 0.105, 0, 0, 0, 0, 'технологическая карта составлена на основании акта проработки. По физико-химическим показателям соответствует требованиям ГОСТ РФ 50763-2007 "Кулинарная продукция, реализуемая населению". По микробиологическим показателям соответствует требованиям СанПиН 2.3.2 1078-01', 143);
INSERT INTO tech_cards (card_number, dish_name, organization_id, approval_date, application_area, portion_norm, technology, technology_source, serving_requirements, total_output_kg, proteins_per_100g, fats_per_100g, carbs_per_100g, calories_per_100g, note, source_page) VALUES ('02967', 'Вафля с лососем', (SELECT id FROM organizations WHERE name='Бранч'), '2021-09-08', 'Cake&Coffee', 1.000, 'На вафлю с одной стороны выложить углубление выложить яйцо пашот. С другой стороны выложить лосось, украсить поперчить, рукколу и лосось сбрызнуть', 'original', NULL, 0.224, 0, 0, 0, 0, 'технологическая карта составлена на основании акта проработки. По физико-химическим показателям соответствует требованиям ГОСТ РФ 50763-2007 "Кулинарная продукция, реализуемая населению". По микробиологическим показателям соответствует требованиям СанПиН 2.3.2 1078-01', 144);
INSERT INTO tech_cards (card_number, dish_name, organization_id, approval_date, application_area, portion_norm, technology, technology_source, serving_requirements, total_output_kg, proteins_per_100g, fats_per_100g, carbs_per_100g, calories_per_100g, note, source_page) VALUES ('02966', 'Вафля с мороженым и фруктами', (SELECT id FROM organizations WHERE name='Бранч'), '2021-09-08', 'Cake&Coffee', 1.000, 'На вафлю с одной стороны выложить нарезаные крупным кубиком, украсить', 'original', NULL, 0.278, 0, 0, 0, 0, 'технологическая карта составлена на основании акта проработки. По физико-химическим показателям соответствует требованиям ГОСТ РФ 50763-2007 "Кулинарная продукция, реализуемая населению". По микробиологическим показателям соответствует требованиям СанПиН 2.3.2 1078-01', 145);
INSERT INTO tech_cards (card_number, dish_name, organization_id, approval_date, application_area, portion_norm, technology, technology_source, serving_requirements, total_output_kg, proteins_per_100g, fats_per_100g, carbs_per_100g, calories_per_100g, note, source_page) VALUES ('00509', 'Вафля с шоколадом', (SELECT id FROM organizations WHERE name='Бранч'), '2021-09-09', 'Cake&Coffee', 1.000, '(от ии) Вафлю (полуфабрикат) обжарить в вафельнице при 180-200 °C 3-4 минуты до золотистого цвета и хруста. Выложить на тарелку. Полить Шоколадная глазурь (30 г), растопленной на водяной бане (40-45 °C). Украсить Маршмелоу (2-3 шт.) и листиком Мята. Посыпать Сахарная пудра. Подавать при 40-50 °C.', 'ai', NULL, 0.152, 0, 0, 0, 0, 'технологическая карта составлена на основании акта проработки. По физико-химическим показателям соответствует требованиям ГОСТ РФ 50763-2007 "Кулинарная продукция, реализуемая населению". По микробиологическим показателям соответствует требованиям СанПиН 2.3.2 1078-01', 146);
INSERT INTO tech_cards (card_number, dish_name, organization_id, approval_date, application_area, portion_norm, technology, technology_source, serving_requirements, total_output_kg, proteins_per_100g, fats_per_100g, carbs_per_100g, calories_per_100g, note, source_page) VALUES ('00510', 'Вафля со сливочным соусом', (SELECT id FROM organizations WHERE name='Бранч'), '2021-09-09', 'Cake&Coffee', 1.000, '(от ии) Вафлю обжарить в вафельнице при 180-200 °C 3-4 минуты до золотистого цвета. Выложить на тарелку. Полить сливочным соусом. Украсить Маршмелоу (2-3 шт.) и Мята. Посыпать Сахарная пудра. Подавать при 40-50 °C.', 'ai', 'Сливочно- И РЕАЛИЗАЦИИ ванильный соус', 0.152, 8, 5, 48, 272, 'технологическая карта составлена на основании акта проработки. По физико-химическим показателям соответствует требованиям ГОСТ РФ 50763-2007 "Кулинарная продукция, реализуемая населению". По микробиологическим показателям соответствует требованиям СанПиН 2.3.2 1078-01', 147);
INSERT INTO tech_cards (card_number, dish_name, organization_id, approval_date, application_area, portion_norm, technology, technology_source, serving_requirements, total_output_kg, proteins_per_100g, fats_per_100g, carbs_per_100g, calories_per_100g, note, source_page) VALUES ('03403', 'Вафля, банан, взрывная карамель', (SELECT id FROM organizations WHERE name='Бранч'), '2023-02-10', 'Cake&Coffee', 1.000, '(от ии) Вафлю обжарить в вафельнице при 180-200 °C 3-4 минуты до золотистого цвета. Бананы (50 г) нарезать кружочками, карамелизировать на сухой сковороде при 160-170 °C 1-2 минуты с добавлением сахара. Выложить вафлю, сверху — бананы и Маршмелоу. Подавать при 40-50 °C.', 'ai', 'Глазурь Карамельная', 0.316, 0, 0, 0, 0, 'технологическая карта составлена на основании акта проработки. По физико-химическим показателям соответствует требованиям ГОСТ РФ 50763-2007 "Кулинарная продукция, реализуемая населению". По микробиологическим показателям соответствует требованиям СанПиН 2.3.2 1078-01', 148);
INSERT INTO tech_cards (card_number, dish_name, organization_id, approval_date, application_area, portion_norm, technology, technology_source, serving_requirements, total_output_kg, proteins_per_100g, fats_per_100g, carbs_per_100g, calories_per_100g, note, source_page) VALUES ('03404', 'Вафля, сыр, черника', (SELECT id FROM organizations WHERE name='Бранч'), '2023-02-10', 'Cake&Coffee', 1.000, '(от ии) Вафлю обжарить в вафельнице при 180-200 °C 3-4 минуты до золотистого цвета. Выложить на тарелку. Выложить Сыр (творожный, 30 г) и варенье черника (20 г). Подавать при 40-50 °C.', 'ai', 'Сыр плавленый сливочный', 0.26, 0, 0, 0, 0, 'технологическая карта составлена на основании акта проработки. По физико-химическим показателям соответствует требованиям ГОСТ РФ 50763-2007 "Кулинарная продукция, реализуемая населению". По микробиологическим показателям соответствует требованиям СанПиН 2.3.2 1078-01', 149);
INSERT INTO tech_cards (card_number, dish_name, organization_id, approval_date, application_area, portion_norm, technology, technology_source, serving_requirements, total_output_kg, proteins_per_100g, fats_per_100g, carbs_per_100g, calories_per_100g, note, source_page) VALUES ('00059', 'Воздушные блинчики', (SELECT id FROM organizations WHERE name='Бранч'), '2017-03-14', 'Cake&Coffee', 1.000, '(от ии) Тесто на оладьи (порция 80-100 г) — перемешать перед использованием. Сковороду (с антипригарным покрытием) разогреть на среднем огне (170-180 °C). Маслом смазывать только первый блин (через силиконовую кисть). Выложить тесто тонким слоем, распределяя ложкой по сковороде. Жарить 1-1,5 минуты до золотистого цвета underside, перевернуть, жарить еще 30-40 секунд. Складывать блины стопкой. При подаче — посыпать Сахарная пудра. Температура подачи 45-55 °C.', 'ai', NULL, 0.155, 10, 2, 60, 292, 'технологическая карта составлена на основании акта проработки. По физико-химическим показателям соответствует требованиям ГОСТ РФ 50763-2007 "Кулинарная продукция, реализуемая населению". По микробиологическим показателям соответствует требованиям СанПиН 2.3.2 1078-01', 150);
INSERT INTO tech_cards (card_number, dish_name, organization_id, approval_date, application_area, portion_norm, technology, technology_source, serving_requirements, total_output_kg, proteins_per_100g, fats_per_100g, carbs_per_100g, calories_per_100g, note, source_page) VALUES ('02951', 'Панкейки с сиропом и ягодой', (SELECT id FROM organizations WHERE name='Бранч'), '2021-08-31', 'Cake&Coffee', 1.000, '4 панкейка выложить в центр десертной блинчики тарелки друг на друга, полить топингом, украсить ягодой и мятой, рядом отсадить', 'original', 'Не горелые, ровные блинчики!', 0.068, 0, 0, 0, 0, 'технологическая карта составлена на основании акта проработки. По физико-химическим показателям соответствует требованиям ГОСТ РФ 50763-2007 "Кулинарная продукция, реализуемая населению". По микробиологическим показателям соответствует требованиям СанПиН 2.3.2 1078-01', 151);
INSERT INTO tech_cards (card_number, dish_name, organization_id, approval_date, application_area, portion_norm, technology, technology_source, serving_requirements, total_output_kg, proteins_per_100g, fats_per_100g, carbs_per_100g, calories_per_100g, note, source_page) VALUES ('00058', 'Сладкий завтрак с оладьями и творогом', (SELECT id FROM organizations WHERE name='Бранч'), '2022-07-07', 'Cake&Coffee', 1.000, 'Выпечь 2 панкейка, в маленькую миску выложить творог, сметану и варенье в соуснички, банан разрезать вдоль, разогреть сливочное масло с сахаром в сотейнике, положить банан, добавить', 'original', 'На плоскую тарелку пставить миску с творогом и соуснички, выложить два панкейка, рядом банан фламбе. Панкейки посыпать пудрой, банан - миндальными лепестками. Украсить мятой или цветами.', 0.4005, 0, 0, 0, 0, 'технологическая карта составлена на основании акта проработки. По физико-химическим показателям соответствует требованиям ГОСТ РФ 50763-2007 "Кулинарная продукция, реализуемая населению". По микробиологическим показателям соответствует требованиям СанПиН 2.3.2 1078-01', 152);
INSERT INTO tech_cards (card_number, dish_name, organization_id, approval_date, application_area, portion_norm, technology, technology_source, serving_requirements, total_output_kg, proteins_per_100g, fats_per_100g, carbs_per_100g, calories_per_100g, note, source_page) VALUES ('02940', 'Сырники с карамелью', (SELECT id FROM organizations WHERE name='Бранч'), '2023-03-11', 'Cake&Coffee', 1.000, 'Три сырника по 50 гр обжарить на малом', 'original', 'Теплую карамель налить на дно шляпы, по центру выложить сырники в нахлест линией. хаотично рассыпать ягоду(15гр) по тарелке, посыпать пудрой, украсить мятой', 0.23, 0, 0, 0, 0, 'технологическая карта составлена на основании акта проработки. По физико-химическим показателям соответствует требованиям ГОСТ РФ 50763-2007 "Кулинарная продукция, реализуемая населению". По микробиологическим показателям соответствует требованиям СанПиН 2.3.2 1078-01', 153);
INSERT INTO tech_cards (card_number, dish_name, organization_id, approval_date, application_area, portion_norm, technology, technology_source, serving_requirements, total_output_kg, proteins_per_100g, fats_per_100g, carbs_per_100g, calories_per_100g, note, source_page) VALUES ('00061', 'Творожный десерт', (SELECT id FROM organizations WHERE name='Бранч'), '2022-03-19', 'Cake&Coffee', 1.000, 'Соус прогреть.', 'original', 'Заготовку на творожный десерт выложить в шляпу, полить соусом и вареньем, посыпать сахарной пудрой, украсить мятой или цветами.', 0.254, 0, 0, 0, 0, 'технологическая карта составлена на основании акта проработки. По физико-химическим показателям соответствует требованиям ГОСТ РФ 50763-2007 "Кулинарная продукция, реализуемая населению". По микробиологическим показателям соответствует требованиям СанПиН 2.3.2 1078-01', 154);
INSERT INTO tech_cards (card_number, dish_name, organization_id, approval_date, application_area, portion_norm, technology, technology_source, serving_requirements, total_output_kg, proteins_per_100g, fats_per_100g, carbs_per_100g, calories_per_100g, note, source_page) VALUES ('02913', 'Бекон доп. 50гр', (SELECT id FROM organizations WHERE name='Бранч'), '2021-07-16', 'Cake&Coffee', 1.000, '(от ии) Бекон нарезка (50 г) выложить на холодную сковороду (без масла). Включить средний огонь. Жарить 3-5 минут с каждой стороны до золотистого цвета и хрустящей корочки при 160-180 °C. Выложить на бумажное полотенце для удаления лишнего жира. Температура подачи 60-65 °C.', 'ai', NULL, 0.05, 3, 9, 9, 128, 'технологическая карта составлена на основании акта проработки. По физико-химическим показателям соответствует требованиям ГОСТ РФ 50763-2007 "Кулинарная продукция, реализуемая населению". По микробиологическим показателям соответствует требованиям СанПиН 2.3.2 1078-01', 155);
INSERT INTO tech_cards (card_number, dish_name, organization_id, approval_date, application_area, portion_norm, technology, technology_source, serving_requirements, total_output_kg, proteins_per_100g, fats_per_100g, carbs_per_100g, calories_per_100g, note, source_page) VALUES ('03148', 'Сырники с кремом из сгущенки', (SELECT id FROM organizations WHERE name='Бранч'), '2022-03-26', 'Cake&Coffee', 1.000, '(от ии) Тесто на сырники (порция ~100 г) размять, сформировать лепешку толщиной 1,5 см. Разогреть сковороду с Масло подсолнечное на среднем огне (170-180 °C). Обжарить сырники 2-3 минуты с каждой стороны до золотистой корочки. Выложить на тарелку. Сверху выложить Крем из вареной (сгущенки, 30 г). Украсить Клубника свежая и Цветы. Температура подачи 55-65 °C.', 'ai', 'сгущенки и сметаны', 0.185, 0, 0, 0, 0, 'технологическая карта составлена на основании акта проработки. По физико-химическим показателям соответствует требованиям ГОСТ РФ 50763-2007 "Кулинарная продукция, реализуемая населению". По микробиологическим показателям соответствует требованиям СанПиН 2.3.2 1078-01', 156);
INSERT INTO tech_cards (card_number, dish_name, organization_id, approval_date, application_area, portion_norm, technology, technology_source, serving_requirements, total_output_kg, proteins_per_100g, fats_per_100g, carbs_per_100g, calories_per_100g, note, source_page) VALUES ('02963', 'Авокадо тост', (SELECT id FROM organizations WHERE name='Бранч'), '2021-09-07', 'Cake&Coffee', 1.000, 'Чиабатту поджарить, намазать гуакамоле, сверху выложить авокадо слайсами, отсадить кремчиз, свекольный хумус, украсить рукколой и посыпать тыквенными семечками. Посолить, поперчить, сбрызнуть', 'original', NULL, 0.167, 0, 0, 0, 0, 'технологическая карта составлена на основании акта проработки. По физико-химическим показателям соответствует требованиям ГОСТ РФ 50763-2007 "Кулинарная продукция, реализуемая населению". По микробиологическим показателям соответствует требованиям СанПиН 2.3.2 1078-01', 157);
INSERT INTO tech_cards (card_number, dish_name, organization_id, approval_date, application_area, portion_norm, technology, technology_source, serving_requirements, total_output_kg, proteins_per_100g, fats_per_100g, carbs_per_100g, calories_per_100g, note, source_page) VALUES ('00046', 'Бруск. с лососем и авокадо', (SELECT id FROM organizations WHERE name='Бранч'), '2023-05-13', 'Cake&Coffee', 1.000, 'чиабатту 2шт поджарить на гриле, сделать сливочным сыром. Семгу нарезать тонкими креметта слайсами, авокадо нарезать слайсами.', 'original', 'На тарелку выложить два кусочка чиабатты, на творожный сыр выложить рванный айсберг, слайсы авокадо. Сверху ровно выложить слайсированный лосось.', 0.208, 14, 38, 17, 471, 'технологическая карта составлена на основании акта проработки. По физико-химическим показателям соответствует требованиям ГОСТ РФ 50763-2007 "Кулинарная продукция, реализуемая населению". По микробиологическим показателям соответствует требованиям СанПиН 2.3.2 1078-01', 158);
INSERT INTO tech_cards (card_number, dish_name, organization_id, approval_date, application_area, portion_norm, technology, technology_source, serving_requirements, total_output_kg, proteins_per_100g, fats_per_100g, carbs_per_100g, calories_per_100g, note, source_page) VALUES ('00045', 'Бруск. с лососем, каперсами и зеленью', (SELECT id FROM organizations WHERE name='Бранч'), '2023-02-11', 'Cake&Coffee', 1.000, 'чиабатту 2шт поджарить на гриле, сделать сливочным сыром.', 'original', 'Выложить чиабатту на тарелку, посыпать рубленой зеленью, каперсами, выложить лосось, сверху украсить рукколой.', 0.199, 0, 0, 0, 0, 'технологическая карта составлена на основании акта проработки. По физико-химическим показателям соответствует требованиям ГОСТ РФ 50763-2007 "Кулинарная продукция, реализуемая населению". По микробиологическим показателям соответствует требованиям СанПиН 2.3.2 1078-01', 159);
INSERT INTO tech_cards (card_number, dish_name, organization_id, approval_date, application_area, portion_norm, technology, technology_source, serving_requirements, total_output_kg, proteins_per_100g, fats_per_100g, carbs_per_100g, calories_per_100g, note, source_page) VALUES ('02811', 'Брускетта с уткой', (SELECT id FROM organizations WHERE name='Бранч'), '2021-07-14', 'Cake&Coffee', 1.000, '(от ии) Чиабатта (1 ломтик, 1,5 см) разрезать пополам. Разогреть гриль/сковороду до 200 °C. Обжарить хлеб с обеих сторон 1-2 минуты до характерных полосок гриля. Натереть чесноком. Грудка утиная вял (30 г) нарезать тонкими ломтиками. Вяленые помидоры (15 г) нарезать соломкой. Салат Руккола (10 г) выложить на поджаренную чиабатту. Сверху разложить утку и помидоры. Яйцо куриное — сварить вкрутую (10 минут в кипящей воде с момента закипания), очистить, разрезать на четвертинки. Выложить на чиабатту. Полить Масло оливковое (5 мл). Подавать при комнатной температуре.', 'ai', 'Сыр творожный креметта Свекольный бальзамик', 0.235, 8, 5, 48, 272, 'технологическая карта составлена на основании акта проработки. По физико-химическим показателям соответствует требованиям ГОСТ РФ 50763-2007 "Кулинарная продукция, реализуемая населению". По микробиологическим показателям соответствует требованиям СанПиН 2.3.2 1078-01', 160);
INSERT INTO tech_cards (card_number, dish_name, organization_id, approval_date, application_area, portion_norm, technology, technology_source, serving_requirements, total_output_kg, proteins_per_100g, fats_per_100g, carbs_per_100g, calories_per_100g, note, source_page) VALUES ('02999', 'Кесадилья с грибами', (SELECT id FROM organizations WHERE name='Бранч'), '2022-07-07', 'Cake&Coffee', 1.000, 'Тортилью положить на блинную сковороду, сверху выложить сыр, включить плитку и дождаться, когда тортилья поджарится, на пиццы сыр выложить жаренные шампиньоны, посолить, поперчить, сложить пополам.', 'original', 'На тарелку выложить кесадилью, разрезанную пополам и соусничку сметаны.', 0.232, 0, 0, 0, 0, 'технологическая карта составлена на основании акта проработки. По физико-химическим показателям соответствует требованиям ГОСТ РФ 50763-2007 "Кулинарная продукция, реализуемая населению". По микробиологическим показателям соответствует требованиям СанПиН 2.3.2 1078-01', 161);
INSERT INTO tech_cards (card_number, dish_name, organization_id, approval_date, application_area, portion_norm, technology, technology_source, serving_requirements, total_output_kg, proteins_per_100g, fats_per_100g, carbs_per_100g, calories_per_100g, note, source_page) VALUES ('00054', 'Кесадилья с курицей', (SELECT id FROM organizations WHERE name='Бранч'), '2022-07-07', 'Cake&Coffee', 1.000, 'Тортилью положить на блинную сковороду, сверху выложить сыр, включить плитку и помидор нарезать кубиком и обжарить, посолить, поперчить, добавить тобаско и пиццы горел. Выложить начинку на сыр и свернуть', 'original', 'На тарелку выложить сметану в соусничке и кесадилью, разрезанную пополам.', 0.381, 3, 2, 3, 40, 'технологическая карта составлена на основании акта проработки. По физико-химическим показателям соответствует требованиям ГОСТ РФ 50763-2007 "Кулинарная продукция, реализуемая населению". По микробиологическим показателям соответствует требованиям СанПиН 2.3.2 1078-01', 162);
INSERT INTO tech_cards (card_number, dish_name, organization_id, approval_date, application_area, portion_norm, technology, technology_source, serving_requirements, total_output_kg, proteins_per_100g, fats_per_100g, carbs_per_100g, calories_per_100g, note, source_page) VALUES ('00055', 'Кесадилья с тунцом', (SELECT id FROM organizations WHERE name='Бранч'), '2022-07-07', 'Cake&Coffee', 1.000, 'Тортилью положить на блинную сковороду, сверху выложить сыр, включить плитку и дождаться, когда тортилья поджарится. пиццы Огруец нарезать мелким кубиком, смешать с кукурузой, тунцом и майонезом, добавить соль и перец по вкусу. Выложить начинку и', 'original', 'На тарелку выложить соус песто в соусничке и кесадилью, разрезаную пополам.', 0.294, 0, 0, 0, 0, 'технологическая карта составлена на основании акта проработки. По физико-химическим показателям соответствует требованиям ГОСТ РФ 50763-2007 "Кулинарная продукция, реализуемая населению". По микробиологическим показателям соответствует требованиям СанПиН 2.3.2 1078-01', 163);
INSERT INTO tech_cards (card_number, dish_name, organization_id, approval_date, application_area, portion_norm, technology, technology_source, serving_requirements, total_output_kg, proteins_per_100g, fats_per_100g, carbs_per_100g, calories_per_100g, note, source_page) VALUES ('02331', 'Кесадилья сырная', (SELECT id FROM organizations WHERE name='Бранч'), '2022-07-07', 'Cake&Coffee', 1.000, 'Намазать тортилью творожным сыром, креметта посыпать моцареллой, чеддаром, рубленой зеленью, свернуть пополам и поджарить с', 'original', 'На тарелку выложить сметану в соусничке и разрезанную пополам кесадилью. Моцарелла для', 0.299, 0, 0, 0, 0, 'технологическая карта составлена на основании акта проработки. По физико-химическим показателям соответствует требованиям ГОСТ РФ 50763-2007 "Кулинарная продукция, реализуемая населению". По микробиологическим показателям соответствует требованиям СанПиН 2.3.2 1078-01', 164);
INSERT INTO tech_cards (card_number, dish_name, organization_id, approval_date, application_area, portion_norm, technology, technology_source, serving_requirements, total_output_kg, proteins_per_100g, fats_per_100g, carbs_per_100g, calories_per_100g, note, source_page) VALUES ('01489', 'Тартар из лосося', (SELECT id FROM organizations WHERE name='Бранч'), '2022-07-07', 'Cake&Coffee', 1.000, 'половинку тортильи поджарить на гриле с Лосось, огруец и красный лук нарезать мелким кубиком и смешать с оливковым', 'original', 'На плоскую тарелку выложить друг на друга в нахлест тортилью, на нее отсадить из мешка или сделать кнелю из гуакамоле, сверху выложить тартар, посыпать кунжутом и украсить микрозеленью.', 0.18, 0, 0, 0, 0, 'технологическая карта составлена на основании акта проработки. По физико-химическим показателям соответствует требованиям ГОСТ РФ 50763-2007 "Кулинарная продукция, реализуемая населению". По микробиологическим показателям соответствует требованиям СанПиН 2.3.2 1078-01', 165);
INSERT INTO tech_cards (card_number, dish_name, organization_id, approval_date, application_area, portion_norm, technology, technology_source, serving_requirements, total_output_kg, proteins_per_100g, fats_per_100g, carbs_per_100g, calories_per_100g, note, source_page) VALUES ('02786', 'Боул с лососем', (SELECT id FROM organizations WHERE name='Бранч'), '2022-10-01', 'Cake&Coffee', 1.000, 'Лосось слайс, авокадо слайс, огурец', 'original', 'В шляпу выкладываем по кругу: киноа, лосось обьемно, огурец, черри, авокадо, гуакамолле. сверху украсить рукколой, посыпать кунжутом. Соевый соус подать отдельно в соуснике.', 0.1948, 0, 0, 0, 0, 'технологическая карта составлена на основании акта проработки. По физико-химическим показателям соответствует требованиям ГОСТ РФ 50763-2007 "Кулинарная продукция, реализуемая населению". По микробиологическим показателям соответствует требованиям СанПиН 2.3.2 1078-01', 166);
INSERT INTO tech_cards (card_number, dish_name, organization_id, approval_date, application_area, portion_norm, technology, technology_source, serving_requirements, total_output_kg, proteins_per_100g, fats_per_100g, carbs_per_100g, calories_per_100g, note, source_page) VALUES ('02942', 'Буррата 1 шт.', (SELECT id FROM organizations WHERE name='Бранч'), '2021-08-06', 'Cake&Coffee', 1.000, '(от ии) Страчателла (100 г) достать из холодильника за 10 минут до подачи. Аккуратно выложить в центр глубокой тарелки ложкой, сохраняя текстуру. Полить Масло оливковое (10 мл) экстра вирджин. Посыпать Соль пищевая и свежемолотым Перец молотый. Подавать с подогретым хлебом/фокаччей при комнатной температуре (18-22 °C).', 'ai', NULL, 0.13, 0, 0, 0, 0, 'технологическая карта составлена на основании акта проработки. По физико-химическим показателям соответствует требованиям ГОСТ РФ 50763-2007 "Кулинарная продукция, реализуемая населению". По микробиологическим показателям соответствует требованиям СанПиН 2.3.2 1078-01', 167);
INSERT INTO tech_cards (card_number, dish_name, organization_id, approval_date, application_area, portion_norm, technology, technology_source, serving_requirements, total_output_kg, proteins_per_100g, fats_per_100g, carbs_per_100g, calories_per_100g, note, source_page) VALUES ('02500', 'Греческий кейк', (SELECT id FROM organizations WHERE name='Бранч'), '2020-12-23', 'Cake&Coffee', 1.000, '(от ии) Салат Айсберг (50 г) нарезать крупными кусками. Авокадо (50 г) разрезать пополам, нарезать дольками, сбрызнуть лимонным соком. Черри вес (30 г) разрезать пополам. Перец горошек — свежемолотый, Соль пищевая по вкусу. Выложить салат на тарелку горкой. Сверху выложить авокадо и черри. Посыпать Сыр фета (30 г, крошкой). Полить Масло оливковое (10 мл). Подавать при 5-10 °C, сразу после сборки.', 'ai', 'Сыр творожный креметта', 0.221, 12, 4, 1, 88, 'технологическая карта составлена на основании акта проработки. По физико-химическим показателям соответствует требованиям ГОСТ РФ 50763-2007 "Кулинарная продукция, реализуемая населению". По микробиологическим показателям соответствует требованиям СанПиН 2.3.2 1078-01', 168);
INSERT INTO tech_cards (card_number, dish_name, organization_id, approval_date, application_area, portion_norm, technology, technology_source, serving_requirements, total_output_kg, proteins_per_100g, fats_per_100g, carbs_per_100g, calories_per_100g, note, source_page) VALUES ('01122', 'Овощной салат', (SELECT id FROM organizations WHERE name='Бранч'), '2022-01-22', 'Cake&Coffee', 1.000, '(от ии) Черни вес (30 г) разрезать пополам. Огурец (30 г) нарезать полукольцами. Салат Айсберг (30 г) порвать руками. Салат Руккола (15 г) выложить. Лук красный (10 г) нарезать тонкими полукольцами, замочить в воде 5 мин для снятия горечи. Укроп (3 г) мелко нарубить. Соль пищевая, Перец молотый. Заправка: Масло оливковое (10 мл), Лимон (5 мл — сок). Выложить на тарелку, полить заправкой, посыпать укропом. Подавать при 5-10 °C.', 'ai', NULL, 0.36, 0, 0, 0, 0, 'технологическая карта составлена на основании акта проработки. По физико-химическим показателям соответствует требованиям ГОСТ РФ 50763-2007 "Кулинарная продукция, реализуемая населению". По микробиологическим показателям соответствует требованиям СанПиН 2.3.2 1078-01', 169);
INSERT INTO tech_cards (card_number, dish_name, organization_id, approval_date, application_area, portion_norm, technology, technology_source, serving_requirements, total_output_kg, proteins_per_100g, fats_per_100g, carbs_per_100g, calories_per_100g, note, source_page) VALUES ('02916', 'Салат с Буррата и томатами', (SELECT id FROM organizations WHERE name='Бранч'), '2021-07-21', 'Cake&Coffee', 1.000, 'Томаты нарезать дольками, лук перьями, смешать с базиликом (только листья), маслом оливковым, солью и перцем', 'original', 'Выложить салат на небольшую глубокую тарелку с одной стороны, буррату с другой, крутоны (3шт) подать отдельно в корзинке для хлеба.', 0.2605, 0, 0, 0, 0, 'технологическая карта составлена на основании акта проработки. По физико-химическим показателям соответствует требованиям ГОСТ РФ 50763-2007 "Кулинарная продукция, реализуемая населению". По микробиологическим показателям соответствует требованиям СанПиН 2.3.2 1078-01', 170);
INSERT INTO tech_cards (card_number, dish_name, organization_id, approval_date, application_area, portion_norm, technology, technology_source, serving_requirements, total_output_kg, proteins_per_100g, fats_per_100g, carbs_per_100g, calories_per_100g, note, source_page) VALUES ('01132', 'Салат с киноа', (SELECT id FROM organizations WHERE name='Бранч'), '2022-11-01', 'Cake&Coffee', 1.000, 'Красный лук нарезать мелкой сосолмкой, крупные вялки пополам. Обжарить лук, добавить черри, вялки, авокадо и киноа, прогреть. Заправить оливковым маслом,', 'original', 'При подаче добавить рукколу, перемешать, выложить в шляпу.', 0.182, 7, 10, 30, 238, 'технологическая карта составлена на основании акта проработки. По физико-химическим показателям соответствует требованиям ГОСТ РФ 50763-2007 "Кулинарная продукция, реализуемая населению". По микробиологическим показателям соответствует требованиям СанПиН 2.3.2 1078-01', 171);
INSERT INTO tech_cards (card_number, dish_name, organization_id, approval_date, application_area, portion_norm, technology, technology_source, serving_requirements, total_output_kg, proteins_per_100g, fats_per_100g, carbs_per_100g, calories_per_100g, note, source_page) VALUES ('02921', 'Салат с моцареллой, огурцом и черри', (SELECT id FROM organizations WHERE name='Бранч'), '2022-07-07', 'Cake&Coffee', 1.000, 'Черри пополам, огурец длинными слайсами тонкими широкими слайсами. Все смешать, перцем. Добавить листья базилика и', 'original', 'Аккуратно выложить в шляпу.', 0.201, 0, 0, 0, 0, 'технологическая карта составлена на основании акта проработки. По физико-химическим показателям соответствует требованиям ГОСТ РФ 50763-2007 "Кулинарная продукция, реализуемая населению". По микробиологическим показателям соответствует требованиям СанПиН 2.3.2 1078-01', 172);
INSERT INTO tech_cards (card_number, dish_name, organization_id, approval_date, application_area, portion_norm, technology, technology_source, serving_requirements, total_output_kg, proteins_per_100g, fats_per_100g, carbs_per_100g, calories_per_100g, note, source_page) VALUES ('02250', 'Салат с тунцом', (SELECT id FROM organizations WHERE name='Бранч'), '2023-02-12', 'Cake&Coffee', 1.000, 'Айсерг нарвать руками,огурец нарезать слайсами, черри пополам, смешать с рукколой, соевым соусом и сметаной.', 'original', 'Выложить салат в шляпу, сверху выложить консервированного тунца полоской, посыпать перцем и кунжутом.', 0.2396, 0, 0, 0, 0, 'технологическая карта составлена на основании акта проработки. По физико-химическим показателям соответствует требованиям ГОСТ РФ 50763-2007 "Кулинарная продукция, реализуемая населению". По микробиологическим показателям соответствует требованиям СанПиН 2.3.2 1078-01', 173);
INSERT INTO tech_cards (card_number, dish_name, organization_id, approval_date, application_area, portion_norm, technology, technology_source, serving_requirements, total_output_kg, proteins_per_100g, fats_per_100g, carbs_per_100g, calories_per_100g, note, source_page) VALUES ('00042', 'С-т. с Пармской ветчиной', (SELECT id FROM organizations WHERE name='Бранч'), '2021-09-10', 'Cake&Coffee', 1.000, '(от ии) Черни вес (30 г) разрезать пополам. Салат Айсберг (30 г) порвать. Салат Руккола (20 г) выложить. Пармезан (20 г) нарезать стружкой с помощью овощечистки. Пармская ветчина/прошутто (30 г) нарезать тонкими ломтиками, слегка обжарить на сухой сковороде 30 секунд при 180 °C до хруста. Выложить салаты на тарелку, сверху — черри, пармезан, прошутто. Заправка: Масло оливковое (10 мл), Бальзамический уксус (5 мл), Соль пищевая, Перец молотый. Подавать при 5-10 °C.', 'ai', 'Горчично-медовая завправка', 0.238, 0, 0, 0, 0, 'технологическая карта составлена на основании акта проработки. По физико-химическим показателям соответствует требованиям ГОСТ РФ 50763-2007 "Кулинарная продукция, реализуемая населению". По микробиологическим показателям соответствует требованиям СанПиН 2.3.2 1078-01', 174);
INSERT INTO tech_cards (card_number, dish_name, organization_id, approval_date, application_area, portion_norm, technology, technology_source, serving_requirements, total_output_kg, proteins_per_100g, fats_per_100g, carbs_per_100g, calories_per_100g, note, source_page) VALUES ('02379', 'Теплый салат с курицей', (SELECT id FROM organizations WHERE name='Бранч'), '2022-11-26', 'Cake&Coffee', 1.000, 'Шампиньоны дольками, болгарский перец бруском, лук толстым кольцом обжарить на добавить рукколу и перемешать. Подавать', 'original', 'Горчично-медовая завправка', 0.2356, 0, 0, 0, 0, 'технологическая карта составлена на основании акта проработки. По физико-химическим показателям соответствует требованиям ГОСТ РФ 50763-2007 "Кулинарная продукция, реализуемая населению". По микробиологическим показателям соответствует требованиям СанПиН 2.3.2 1078-01', 175);
INSERT INTO tech_cards (card_number, dish_name, organization_id, approval_date, application_area, portion_norm, technology, technology_source, serving_requirements, total_output_kg, proteins_per_100g, fats_per_100g, carbs_per_100g, calories_per_100g, note, source_page) VALUES ('02373', 'Цезарь с креветкамии', (SELECT id FROM organizations WHERE name='Бранч'), '2019-10-18', 'Cake&Coffee', 1.000, '(от ии) Черни вес (30 г) разрезать пополам. Салат Айсберг (30 г) порвать. Салат Руккола (15 г). Пармезан (15 г) — стружка. Креветки (80 г) — если замороженные: разморозить, обсушить. Обжарить на Масло оливковое (5 мл) на сильном огне (200 °C) по 1-1,5 минуты с каждой стороны до розового цвета. Белок (20 г) — сварить яйцо вкрутую (10 мин в кипятке), нарезать. Гренки (20 г) — нарезать хлеб кубиками, обжарить с Масло оливковое на сковороде при 180 °C до золотистого цвета (3-4 мин). Выложить салаты на тарелку, сверху — черри, креветки, белок, гренки, пармезан. Полить Домашний майонез (15 г). Подавать при 5-10 °C.', 'ai', NULL, 0.19, 0, 0, 0, 0, 'технологическая карта составлена на основании акта проработки. По физико-химическим показателям соответствует требованиям ГОСТ РФ 50763-2007 "Кулинарная продукция, реализуемая населению". По микробиологическим показателям соответствует требованиям СанПиН 2.3.2 1078-01', 176);
INSERT INTO tech_cards (card_number, dish_name, organization_id, approval_date, application_area, portion_norm, technology, technology_source, serving_requirements, total_output_kg, proteins_per_100g, fats_per_100g, carbs_per_100g, calories_per_100g, note, source_page) VALUES ('00041', 'Цезарь с курицей', (SELECT id FROM organizations WHERE name='Бранч'), '2022-07-07', 'Cake&Coffee', 1.000, 'Айсберг нарвать, смешать с рукколой и майонезом. Грудку су вид поджарить и прогреть на сковороде на купаже посолить, поперчить.', 'original', 'В шляпу выложить микс салат, три черри по краям, посыпать пармезаном, сверху выложить куриную грудку, нарезанную под углом 45 на 4-5 частей, положить два крутона.', 0.327, 12, 4, 1, 88, 'технологическая карта составлена на основании акта проработки. По физико-химическим показателям соответствует требованиям ГОСТ РФ 50763-2007 "Кулинарная продукция, реализуемая населению". По микробиологическим показателям соответствует требованиям СанПиН 2.3.2 1078-01', 177);
INSERT INTO tech_cards (card_number, dish_name, organization_id, approval_date, application_area, portion_norm, technology, technology_source, serving_requirements, total_output_kg, proteins_per_100g, fats_per_100g, carbs_per_100g, calories_per_100g, note, source_page) VALUES ('02006', 'Цезарь с лососем', (SELECT id FROM organizations WHERE name='Бранч'), '2022-07-07', 'Cake&Coffee', 1.000, 'Айсберг нарвать, смешать с рукколой и', 'original', 'Микс салат выложить в шляпу, три черри целиком по краям, микс посыпать пармезаном, сверху выложить слайсы слабосоленого лосося объемно, рядом положить два крутона.', 0.2646, 0, 0, 0, 0, 'технологическая карта составлена на основании акта проработки. По физико-химическим показателям соответствует требованиям ГОСТ РФ 50763-2007 "Кулинарная продукция, реализуемая населению". По микробиологическим показателям соответствует требованиям СанПиН 2.3.2 1078-01', 178);
INSERT INTO tech_cards (card_number, dish_name, organization_id, approval_date, application_area, portion_norm, technology, technology_source, serving_requirements, total_output_kg, proteins_per_100g, fats_per_100g, carbs_per_100g, calories_per_100g, note, source_page) VALUES ('02374', 'Шеф-салат с ростбифом', (SELECT id FROM organizations WHERE name='Бранч'), '2022-07-07', 'Cake&Coffee', 1.000, 'Шампиньоны(крупно) и ростбиф обжарить. вырезка Огурец слайсом, черри пополам, смешать с', 'original', 'Выложить микс салат с овощами в шляпу, сверху выложить жаренные шампы и ростбиф.', 0.182, 0, 0, 0, 0, 'технологическая карта составлена на основании акта проработки. По физико-химическим показателям соответствует требованиям ГОСТ РФ 50763-2007 "Кулинарная продукция, реализуемая населению". По микробиологическим показателям соответствует требованиям СанПиН 2.3.2 1078-01', 179);
INSERT INTO tech_cards (card_number, dish_name, organization_id, approval_date, application_area, portion_norm, technology, technology_source, serving_requirements, total_output_kg, proteins_per_100g, fats_per_100g, carbs_per_100g, calories_per_100g, note, source_page) VALUES ('02074', 'Борщ тапас', (SELECT id FROM organizations WHERE name='Бранч'), '2020-12-28', 'Cake&Coffee', 1.000, '(от ии) Борщ п/ф (200 г) разморозить, выложить в кастрюлю. Довести до кипения на среднем огне. Варить при 95-98 °C 5-7 минут до прогрева. Телячьи щеки (30 г, готовые томленые) нарезать, разогреть в борще. Хлеб Альпийский (30 г) — нарезать ломтиками, подсушить в духовке при 180 °C 3-5 минут до хруста. Чеснок (1 зубчик) натереть на теплый хлеб. Разлить борщ в подогретую глубокую тарелку. Сверху — Сметана 30% (15 г), посыпать Петрушка. Отдельно подать гренки с чесноком. Температура подачи 70-75 °C.', 'ai', NULL, 0.4013, 0, 0, 0, 0, 'технологическая карта составлена на основании акта проработки. По физико-химическим показателям соответствует требованиям ГОСТ РФ 50763-2007 "Кулинарная продукция, реализуемая населению". По микробиологическим показателям соответствует требованиям СанПиН 2.3.2 1078-01', 180);
INSERT INTO tech_cards (card_number, dish_name, organization_id, approval_date, application_area, portion_norm, technology, technology_source, serving_requirements, total_output_kg, proteins_per_100g, fats_per_100g, carbs_per_100g, calories_per_100g, note, source_page) VALUES ('02009', 'Куриный бульон', (SELECT id FROM organizations WHERE name='Бранч'), '2018-10-02', 'Cake&Coffee', 1.000, '(от ии) Бульон куриный (250 мл) довести до кипения, снять пену. Убавить огонь, варить при 95-98 °C. Спагетти (30 г) сломать на 2-3 части, засыпать в кипящий бульон. Варить 8-10 минут до аль денте. Филе грудки куриная (30 г) нарезать тонкими ломтиками, добавить в суп. Варить 3-5 минут до готовности. В конце добавить Соль пищевая, Перец молотый по вкусу. Зелень (Петрушка/Укроп, 3 г) мелко нарубить. Разлить в подогретую тарелку/кружку. Посыпать зеленью. Температура подачи 70-75 °C.', 'ai', 'Мальтальятти Сухари панировочные', 0.338, 0, 0, 0, 0, 'технологическая карта составлена на основании акта проработки. По физико-химическим показателям соответствует требованиям ГОСТ РФ 50763-2007 "Кулинарная продукция, реализуемая населению". По микробиологическим показателям соответствует требованиям СанПиН 2.3.2 1078-01', 181);
INSERT INTO tech_cards (card_number, dish_name, organization_id, approval_date, application_area, portion_norm, technology, technology_source, serving_requirements, total_output_kg, proteins_per_100g, fats_per_100g, carbs_per_100g, calories_per_100g, note, source_page) VALUES ('00021', 'Суп грибной', (SELECT id FROM organizations WHERE name='Бранч'), '2022-04-30', 'Cake&Coffee', 1.000, '(от ии) Грибное пюре (готовое, 200 г) выложить в кастрюлю, развести водой или бульоном до нужной консистенции. Довести до кипения на среднем огне, помешивая. Убавить огонь, варить 3-5 минут при 90-95 °C. Добавить Сливки 33% (30 мл), перемешать. Соль пищевая и Перец молотый по вкусу. Чиабатта (30 г) — нарезать ломтиками, сбрызнуть Масло оливковое, подсушить в духовке при 180 °C 5-7 минут до хруста. Разлить суп в тарелку. Сверху выложить Шампиньоны (20 г, нарезанные пластинками и обжаренные на масле 3-4 мин при 180 °C). Добавить Песто (5 г) и гренки. Температура подачи 70-75 °C.', 'ai', NULL, 0.2799, 0, 0, 0, 0, 'технологическая карта составлена на основании акта проработки. По физико-химическим показателям соответствует требованиям ГОСТ РФ 50763-2007 "Кулинарная продукция, реализуемая населению". По микробиологическим показателям соответствует требованиям СанПиН 2.3.2 1078-01', 182);
INSERT INTO tech_cards (card_number, dish_name, organization_id, approval_date, application_area, portion_norm, technology, technology_source, serving_requirements, total_output_kg, proteins_per_100g, fats_per_100g, carbs_per_100g, calories_per_100g, note, source_page) VALUES ('01347', 'Суп кукурузный', (SELECT id FROM organizations WHERE name='Бранч'), '2017-04-27', 'Cake&Coffee', 1.000, '(от ии) Кукурузный суп (готовый, 250 мл) вылить в кастрюлю. Нагреть на среднем огне до 90-95 °C, помешивая, не доводя до бурного кипения. При необходимости разбавить водой/сливками до нужной консистенции. Разлить в подогретую тарелку. Температура подачи 70-75 °C.', 'ai', NULL, 0.2, 0, 0, 0, 0, 'технологическая карта составлена на основании акта проработки. По физико-химическим показателям соответствует требованиям ГОСТ РФ 50763-2007 "Кулинарная продукция, реализуемая населению". По микробиологическим показателям соответствует требованиям СанПиН 2.3.2 1078-01', 183);
INSERT INTO tech_cards (card_number, dish_name, organization_id, approval_date, application_area, portion_norm, technology, technology_source, serving_requirements, total_output_kg, proteins_per_100g, fats_per_100g, carbs_per_100g, calories_per_100g, note, source_page) VALUES ('00022', 'Суп луковый', (SELECT id FROM organizations WHERE name='Бранч'), '2017-02-11', 'Cake&Coffee', 1.000, '(от ии) Луковое пюре (готовое, 200 г) выложить в кастрюлю, развести водой/бульоном. Довести до кипения, убавить огонь. Варить 5 минут при 90-95 °C, помешивая. Добавить Сливки 33% (30 мл), Соль пищевая, Перец горошек по вкусу. Перемешать. Чиабатта (30 г) — нарезать кубиками, сбрызнуть Масло оливковое, подсушить в духовке при 180 °C 5-7 минут до хруста (крутоны). Пармезан (10 г) натереть на мелкой терке. Разлить суп в тарелку. Сверху выложить крутоны, посыпать пармезаном, добавить Песто (3 г). Температура подачи 70-75 °C.', 'ai', NULL, 0.2874, 0, 0, 0, 0, 'технологическая карта составлена на основании акта проработки. По физико-химическим показателям соответствует требованиям ГОСТ РФ 50763-2007 "Кулинарная продукция, реализуемая населению". По микробиологическим показателям соответствует требованиям СанПиН 2.3.2 1078-01', 184);
INSERT INTO tech_cards (card_number, dish_name, organization_id, approval_date, application_area, portion_norm, technology, technology_source, serving_requirements, total_output_kg, proteins_per_100g, fats_per_100g, carbs_per_100g, calories_per_100g, note, source_page) VALUES ('02055', 'Сырный суп', (SELECT id FROM organizations WHERE name='Бранч'), '2018-12-12', 'Cake&Coffee', 1.000, '(от ии) Масло подсолнечное (10 г) разогреть в кастрюле на среднем огне (160-170 °C). Чеснок (3 г) мелко нарубить, Лук репчатый (30 г) нарезать мелким кубиком. Обжарить 3-4 минуты до прозрачности лука. Картофель (80 г) нарезать кубиком 1,5 см. Добавить в кастрюлю, залить водой/бульоном (300 мл). Довести до кипения, варить 10-12 минут при 95-98 °C до мягкости картофеля. Морковь (30 г) натереть на крупной терке, добавить в суп. Варить еще 5 минут. Бекон (20 г) нарезать соломкой, обжарить на отдельной сковороде при 180 °C до хруста (3-5 мин). Снять суп с огня. Добавить Сыр плавленый/твердый (40 г), перемешивать до растворения 1-2 минуты. Добавить Сливки 33% (30 мл), Соль пищевая, Перец молотый, Петрушка (3 г, нарубленная). Разлить в тарелки. Сверху — бекон и гренки (Чиабатта, обжаренная в духовке 180 °C, 5 мин). Температура подачи 70-75 °C.', 'ai', 'Сыр творожный креметта', 0.3065, 0, 0, 0, 0, 'технологическая карта составлена на основании акта проработки. По физико-химическим показателям соответствует требованиям ГОСТ РФ 50763-2007 "Кулинарная продукция, реализуемая населению". По микробиологическим показателям соответствует требованиям СанПиН 2.3.2 1078-01', 185);
INSERT INTO tech_cards (card_number, dish_name, organization_id, approval_date, application_area, portion_norm, technology, technology_source, serving_requirements, total_output_kg, proteins_per_100g, fats_per_100g, carbs_per_100g, calories_per_100g, note, source_page) VALUES ('01688', 'Уха с семгой', (SELECT id FROM organizations WHERE name='Бранч'), '2021-10-02', 'Cake&Coffee', 1.000, 'Заготовка на уху : с помидорами, отварной картофель, Уха: филе лосося в сотейнике, добавляем 270 выключаем плиту и добавляем сливки,', 'original', NULL, 0.319, 0, 0, 0, 0, 'технологическая карта составлена на основании акта проработки. По физико-химическим показателям соответствует требованиям ГОСТ РФ 50763-2007 "Кулинарная продукция, реализуемая населению". По микробиологическим показателям соответствует требованиям СанПиН 2.3.2 1078-01', 186);
INSERT INTO tech_cards (card_number, dish_name, organization_id, approval_date, application_area, portion_norm, technology, technology_source, serving_requirements, total_output_kg, proteins_per_100g, fats_per_100g, carbs_per_100g, calories_per_100g, note, source_page) VALUES ('02509', 'Лапша.', (SELECT id FROM organizations WHERE name='Бранч'), '2020-07-22', 'Cake&Coffee', 1.000, '(от ии) Вскипятить воду (1 л на 100 г пасты), посолить (10 г соли на 1 л). Спагетти (80 г) засыпать в кипящую воду. Варить 8-10 минут до аль денте (проверять на откус — центр должен остаться слегка упругим). Откинуть на дуршлаг, сохранив 50 мл воды от варки. В сковороду добавить Масло сливочное (15 г), растопить на слабом огне (130-140 °C). Добавить спагетти, перемешать. Добавить воду от варки, помешивать 30 секунд для образования эмульсии. Подавать немедленно. Температура подачи 60-65 °C.', 'ai', NULL, 0.18, 14, 24, 41, 437, 'технологическая карта составлена на основании акта проработки. По физико-химическим показателям соответствует требованиям ГОСТ РФ 50763-2007 "Кулинарная продукция, реализуемая населению". По микробиологическим показателям соответствует требованиям СанПиН 2.3.2 1078-01', 187);
INSERT INTO tech_cards (card_number, dish_name, organization_id, approval_date, application_area, portion_norm, technology, technology_source, serving_requirements, total_output_kg, proteins_per_100g, fats_per_100g, carbs_per_100g, calories_per_100g, note, source_page) VALUES ('00051', 'Паста с беконом', (SELECT id FROM organizations WHERE name='Бранч'), '2022-12-01', 'Cake&Coffee', 1.000, 'Обжарить лук, бекон и чеснок, добавит вино и выпарить, добавить сливки и пасту, довести до вкуса солью и перцем.', 'original', 'Аккуратно выложить в шляпу, поперчить.', 0.2361, 14, 24, 41, 437, 'технологическая карта составлена на основании акта проработки. По физико-химическим показателям соответствует требованиям ГОСТ РФ 50763-2007 "Кулинарная продукция, реализуемая населению". По микробиологическим показателям соответствует требованиям СанПиН 2.3.2 1078-01', 188);
INSERT INTO tech_cards (card_number, dish_name, organization_id, approval_date, application_area, portion_norm, technology, technology_source, serving_requirements, total_output_kg, proteins_per_100g, fats_per_100g, carbs_per_100g, calories_per_100g, note, source_page) VALUES ('00052', 'Паста с лососем', (SELECT id FROM organizations WHERE name='Бранч'), '2022-12-01', 'Cake&Coffee', 1.000, 'Обжарить лук, чеснок и лосось с/с пластиками, добавить вино и выпарить, добавить сливки и пасту, довести до вкуса', 'original', 'Аккуратно выложить в шляпу, поперчить.', 0.2444, 14, 32, 45, 525, 'технологическая карта составлена на основании акта проработки. По физико-химическим показателям соответствует требованиям ГОСТ РФ 50763-2007 "Кулинарная продукция, реализуемая населению". По микробиологическим показателям соответствует требованиям СанПиН 2.3.2 1078-01', 189);
INSERT INTO tech_cards (card_number, dish_name, organization_id, approval_date, application_area, portion_norm, technology, technology_source, serving_requirements, total_output_kg, proteins_per_100g, fats_per_100g, carbs_per_100g, calories_per_100g, note, source_page) VALUES ('03161', 'Паста с томленой говядиной и овощами', (SELECT id FROM organizations WHERE name='Бранч'), '2022-04-18', 'Cake&Coffee', 1.000, 'Нарезать лук кубиком, цукини и телячьи щечки соломкой. Обжарить лук, добавить цукини, щеки, щечный соус и сливки. В готовый соус добавить отваренную пасту, соль, перец.', 'original', 'Выложить в шляпу, украсить мелкорезанным зеленым луком.', 0.2683, 0, 0, 0, 0, 'технологическая карта составлена на основании акта проработки. По физико-химическим показателям соответствует требованиям ГОСТ РФ 50763-2007 "Кулинарная продукция, реализуемая населению". По микробиологическим показателям соответствует требованиям СанПиН 2.3.2 1078-01', 190);
INSERT INTO tech_cards (card_number, dish_name, organization_id, approval_date, application_area, portion_norm, technology, technology_source, serving_requirements, total_output_kg, proteins_per_100g, fats_per_100g, carbs_per_100g, calories_per_100g, note, source_page) VALUES ('01133', 'Горячий ростбиф с картофелем', (SELECT id FROM organizations WHERE name='Бранч'), '2022-07-09', 'Cake&Coffee', 1.000, 'Ростбиф сувидированный обжарить на растительном масле, добавить сливочное дольками обжарить вместе, посолить, поперчить.', 'original', 'Выложить гарнир в шляпу, ростбиф нарезать на три части под прямым углом, выложить на гарнир внахлест.поперчить и посолить мясо, украсить микрозеленью.', 0.3525, 0, 0, 0, 0, 'технологическая карта составлена на основании акта проработки. По физико-химическим показателям соответствует требованиям ГОСТ РФ 50763-2007 "Кулинарная продукция, реализуемая населению". По микробиологическим показателям соответствует требованиям СанПиН 2.3.2 1078-01', 191);
INSERT INTO tech_cards (card_number, dish_name, organization_id, approval_date, application_area, portion_norm, technology, technology_source, serving_requirements, total_output_kg, proteins_per_100g, fats_per_100g, carbs_per_100g, calories_per_100g, note, source_page) VALUES ('01129', 'Кур. грудка с овощами альденте', (SELECT id FROM organizations WHERE name='Бранч'), '2022-07-09', 'Cake&Coffee', 1.000, 'Моцареллу нарезать мелким кубиком, Начинка д/куриной нарубить, все смешать и заправить поместить начинку в карман, обжарить нарезать дольками, болгарский перец дольками. Обжарить овощи до альдэнтэ, посолить, поперчить.', 'original', 'На плоскую тарелку выложить овощи по линии, рядом - грудку, украсить черри, разрезанной пополам и соцветием базилика.', 0.33, 0, 0, 0, 0, 'технологическая карта составлена на основании акта проработки. По физико-химическим показателям соответствует требованиям ГОСТ РФ 50763-2007 "Кулинарная продукция, реализуемая населению". По микробиологическим показателям соответствует требованиям СанПиН 2.3.2 1078-01', 192);
INSERT INTO tech_cards (card_number, dish_name, organization_id, approval_date, application_area, portion_norm, technology, technology_source, serving_requirements, total_output_kg, proteins_per_100g, fats_per_100g, carbs_per_100g, calories_per_100g, note, source_page) VALUES ('01726', 'Телячьи щечки', (SELECT id FROM organizations WHERE name='Бранч'), '2022-04-19', 'Cake&Coffee', 1.000, 'Пюре выкладываем в глубокую тарелку щеки выкладываем на кнели, посыпаем', 'original', 'Если щеки подаются с другим гарниром - соус в соусничку.', 0.108, 0, 0, 0, 0, 'технологическая карта составлена на основании акта проработки. По физико-химическим показателям соответствует требованиям ГОСТ РФ 50763-2007 "Кулинарная продукция, реализуемая населению". По микробиологическим показателям соответствует требованиям СанПиН 2.3.2 1078-01', 193);
INSERT INTO tech_cards (card_number, dish_name, organization_id, approval_date, application_area, portion_norm, technology, technology_source, serving_requirements, total_output_kg, proteins_per_100g, fats_per_100g, carbs_per_100g, calories_per_100g, note, source_page) VALUES ('02705', 'Филе куриное су вид с цукини', (SELECT id FROM organizations WHERE name='Бранч'), '2022-07-09', 'Cake&Coffee', 1.000, 'Куриную грудку сувид обжарить на треугольника. Цукини и морковь нарезать бруском, морковь бланшировать и обжарить', 'original', 'Выложить в шляпу гарнир, на гарнир куриную грудку внахлест, посолить, поперчить, украситьь микрозеленью.', 0.286, 0, 0, 0, 0, 'технологическая карта составлена на основании акта проработки. По физико-химическим показателям соответствует требованиям ГОСТ РФ 50763-2007 "Кулинарная продукция, реализуемая населению". По микробиологическим показателям соответствует требованиям СанПиН 2.3.2 1078-01', 194);
INSERT INTO tech_cards (card_number, dish_name, organization_id, approval_date, application_area, portion_norm, technology, technology_source, serving_requirements, total_output_kg, proteins_per_100g, fats_per_100g, carbs_per_100g, calories_per_100g, note, source_page) VALUES ('00995', 'Пицца Маргарита', (SELECT id FROM organizations WHERE name='Бранч'), '2021-12-15', 'Cake&Coffee', 1.000, 'Раскатать круг теста ~33 см, смазать посыпать тертой моцареллой, запечь в выложить на пергамент, нарезать на 6 украсить соцветием базилика.', 'original', 'Тесто не должно подгореть!', 0.381, 0, 0, 0, 0, 'технологическая карта составлена на основании акта проработки. По физико-химическим показателям соответствует требованиям ГОСТ РФ 50763-2007 "Кулинарная продукция, реализуемая населению". По микробиологическим показателям соответствует требованиям СанПиН 2.3.2 1078-01', 195);
INSERT INTO tech_cards (card_number, dish_name, organization_id, approval_date, application_area, portion_norm, technology, technology_source, serving_requirements, total_output_kg, proteins_per_100g, fats_per_100g, carbs_per_100g, calories_per_100g, note, source_page) VALUES ('02040', 'Пицца Пепперони', (SELECT id FROM organizations WHERE name='Бранч'), '2021-12-15', 'Cake&Coffee', 1.000, 'Собрать маргариту; Выложить тонко наслайсированную пепперони; Запечь в пиццепечи; Нарезать на 6 кусочков.', 'original', 'Тесто не должно подгореть!', 0.4031, 0, 0, 0, 0, 'технологическая карта составлена на основании акта проработки. По физико-химическим показателям соответствует требованиям ГОСТ РФ 50763-2007 "Кулинарная продукция, реализуемая населению". По микробиологическим показателям соответствует требованиям СанПиН 2.3.2 1078-01', 196);
INSERT INTO tech_cards (card_number, dish_name, organization_id, approval_date, application_area, portion_norm, technology, technology_source, serving_requirements, total_output_kg, proteins_per_100g, fats_per_100g, carbs_per_100g, calories_per_100g, note, source_page) VALUES ('02978', 'Пицца с беконом', (SELECT id FROM organizations WHERE name='Бранч'), '2021-12-15', 'Cake&Coffee', 1.000, 'Собрать маргориту; Бекон нарезать курпными квадратами, маслины нарезать кольцами, выложить на Запечь в пиццепечи, украсить петрушкой, пиццы нарезать на 6 кусочков.', 'original', 'Тесто не должно подгореть!', 0.459, 0, 0, 0, 0, 'технологическая карта составлена на основании акта проработки. По физико-химическим показателям соответствует требованиям ГОСТ РФ 50763-2007 "Кулинарная продукция, реализуемая населению". По микробиологическим показателям соответствует требованиям СанПиН 2.3.2 1078-01', 197);
INSERT INTO tech_cards (card_number, dish_name, organization_id, approval_date, application_area, portion_norm, technology, technology_source, serving_requirements, total_output_kg, proteins_per_100g, fats_per_100g, carbs_per_100g, calories_per_100g, note, source_page) VALUES ('02977', 'Пицца с курицей и грибами', (SELECT id FROM organizations WHERE name='Бранч'), '2021-12-15', 'Cake&Coffee', 1.000, 'Собрать маргориту; Курицу и грибы нарезать слайсами, выложить на пиццу; Запечь в пиццепечи, нарезать на 6 кусочков; пиццы Украсить петрушкой и кунжутом.', 'original', 'Тесто не должно подгореть!', 0.482, 0, 0, 0, 0, 'технологическая карта составлена на основании акта проработки. По физико-химическим показателям соответствует требованиям ГОСТ РФ 50763-2007 "Кулинарная продукция, реализуемая населению". По микробиологическим показателям соответствует требованиям СанПиН 2.3.2 1078-01', 198);
INSERT INTO tech_cards (card_number, dish_name, organization_id, approval_date, application_area, portion_norm, technology, technology_source, serving_requirements, total_output_kg, proteins_per_100g, fats_per_100g, carbs_per_100g, calories_per_100g, note, source_page) VALUES ('00991', 'Пицца с лососем', (SELECT id FROM organizations WHERE name='Бранч'), '2021-12-01', 'Cake&Coffee', 1.000, 'Собрать маргориту; Выложить 6 шариков из творожного сыра; Запечь в пиццепечи; пиццы Нарезать на 6 кусочков; Нарезать 6 пластиков семги по 10 грамм и выложить по пластику на каждый шарик креметта Посыпать петрушкой и кунжутом.', 'original', 'тесто не должно подгореть! ПЛАСТИКИ СЕМГИ ДОЛЖНЫ БЫТЬ РОВНЫЕ И КРАСИВЫЕ!', 0.5516, 0, 0, 0, 0, 'технологическая карта составлена на основании акта проработки. По физико-химическим показателям соответствует требованиям ГОСТ РФ 50763-2007 "Кулинарная продукция, реализуемая населению". По микробиологическим показателям соответствует требованиям СанПиН 2.3.2 1078-01', 199);
INSERT INTO tech_cards (card_number, dish_name, organization_id, approval_date, application_area, portion_norm, technology, technology_source, serving_requirements, total_output_kg, proteins_per_100g, fats_per_100g, carbs_per_100g, calories_per_100g, note, source_page) VALUES ('00996', 'Пицца с пармой', (SELECT id FROM organizations WHERE name='Бранч'), '2021-12-01', 'Cake&Coffee', 1.000, 'Собрать и выпечь маргориту; Нарезать на 6 кусочков; на каждый кусочек выложитьвяленые четвертинки; пиццы украсить рукколой; сверху на рукколу выложить тонко', 'original', 'Тесто не должно подгореть!', 0.4542, 0, 0, 0, 0, 'технологическая карта составлена на основании акта проработки. По физико-химическим показателям соответствует требованиям ГОСТ РФ 50763-2007 "Кулинарная продукция, реализуемая населению". По микробиологическим показателям соответствует требованиям СанПиН 2.3.2 1078-01', 200);
INSERT INTO tech_cards (card_number, dish_name, organization_id, approval_date, application_area, portion_norm, technology, technology_source, serving_requirements, total_output_kg, proteins_per_100g, fats_per_100g, carbs_per_100g, calories_per_100g, note, source_page) VALUES ('00992', 'Пицца сырная', (SELECT id FROM organizations WHERE name='Бранч'), '2021-12-15', 'Cake&Coffee', 1.000, 'Раскатать тесто ~33 см, смазать сливками; кусочками и выложить на сливки; Посыпать моцареллой и выложить пластики чеддара; пиццы Выпечь в пиццепечи; Нарезать на 6 кусочков, украсить соцветием', 'original', 'Сыр творожный креметта', 0.3456, 0, 0, 0, 0, 'технологическая карта составлена на основании акта проработки. По физико-химическим показателям соответствует требованиям ГОСТ РФ 50763-2007 "Кулинарная продукция, реализуемая населению". По микробиологическим показателям соответствует требованиям СанПиН 2.3.2 1078-01', 201);
INSERT INTO tech_cards (card_number, dish_name, organization_id, approval_date, application_area, portion_norm, technology, technology_source, serving_requirements, total_output_kg, proteins_per_100g, fats_per_100g, carbs_per_100g, calories_per_100g, note, source_page) VALUES ('01721', 'Фокачча', (SELECT id FROM organizations WHERE name='Бранч'), '2021-12-19', 'Cake&Coffee', 1.000, '130 грамм теста раскатать в круг ~20 см, сделать несколько дырок, выпечь в пиццепечи, смазать готовую лепешку соусом песто, нарезать на 4 части.', 'original', NULL, 0.135, 0, 0, 0, 0, 'технологическая карта составлена на основании акта проработки. По физико-химическим показателям соответствует требованиям ГОСТ РФ 50763-2007 "Кулинарная продукция, реализуемая населению". По микробиологическим показателям соответствует требованиям СанПиН 2.3.2 1078-01', 202);
INSERT INTO tech_cards (card_number, dish_name, organization_id, approval_date, application_area, portion_norm, technology, technology_source, serving_requirements, total_output_kg, proteins_per_100g, fats_per_100g, carbs_per_100g, calories_per_100g, note, source_page) VALUES ('03135', 'Блинный торт, крем маскарпоне, топинги', (SELECT id FROM organizations WHERE name='Бранч'), '2022-03-16', 'Cake&Coffee', 1.000, '(от ии) Блинное тесто (3-4 блина, готовые). Выложить первый блин, промазать Крем маскарпоне (30 г). Накрыть вторым блином, промазать кремом. Повторить. Верхний блин украсить кремом (розетка). Добавить Топинг (10 мл) по вкусу. Подавать при 8-12 °C.', 'ai', 'Мини твикс, марс, сникерс, милки', 0.2805, 0, 0, 0, 0, 'технологическая карта составлена на основании акта проработки. По физико-химическим показателям соответствует требованиям ГОСТ РФ 50763-2007 "Кулинарная продукция, реализуемая населению". По микробиологическим показателям соответствует требованиям СанПиН 2.3.2 1078-01', 203);
INSERT INTO tech_cards (card_number, dish_name, organization_id, approval_date, application_area, portion_norm, technology, technology_source, serving_requirements, total_output_kg, proteins_per_100g, fats_per_100g, carbs_per_100g, calories_per_100g, note, source_page) VALUES ('03134', 'Блинный торт, сливочный крем, топинги', (SELECT id FROM organizations WHERE name='Бранч'), '2022-03-16', 'Cake&Coffee', 1.000, '(от ии) Блинное тесто (3-4 блина, готовые). Выложить первый блин, промазать Крем сливочный (30 г). Накрыть вторым блином, промазать кремом. Повторить. Верхний блин украсить кремом (розетка). Добавить Топинг (10 мл) по вкусу. Подавать при 8-12 °C.', 'ai', 'Мини твикс, марс, сникерс, милки', 0.2805, 0, 0, 0, 0, 'технологическая карта составлена на основании акта проработки. По физико-химическим показателям соответствует требованиям ГОСТ РФ 50763-2007 "Кулинарная продукция, реализуемая населению". По микробиологическим показателям соответствует требованиям СанПиН 2.3.2 1078-01', 204);
INSERT INTO tech_cards (card_number, dish_name, organization_id, approval_date, application_area, portion_norm, technology, technology_source, serving_requirements, total_output_kg, proteins_per_100g, fats_per_100g, carbs_per_100g, calories_per_100g, note, source_page) VALUES ('03125', 'Большой, йогуртовый крем, топинги', (SELECT id FROM organizations WHERE name='Бранч'), '2022-03-16', 'Cake&Coffee', 1.000, '(от ии) Бисквит ванильный/соответствующий (1 корж, 1 см толщиной) пропитать Пропитка (Сироп Монин, 15 мл) с помощью кисти. На корж выложить Крем Йогуртовый (50-60 г) ровным слоем кондитерским мешком.  Сверху украсить Крем Йогуртовый (розочка из мешка). Добавить Топинг/Сироп Монин (10 мл). Подавать при 8-12 °C. Хранить собранный десерт не более 2 часов.', 'ai', 'Мини твикс, марс, сникерс, милки', 0.205, 0, 0, 0, 0, 'технологическая карта составлена на основании акта проработки. По физико-химическим показателям соответствует требованиям ГОСТ РФ 50763-2007 "Кулинарная продукция, реализуемая населению". По микробиологическим показателям соответствует требованиям СанПиН 2.3.2 1078-01', 205);
INSERT INTO tech_cards (card_number, dish_name, organization_id, approval_date, application_area, portion_norm, technology, technology_source, serving_requirements, total_output_kg, proteins_per_100g, fats_per_100g, carbs_per_100g, calories_per_100g, note, source_page) VALUES ('03131', 'Большой, крем маскарпоне, топинги', (SELECT id FROM organizations WHERE name='Бранч'), '2022-03-16', 'Cake&Coffee', 1.000, '(от ии) Бисквит ванильный/соответствующий (1 корж, 1 см толщиной) пропитать Пропитка (Сироп Монин, 15 мл) с помощью кисти. На корж выложить Крем маскарпоне (50-60 г) ровным слоем кондитерским мешком.  Сверху украсить Крем маскарпоне (розочка из мешка). Добавить Топинг/Сироп Монин (10 мл). Подавать при 8-12 °C. Хранить собранный десерт не более 2 часов.', 'ai', 'Мини твикс, марс, сникерс, милки', 0.205, 0, 0, 0, 0, 'технологическая карта составлена на основании акта проработки. По физико-химическим показателям соответствует требованиям ГОСТ РФ 50763-2007 "Кулинарная продукция, реализуемая населению". По микробиологическим показателям соответствует требованиям СанПиН 2.3.2 1078-01', 206);
INSERT INTO tech_cards (card_number, dish_name, organization_id, approval_date, application_area, portion_norm, technology, technology_source, serving_requirements, total_output_kg, proteins_per_100g, fats_per_100g, carbs_per_100g, calories_per_100g, note, source_page) VALUES ('03127', 'Большой, сливочный крем, топинги', (SELECT id FROM organizations WHERE name='Бранч'), '2022-03-16', 'Cake&Coffee', 1.000, '(от ии) Бисквит ванильный/соответствующий (1 корж, 1 см толщиной) пропитать Пропитка (Сироп Монин, 15 мл) с помощью кисти. На корж выложить Крем сливочный (50-60 г) ровным слоем кондитерским мешком.  Сверху украсить Крем сливочный (розочка из мешка). Добавить Топинг/Сироп Монин (10 мл). Подавать при 8-12 °C. Хранить собранный десерт не более 2 часов.', 'ai', 'Мини твикс, марс, сникерс, милки', 0.205, 0, 0, 0, 0, 'технологическая карта составлена на основании акта проработки. По физико-химическим показателям соответствует требованиям ГОСТ РФ 50763-2007 "Кулинарная продукция, реализуемая населению". По микробиологическим показателям соответствует требованиям СанПиН 2.3.2 1078-01', 207);
