INSERT INTO tech_cards (card_number, dish_name, organization_id, approval_date, application_area, portion_norm, technology, technology_source, serving_requirements, total_output_kg, proteins_per_100g, fats_per_100g, carbs_per_100g, calories_per_100g, note, source_page) VALUES ('03136', 'Блинный торт, крем маскарпоне, ягода', (SELECT id FROM organizations WHERE name='Бранч'), '2022-03-16', 'Cake&Coffee', 1.000, '(от ии) Блинное тесто (3-4 блина). Выкладывать блин, промазывать Крем маскарпоне (30 г). Между слоями — Клубника свежая и Голубика свежая (по 15 г). Верх украсить кремом и ягодами. Подавать при 8-12 °C.', 'ai', NULL, 0.2745, 0, 0, 0, 0, 'технологическая карта составлена на основании акта проработки. По физико-химическим показателям соответствует требованиям ГОСТ РФ 50763-2007 "Кулинарная продукция, реализуемая населению". По микробиологическим показателям соответствует требованиям СанПиН 2.3.2 1078-01', 213);
