INSERT INTO tech_cards (card_number, dish_name, organization_id, approval_date, application_area, portion_norm, technology, technology_source, serving_requirements, total_output_kg, proteins_per_100g, fats_per_100g, carbs_per_100g, calories_per_100g, note, source_page) VALUES ('03118', 'Маленький, сливочный крем, ягода', (SELECT id FROM organizations WHERE name='Бранч'), '2022-03-16', 'Cake&Coffee', 1.000, '(от ии) Бисквит ванильный (1 корж) пропитать Пропитка (Сироп Монин, 15 мл) кистью. Выложить крем (50-60 г) ровным слоем кондитерским мешком. Добавить Клубника свежая (3-4 шт., нарезанные) и Голубика свежая (10 г).  Сверху — розочка из крема. Подавать при 8-12 °C. Хранить собранный десерт не более 2 часов.', 'ai', NULL, 0.1487, 0, 0, 0, 0, 'технологическая карта составлена на основании акта проработки. По физико-химическим показателям соответствует требованиям ГОСТ РФ 50763-2007 "Кулинарная продукция, реализуемая населению". По микробиологическим показателям соответствует требованиям СанПиН 2.3.2 1078-01', 222);
INSERT INTO tech_cards (card_number, dish_name, organization_id, approval_date, application_area, portion_norm, technology, technology_source, serving_requirements, total_output_kg, proteins_per_100g, fats_per_100g, carbs_per_100g, calories_per_100g, note, source_page) VALUES ('03141', 'Карамельная глазурь на кусочек', (SELECT id FROM organizations WHERE name='Бранч'), '2022-03-17', 'Cake&Coffee', 1.000, '(от ии) Карамельная глазурь — подогреть до 50-55 °C на водяной бане до текучей консистенции. Полить десерт сверху. Дать застыть 3-5 минут. Подавать при 8-12 °C.', 'ai', NULL, 0.02, 0, 0, 0, 0, 'технологическая карта составлена на основании акта проработки. По физико-химическим показателям соответствует требованиям ГОСТ РФ 50763-2007 "Кулинарная продукция, реализуемая населению". По микробиологическим показателям соответствует требованиям СанПиН 2.3.2 1078-01', 223);
INSERT INTO tech_cards (card_number, dish_name, organization_id, approval_date, application_area, portion_norm, technology, technology_source, serving_requirements, total_output_kg, proteins_per_100g, fats_per_100g, carbs_per_100g, calories_per_100g, note, source_page) VALUES ('03139', 'Медовик кусочек', (SELECT id FROM organizations WHERE name='Бранч'), '2022-03-16', 'Cake&Coffee', 1.000, '(от ии) Медовые коржи (2 шт., готовые) пропитать Сгущенка вареная (10 мл) смешанной с водой (10 мл). Промазать Крем сметанный (40 г) между коржами. Обсыпать бока и верх крошкой из коржа. Украсить кремом. Подавать при 8-12 °C.', 'ai', NULL, 0.1873, 0, 0, 0, 0, 'технологическая карта составлена на основании акта проработки. По физико-химическим показателям соответствует требованиям ГОСТ РФ 50763-2007 "Кулинарная продукция, реализуемая населению". По микробиологическим показателям соответствует требованиям СанПиН 2.3.2 1078-01', 224);
INSERT INTO tech_cards (card_number, dish_name, organization_id, approval_date, application_area, portion_norm, technology, technology_source, serving_requirements, total_output_kg, proteins_per_100g, fats_per_100g, carbs_per_100g, calories_per_100g, note, source_page) VALUES ('03138', 'Наполеон кусочек', (SELECT id FROM organizations WHERE name='Бранч'), '2022-03-16', 'Cake&Coffee', 1.000, '(от ии) Корж на Наполеон (2 шт.) пропитать заварным кремом. Крем Заварной (50 г) выложить на первый корж, накрыть вторым. Сверху — крем (розетка). Посыпать Сливки 33% (взбитыми, 20 г) и Сахарная пудра. Подавать при 8-12 °C.', 'ai', NULL, 0.2162, 0, 0, 0, 0, 'технологическая карта составлена на основании акта проработки. По физико-химическим показателям соответствует требованиям ГОСТ РФ 50763-2007 "Кулинарная продукция, реализуемая населению". По микробиологическим показателям соответствует требованиям СанПиН 2.3.2 1078-01', 225);
INSERT INTO tech_cards (card_number, dish_name, organization_id, approval_date, application_area, portion_norm, technology, technology_source, serving_requirements, total_output_kg, proteins_per_100g, fats_per_100g, carbs_per_100g, calories_per_100g, note, source_page) VALUES ('03140', 'Шоколадная глазурь на кусочек', (SELECT id FROM organizations WHERE name='Бранч'), '2022-03-17', 'Cake&Coffee', 1.000, '(от ии) Глазурь Шоколадная — подогреть на водяной бане до 40-45 °C до жидкой консистенции. Полить готовый десерт (корж/пирог) сверху, равномерно распределяя. Дать застыть 5-10 минут при комнатной температуре. Подавать при 8-12 °C.', 'ai', NULL, 0.02, 0, 0, 0, 0, 'технологическая карта составлена на основании акта проработки. По физико-химическим показателям соответствует требованиям ГОСТ РФ 50763-2007 "Кулинарная продукция, реализуемая населению". По микробиологическим показателям соответствует требованиям СанПиН 2.3.2 1078-01', 226);
INSERT INTO tech_cards (card_number, dish_name, organization_id, approval_date, application_area, portion_norm, technology, technology_source, serving_requirements, total_output_kg, proteins_per_100g, fats_per_100g, carbs_per_100g, calories_per_100g, note, source_page) VALUES ('01841', 'Angel cookies', (SELECT id FROM organizations WHERE name='Бранч'), '2022-03-20', 'Cake&Coffee', 1.000, '(от ии) Тесто на angel (готовое печенье, 60 г) — при подаче выложить на тарелку. Сверху — Сливочный крем (20 г) из мешка. Полить Глазурь Шоколадная (10 г). Украсить Голубика свежая (3-5 шт.). Подавать при 18-22 °C.', 'ai', NULL, 0.243, 0, 0, 0, 0, 'технологическая карта составлена на основании акта проработки. По физико-химическим показателям соответствует требованиям ГОСТ РФ 50763-2007 "Кулинарная продукция, реализуемая населению". По микробиологическим показателям соответствует требованиям СанПиН 2.3.2 1078-01', 227);
INSERT INTO tech_cards (card_number, dish_name, organization_id, approval_date, application_area, portion_norm, technology, technology_source, serving_requirements, total_output_kg, proteins_per_100g, fats_per_100g, carbs_per_100g, calories_per_100g, note, source_page) VALUES ('03437', 'cake to go', (SELECT id FROM organizations WHERE name='Бранч'), '2023-05-01', 'Cake&Coffee', 1.000, 'Бисквит вырезать по диаметру стакана или нарезать кубиком. сироп смешать с водой. Собрать торт в стакане: бисквит, пропитка,', 'original', '0,000 Покрыть шоколадной глазурью, украсить ягодой.', 0.25, 0, 0, 0, 0, 'технологическая карта составлена на основании акта проработки. По физико-химическим показателям соответствует требованиям ГОСТ РФ 50763-2007 "Кулинарная продукция, реализуемая населению". По микробиологическим показателям соответствует требованиям СанПиН 2.3.2 1078-01', 228);
INSERT INTO tech_cards (card_number, dish_name, organization_id, approval_date, application_area, portion_norm, technology, technology_source, serving_requirements, total_output_kg, proteins_per_100g, fats_per_100g, carbs_per_100g, calories_per_100g, note, source_page) VALUES ('00455', 'Брауни', (SELECT id FROM organizations WHERE name='Бранч'), '2022-03-23', 'Cake&Coffee', 1.000, '(от ии) Брауни (полуфабрикат, 80 г) — при подаче комнатной температуры или разогреть в микроволновке 15-20 секунд (до 40-45 °C внутри). Выложить на тарелку, украсить Сливочный крем (10 г) из мешка.', 'ai', NULL, 0.166, 0, 0, 0, 0, 'технологическая карта составлена на основании акта проработки. По физико-химическим показателям соответствует требованиям ГОСТ РФ 50763-2007 "Кулинарная продукция, реализуемая населению". По микробиологическим показателям соответствует требованиям СанПиН 2.3.2 1078-01', 229);
INSERT INTO tech_cards (card_number, dish_name, organization_id, approval_date, application_area, portion_norm, technology, technology_source, serving_requirements, total_output_kg, proteins_per_100g, fats_per_100g, carbs_per_100g, calories_per_100g, note, source_page) VALUES ('00462', 'Вуппи Пай', (SELECT id FROM organizations WHERE name='Бранч'), '2022-03-19', 'Cake&Coffee', 1.000, '(от ии) Вуппи Пай: Тесто вупи (2 готовых половинки, похожих на макарон) — на нижнюю половину выложить Крем вупи (20 г). Накрыть верхней половиной. Украсить Голубика свежая (2-3 шт.). Подавать при 18-22 °C.', 'ai', NULL, 0.131, 0, 0, 0, 0, 'технологическая карта составлена на основании акта проработки. По физико-химическим показателям соответствует требованиям ГОСТ РФ 50763-2007 "Кулинарная продукция, реализуемая населению". По микробиологическим показателям соответствует требованиям СанПиН 2.3.2 1078-01', 230);
INSERT INTO tech_cards (card_number, dish_name, organization_id, approval_date, application_area, portion_norm, technology, technology_source, serving_requirements, total_output_kg, proteins_per_100g, fats_per_100g, carbs_per_100g, calories_per_100g, note, source_page) VALUES ('00470', 'Десерт Павлова', (SELECT id FROM organizations WHERE name='Бранч'), '2022-03-23', 'Cake&Coffee', 1.000, '(от ии) Безе (готовое, 1 основа d=15 см) — выложить на тарелку. Крем на Павлова (50 г) — сливки с маскарпоне — выложить на безе из кондитерского мешка. Украсить Голубика свежая (20 г) и Клубника свежая (30 г, разрезанная). Подавать немедленно (безе размокает от крема). Температура подачи 8-12 °C.', 'ai', NULL, 0.077, 0, 0, 0, 0, 'технологическая карта составлена на основании акта проработки. По физико-химическим показателям соответствует требованиям ГОСТ РФ 50763-2007 "Кулинарная продукция, реализуемая населению". По микробиологическим показателям соответствует требованиям СанПиН 2.3.2 1078-01', 231);
INSERT INTO tech_cards (card_number, dish_name, organization_id, approval_date, application_area, portion_norm, technology, technology_source, serving_requirements, total_output_kg, proteins_per_100g, fats_per_100g, carbs_per_100g, calories_per_100g, note, source_page) VALUES ('00459', 'Капкейк', (SELECT id FROM organizations WHERE name='Бранч'), '2022-09-01', 'Cake&Coffee', 1.000, '(от ии) Капкейк: Тесто на капкейки (готовый, 60 г) — если охлажденный, разогреть 15-20 секунд при 600 Вт в микроволновке. Сверху выложить Сливочный крем (30 г) из кондитерского мешка (розетка). Украсить по сезону. Подавать при 18-22 °C.', 'ai', NULL, 0.12, 0, 0, 0, 0, 'технологическая карта составлена на основании акта проработки. По физико-химическим показателям соответствует требованиям ГОСТ РФ 50763-2007 "Кулинарная продукция, реализуемая населению". По микробиологическим показателям соответствует требованиям СанПиН 2.3.2 1078-01', 232);
INSERT INTO tech_cards (card_number, dish_name, organization_id, approval_date, application_area, portion_norm, technology, technology_source, serving_requirements, total_output_kg, proteins_per_100g, fats_per_100g, carbs_per_100g, calories_per_100g, note, source_page) VALUES ('03197', 'Карамельный Эклер', (SELECT id FROM organizations WHERE name='Бранч'), '2022-08-11', 'Cake&Coffee', 1.000, '(от ии) Эклер (заварное тесто, готовый) — разрезать вдоль. На нижнюю половину выложить крем соленой карамели (30 г) из мешка. Накрыть верхней половиной. Полить карамельной глазурью. Подавать при 8-12 °C.', 'ai', 'Сливочный крем с И РЕАЛИЗАЦИИ на 12шт. Карамельный глассаж на 50шт.', 0.117, 0, 0, 0, 0, 'технологическая карта составлена на основании акта проработки. По физико-химическим показателям соответствует требованиям ГОСТ РФ 50763-2007 "Кулинарная продукция, реализуемая населению". По микробиологическим показателям соответствует требованиям СанПиН 2.3.2 1078-01', 233);
INSERT INTO tech_cards (card_number, dish_name, organization_id, approval_date, application_area, portion_norm, technology, technology_source, serving_requirements, total_output_kg, proteins_per_100g, fats_per_100g, carbs_per_100g, calories_per_100g, note, source_page) VALUES ('02170', 'Меренговый пирог', (SELECT id FROM organizations WHERE name='Бранч'), '2022-03-23', 'Cake&Coffee', 8.000, '(от ии) Яйцо куриное (3 шт., белки) — взбить миксером до мягких пиков. Постепенно добавить Сахар-песок (150 г) по ложке, взбивая до жестких глянцевых пиков. Добавить Крахмал кукурузный (5 г) и Лимонный сок (2 мл). Аккуратно перемешать лопаткой. Выложить на пергамент в форме круга d=20 см с углублением в центре. Сушить в духовке при 100 °C 1,5-2 часа до хруста снаружи и мягкости внутри. Остудить в выключенной духовке с приоткрытой дверцей. Сливки 33% (150 г) взбить с Сахарная пудра (15 г) и Маскарпоне (50 г). На безе выложить крем, украсить Клубника свежая и Голубика свежая. Подавать немедленно при 8-12 °C.', 'ai', 'Суммарный выход продукта (1200)', 1.205, 0, 0, 0, 0, 'технологическая карта составлена на основании акта проработки. По физико-химическим показателям соответствует требованиям ГОСТ РФ 50763-2007 "Кулинарная продукция, реализуемая населению". По микробиологическим показателям соответствует требованиям СанПиН 2.3.2 1078-01', 234);
INSERT INTO tech_cards (card_number, dish_name, organization_id, approval_date, application_area, portion_norm, technology, technology_source, serving_requirements, total_output_kg, proteins_per_100g, fats_per_100g, carbs_per_100g, calories_per_100g, note, source_page) VALUES ('01994', 'Овсяное печенье', (SELECT id FROM organizations WHERE name='Бранч'), '2018-08-15', 'Cake&Coffee', 1.000, '(от ии) Овсяное печенье (готовое) — выложить 2-3 шт. на тарелку. Подавать при комнатной температуре 18-22 °C.', 'ai', NULL, 0.05, 0, 0, 0, 0, 'технологическая карта составлена на основании акта проработки. По физико-химическим показателям соответствует требованиям ГОСТ РФ 50763-2007 "Кулинарная продукция, реализуемая населению". По микробиологическим показателям соответствует требованиям СанПиН 2.3.2 1078-01', 235);
INSERT INTO tech_cards (card_number, dish_name, organization_id, approval_date, application_area, portion_norm, technology, technology_source, serving_requirements, total_output_kg, proteins_per_100g, fats_per_100g, carbs_per_100g, calories_per_100g, note, source_page) VALUES ('03353', 'Пари-Брест', (SELECT id FROM organizations WHERE name='Бранч'), '2023-01-11', 'Cake&Coffee', 6.000, '(от ии) Заварное тесто: Воду (120 мл) и Масло сливочное (50 г) довести до кипения в сотейнике при 180 °C. Снять с огня, всыпать Мука хлебопекарная (80 г) разом. Перемешать деревянной ложкой до образования кома (ball stage). Остудить до 60 °C. По одному вводить Яйцо куриное (2-3 шт.), каждый раз тщательно вымешивая до однородности. Тесто должно быть глянцевым и тянуться лентой при поднятии ложкой. Отсадить на пергамент 2 кольца (d=18 и d=14 см) или одно большое (d=20 см). Выпекать в духовке при 200 °C первые 15 минут (не открывать дверцу!). Снизить до 170 °C, выпекать еще 20-25 минут до золотистого цвета и сухого внутри. Остудить на решетке. Крем: Желток (1 шт.) взбить с Сахар-песок (40 г). Молоко (50 мл) довести до кипения, влить тонкой струей в желток, постоянно помешивая. Вернуть на огонь, варить до загустения (82-85 °C), помешивая. Снять, добавить Масло сливочное (30 г) и Миндаль (20 г, обжаренный и измельченный). Остудить крем. Заполнить заварное кольцо кремом из кондитерского мешка. Сверху посыпать Мука миндальная/миндальная стружка и Сахарная пудра. Подавать при 8-12 °C.', 'ai', 'Глазурь Карамельная', 1.031, 0, 0, 0, 0, 'технологическая карта составлена на основании акта проработки. По физико-химическим показателям соответствует требованиям ГОСТ РФ 50763-2007 "Кулинарная продукция, реализуемая населению". По микробиологическим показателям соответствует требованиям СанПиН 2.3.2 1078-01', 236);
INSERT INTO tech_cards (card_number, dish_name, organization_id, approval_date, application_area, portion_norm, technology, technology_source, serving_requirements, total_output_kg, proteins_per_100g, fats_per_100g, carbs_per_100g, calories_per_100g, note, source_page) VALUES ('03259', 'Печенье брауни с маршмеллоу', (SELECT id FROM organizations WHERE name='Бранч'), '2022-11-01', 'Cake&Coffee', 11.000, '(от ии) Масло сливочное (80 г) растопить. Шоколад темный (100 г) — расплавить. Смешать. Добавить Сахар-песок (100 г), Яйцо куриное (1 шт.), Мука хлебопекарная (100 г), Разрыхлитель (3 г). Вымесить тесто. Выложить в форму (20х20 см) с пергаментом. Выпекать при 175 °C 15 минут. Достать, разложить Маршмелоу (10-12 шт.) сверху. Вернуть в духовку на 3-5 минут до подплавления маршмеллоу. Остудить, нарезать. Подавать при 18-22 °C.', 'ai', 'Маршмеллоу И РЕАЛИЗАЦИИ самодельные', 0.99, 0, 0, 0, 0, 'технологическая карта составлена на основании акта проработки. По физико-химическим показателям соответствует требованиям ГОСТ РФ 50763-2007 "Кулинарная продукция, реализуемая населению". По микробиологическим показателям соответствует требованиям СанПиН 2.3.2 1078-01', 237);
INSERT INTO tech_cards (card_number, dish_name, organization_id, approval_date, application_area, portion_norm, technology, technology_source, serving_requirements, total_output_kg, proteins_per_100g, fats_per_100g, carbs_per_100g, calories_per_100g, note, source_page) VALUES ('02496', 'Трайфл', (SELECT id FROM organizations WHERE name='Бранч'), '2022-04-21', 'Cake&Coffee', 14.000, '(от ии) Основа: Бисквит ванильный (или приготовить: Мука хлебопекарная 60 г, Масло подсолнечное 40 мл, Молоко 3,2% 40 мл, Яйцо 1 шт., Сахар 50 г, Разрыхлитель 3 г, Сода 1 г — перемешать, выпечь при 180 °C 25-30 мин). Бисквит нарезать кубиком 1,5 см. Желе (готовое, 50 г) — нарезать кубиком. Сливки 33% (100 г) взбить с Сахарная пудра (15 г) до устойчивых пиков. В стакан слоями: бисквит → желе → сливки → бисквит → желе → сливки. Верхний слой — сливки. Украсить Шоколадная стружка/ягодами. Охладить 1-2 часа. Подавать при 8-12 °C.', 'ai', 'Какао Красный октябрь Шоколад мол. в галетах Шоколад тем. в галетах', 2.2135, 0, 0, 0, 0, 'технологическая карта составлена на основании акта проработки. По физико-химическим показателям соответствует требованиям ГОСТ РФ 50763-2007 "Кулинарная продукция, реализуемая населению". По микробиологическим показателям соответствует требованиям СанПиН 2.3.2 1078-01', 238);
INSERT INTO tech_cards (card_number, dish_name, organization_id, approval_date, application_area, portion_norm, technology, technology_source, serving_requirements, total_output_kg, proteins_per_100g, fats_per_100g, carbs_per_100g, calories_per_100g, note, source_page) VALUES ('03349', 'Три шоколада', (SELECT id FROM organizations WHERE name='Бранч'), '2023-01-11', 'Cake&Coffee', 6.000, 'Отвешать белый, молочный и темный Шоколад мол. в шоколаду добавить молоко, растопить весь Шоколад белый в 50 градусов, сливки взбить до плотной пены, разделить на три части. Добавить силиконовой лопаткой до однородности. добавить в него 4г замоченного желатина и получившиеся муссы по одноразовым', 'original', 'Плотные муссы, однородные, держат слои.', 1.02, 6, 36, 19, 421, 'технологическая карта составлена на основании акта проработки. По физико-химическим показателям соответствует требованиям ГОСТ РФ 50763-2007 "Кулинарная продукция, реализуемая населению". По микробиологическим показателям соответствует требованиям СанПиН 2.3.2 1078-01', 239);
INSERT INTO tech_cards (card_number, dish_name, organization_id, approval_date, application_area, portion_norm, technology, technology_source, serving_requirements, total_output_kg, proteins_per_100g, fats_per_100g, carbs_per_100g, calories_per_100g, note, source_page) VALUES ('02025', 'Трюфель', (SELECT id FROM organizations WHERE name='Бранч'), '2018-11-20', 'Cake&Coffee', 1.000, '(от ии) Трюфель п/ф (готовый, 1-2 шт., 30 г) — достать из холодильника за 5 минут до подачи. Шоколадная пыль/какао — обвалять перед подачей. Выложить на тарелку на пергаментную подложку. Подавать при 18-22 °C.', 'ai', NULL, 0.049, 0, 0, 0, 0, 'технологическая карта составлена на основании акта проработки. По физико-химическим показателям соответствует требованиям ГОСТ РФ 50763-2007 "Кулинарная продукция, реализуемая населению". По микробиологическим показателям соответствует требованиям СанПиН 2.3.2 1078-01', 240);
INSERT INTO tech_cards (card_number, dish_name, organization_id, approval_date, application_area, portion_norm, technology, technology_source, serving_requirements, total_output_kg, proteins_per_100g, fats_per_100g, carbs_per_100g, calories_per_100g, note, source_page) VALUES ('02043', 'Фисташковый пирог', (SELECT id FROM organizations WHERE name='Бранч'), '2022-03-23', 'Cake&Coffee', 5.000, '(от ии) Основа: Фисташки (40 г) и Миндаль (30 г) измельчить в блендере в муку. Смешать с Мука хлебопекарная (40 г). Масло сливочное (80 г) взбить с Сахар-песок (60 г) до пышной массы (3-5 минут миксером на средней скорости). Добавить Яйцо куриное (2 шт.) по одному, каждый раз перемешивая. Ввести сухую смесь (ореховая мука + пшеничная + Разрыхлитель 3 г). Перемешать лопаткой до однородности. Выложить в форму (d=18 см) с пергаментом. Выпекать при 170-180 °C 25-30 минут до сухой зубочистки. Остудить в форме 10 минут, затем на решетке. Глазурь: Шоколад белый (50 г) растопить на водяной бане до 40-45 °C. Полить остывший пирог. Украсить целыми фисташками. Подавать при 18-22 °C.', 'ai', 'Глазурь Карамельная', 0.941, 0, 0, 0, 0, 'технологическая карта составлена на основании акта проработки. По физико-химическим показателям соответствует требованиям ГОСТ РФ 50763-2007 "Кулинарная продукция, реализуемая населению". По микробиологическим показателям соответствует требованиям СанПиН 2.3.2 1078-01', 241);
INSERT INTO tech_cards (card_number, dish_name, organization_id, approval_date, application_area, portion_norm, technology, technology_source, serving_requirements, total_output_kg, proteins_per_100g, fats_per_100g, carbs_per_100g, calories_per_100g, note, source_page) VALUES ('03512', 'Чизкейк в стакане', (SELECT id FROM organizations WHERE name='Бранч'), '2023-04-30', 'Cake&Coffee', 1.000, 'Печенье измельчить в крошку, масло растопить и добавить в печенье, вымешать до однородности. На дно стакана выложить варенье, закрыть сверху сливочным кремом, украсить ягодой.', 'original', NULL, 0.165, 0, 0, 0, 0, 'технологическая карта составлена на основании акта проработки. По физико-химическим показателям соответствует требованиям ГОСТ РФ 50763-2007 "Кулинарная продукция, реализуемая населению". По микробиологическим показателям соответствует требованиям СанПиН 2.3.2 1078-01', 242);
INSERT INTO tech_cards (card_number, dish_name, organization_id, approval_date, application_area, portion_norm, technology, technology_source, serving_requirements, total_output_kg, proteins_per_100g, fats_per_100g, carbs_per_100g, calories_per_100g, note, source_page) VALUES ('00464', 'Чизкейк мусс', (SELECT id FROM organizations WHERE name='Бранч'), '2023-05-01', 'Cake&Coffee', 1.000, '(от ии) Чизкейк мусс: Основа на чизкейк (1 шт., готовая основа из печенья). Заполнить Крем сливочный (60 г) из кондитерского мешка. Сверху — Топинг (15 мл). Украсить Клубника свежая (2 шт.). Подавать при 8-12 °C.', 'ai', NULL, 0.157, 0, 0, 0, 0, 'технологическая карта составлена на основании акта проработки. По физико-химическим показателям соответствует требованиям ГОСТ РФ 50763-2007 "Кулинарная продукция, реализуемая населению". По микробиологическим показателям соответствует требованиям СанПиН 2.3.2 1078-01', 243);
INSERT INTO tech_cards (card_number, dish_name, organization_id, approval_date, application_area, portion_norm, technology, technology_source, serving_requirements, total_output_kg, proteins_per_100g, fats_per_100g, carbs_per_100g, calories_per_100g, note, source_page) VALUES ('00636', 'Шокоболы', (SELECT id FROM organizations WHERE name='Бранч'), '2023-05-01', 'Cake&Coffee', 1.000, 'Смесь на шокоболы разделить по 80гр, растопить до рабочей температуры,', 'original', 'сделать узор на шокоболе с помощью', 0.09, 0, 0, 0, 0, 'технологическая карта составлена на основании акта проработки. По физико-химическим показателям соответствует требованиям ГОСТ РФ 50763-2007 "Кулинарная продукция, реализуемая населению". По микробиологическим показателям соответствует требованиям СанПиН 2.3.2 1078-01', 244);
INSERT INTO tech_cards (card_number, dish_name, organization_id, approval_date, application_area, portion_norm, technology, technology_source, serving_requirements, total_output_kg, proteins_per_100g, fats_per_100g, carbs_per_100g, calories_per_100g, note, source_page) VALUES ('00457', 'Шоколадный кукис', (SELECT id FROM organizations WHERE name='Бранч'), '2022-03-19', 'Cake&Coffee', 1.000, '(от ии) Шоколадные кукисы (2 шт.) выложить на тарелку. Сверху — M&M конфетки (5-8 шт.), слегка вдавив в тесто перед выпечкой или украсив сверху. Подавать при комнатной температуре.', 'ai', NULL, 0.085, 0, 0, 0, 0, 'технологическая карта составлена на основании акта проработки. По физико-химическим показателям соответствует требованиям ГОСТ РФ 50763-2007 "Кулинарная продукция, реализуемая населению". По микробиологическим показателям соответствует требованиям СанПиН 2.3.2 1078-01', 245);
INSERT INTO tech_cards (card_number, dish_name, organization_id, approval_date, application_area, portion_norm, technology, technology_source, serving_requirements, total_output_kg, proteins_per_100g, fats_per_100g, carbs_per_100g, calories_per_100g, note, source_page) VALUES ('00461', 'Эклер', (SELECT id FROM organizations WHERE name='Бранч'), '2022-03-19', 'Cake&Coffee', 1.000, '(от ии) Эклер: Заварное (1 шт., готовый, длинный, 12-15 см) — разрезать вдоль пополам. На нижнюю половину выложить Крем сливочный (30 г) из мешка. Накрыть верхней половиной. Полить Глазурь Шоколадная (15 г), растопленной на водяной бане до 40-45 °C. Украсить Голубика свежая (2-3 шт.). Подавать при 8-12 °C.', 'ai', NULL, 0.205, 0, 0, 0, 0, 'технологическая карта составлена на основании акта проработки. По физико-химическим показателям соответствует требованиям ГОСТ РФ 50763-2007 "Кулинарная продукция, реализуемая населению". По микробиологическим показателям соответствует требованиям СанПиН 2.3.2 1078-01', 246);
INSERT INTO tech_cards (card_number, dish_name, organization_id, approval_date, application_area, portion_norm, technology, technology_source, serving_requirements, total_output_kg, proteins_per_100g, fats_per_100g, carbs_per_100g, calories_per_100g, note, source_page) VALUES ('03377', 'Эклер сливочный', (SELECT id FROM organizations WHERE name='Бранч'), '2023-01-23', 'Cake&Coffee', 6.000, '(от ии) Заварное тесто: Воду (100 мл) и Масло сливочное (50 г) довести до кипения. Всыпать Мука хлебопекарная (80 г), вымешать до кома. Остудить до 60 °C. По одному ввести Яйцо куриное (2-3 шт.), вымешивая до глянцевой массы. Отсадить полоски (12-15 см) на пергамент через круглую насадку. Выпекать при 200 °C 15 мин, затем 170 °C 15-20 мин до золотистого цвета. Остудить. Крем: Сливки 33% (150 г) взбить с Сахарная пудра (20 г) до устойчивых пиков. Эклеры разрезать вдоль. На нижнюю половину — крем из мешка. Накрыть верхней. Верх полить Шоколадная глазурь (растопленной при 40-45 °C). Подавать при 8-12 °C.', 'ai', NULL, 0.8394, 0, 0, 0, 0, 'технологическая карта составлена на основании акта проработки. По физико-химическим показателям соответствует требованиям ГОСТ РФ 50763-2007 "Кулинарная продукция, реализуемая населению". По микробиологическим показателям соответствует требованиям СанПиН 2.3.2 1078-01', 247);
INSERT INTO tech_cards (card_number, dish_name, organization_id, approval_date, application_area, portion_norm, technology, technology_source, serving_requirements, total_output_kg, proteins_per_100g, fats_per_100g, carbs_per_100g, calories_per_100g, note, source_page) VALUES ('00466', 'Яблочный штрудель', (SELECT id FROM organizations WHERE name='Бранч'), '2019-10-31', 'Cake&Coffee', 1.000, '(от ии) Яблочный штрудель: Яблочный штрудель (готовый, 120 г) разогреть в духовке при 180 °C 8-10 минут до хрустящего теста. Выложить на тарелку. Сверху — Заварной крем (20 г, холодный). Посыпать Сахарная пудра. Украсить Мята. Температура подачи 50-60 °C.', 'ai', NULL, 0.157, 0, 0, 0, 0, 'технологическая карта составлена на основании акта проработки. По физико-химическим показателям соответствует требованиям ГОСТ РФ 50763-2007 "Кулинарная продукция, реализуемая населению". По микробиологическим показателям соответствует требованиям СанПиН 2.3.2 1078-01', 248);
INSERT INTO tech_cards (card_number, dish_name, organization_id, approval_date, application_area, portion_norm, technology, technology_source, serving_requirements, total_output_kg, proteins_per_100g, fats_per_100g, carbs_per_100g, calories_per_100g, note, source_page) VALUES ('00456', 'Безе', (SELECT id FROM organizations WHERE name='Бранч'), '2016-09-18', 'Cake&Coffee', 1.000, '(от ии) Безе (2-3 шт., готовые) — выложить на тарелку. Хранить в герметичной таре при комнатной температуре. Подавать при 18-22 °C. Не хранить при влажности — размокают.', 'ai', NULL, 0.017, 0, 0, 0, 0, 'технологическая карта составлена на основании акта проработки. По физико-химическим показателям соответствует требованиям ГОСТ РФ 50763-2007 "Кулинарная продукция, реализуемая населению". По микробиологическим показателям соответствует требованиям СанПиН 2.3.2 1078-01', 249);
INSERT INTO tech_cards (card_number, dish_name, organization_id, approval_date, application_area, portion_norm, technology, technology_source, serving_requirements, total_output_kg, proteins_per_100g, fats_per_100g, carbs_per_100g, calories_per_100g, note, source_page) VALUES ('00674', 'Белые кукисы', (SELECT id FROM organizations WHERE name='Бранч'), '2016-10-21', 'Cake&Coffee', 1.000, '(от ии) Белые кукисы (2-3 шт., готовые) — выложить на тарелку. Подавать при комнатной температуре (18-22 °C).', 'ai', NULL, 0.041, 0, 0, 0, 0, 'технологическая карта составлена на основании акта проработки. По физико-химическим показателям соответствует требованиям ГОСТ РФ 50763-2007 "Кулинарная продукция, реализуемая населению". По микробиологическим показателям соответствует требованиям СанПиН 2.3.2 1078-01', 250);
INSERT INTO tech_cards (card_number, dish_name, organization_id, approval_date, application_area, portion_norm, technology, technology_source, serving_requirements, total_output_kg, proteins_per_100g, fats_per_100g, carbs_per_100g, calories_per_100g, note, source_page) VALUES ('03193', 'Брауни с арахисовым кремом', (SELECT id FROM organizations WHERE name='Бранч'), '2022-08-10', 'Cake&Coffee', 8.000, '(от ии) Масло сливочное (80 г) растопить на водяной бане (45-50 °C). Добавить Шоколад темный (100 г), помешивать до растворения. Снять с огня. Добавить Сахар-песок (80 г), перемешать. Ввести Яйцо куриное (2 шт.) по одному, перемешивая. Мука хлебопекарная (60 г), Соль пищевая (щепотка) — просеять, добавить. Перемешать лопаткой. Выложить в форму (20х20 см) с пергаментом. Выпекать при 170-180 °C 20-25 минут (центр должен быть слегка влажным — недопеченный). Остудить. Нарезать на порции (4х4 см). Арахисовый крем: Арахисовая паста (80 г) смешать с Сливки 33% (50 г) и Сахарная пудра (20 г). Выложить крем на брауни из мешка. Посыпать Арахис (рубленый, 10 г). Подавать при 18-22 °C.', 'ai', 'Какао Красный октябрь Шоколад мол. в галетах', 1.109, 0, 0, 0, 0, 'технологическая карта составлена на основании акта проработки. По физико-химическим показателям соответствует требованиям ГОСТ РФ 50763-2007 "Кулинарная продукция, реализуемая населению". По микробиологическим показателям соответствует требованиям СанПиН 2.3.2 1078-01', 251);
INSERT INTO tech_cards (card_number, dish_name, organization_id, approval_date, application_area, portion_norm, technology, technology_source, serving_requirements, total_output_kg, proteins_per_100g, fats_per_100g, carbs_per_100g, calories_per_100g, note, source_page) VALUES ('02295', 'Десерт из авокадо', (SELECT id FROM organizations WHERE name='Бранч'), '2019-06-28', 'Cake&Coffee', 2.000, '(от ии) Авокадо (1 шт., спелое) разрезать, удалить косточку. Мякоть выложить в блендер. Добавить Мед (15 г), Сок лайма (10 мл), Сливки 10% (30 мл). Взбить до однородной кремовой массы. Разлить в стеклянный стакан/креманку. Сверху — взбитые сливки (10 мл) и кокосовая стружка. Подавать при 5-10 °C, сразу после приготовления (авокадо темнеет).', 'ai', NULL, 0.2203, 0, 0, 0, 0, 'технологическая карта составлена на основании акта проработки. По физико-химическим показателям соответствует требованиям ГОСТ РФ 50763-2007 "Кулинарная продукция, реализуемая населению". По микробиологическим показателям соответствует требованиям СанПиН 2.3.2 1078-01', 252);
INSERT INTO tech_cards (card_number, dish_name, organization_id, approval_date, application_area, portion_norm, technology, technology_source, serving_requirements, total_output_kg, proteins_per_100g, fats_per_100g, carbs_per_100g, calories_per_100g, note, source_page) VALUES ('01855', 'Десерт стаканчике', (SELECT id FROM organizations WHERE name='Бранч'), '2020-12-23', 'Cake&Coffee', 1.000, '(от ии) На дно стакана выложить кусочки Шоколадный бисквит (30 г). Полить Сироп Монин (10 мл). Сверху — Сливки 33% (взбитые с Сахарная пудра, 50 г) из мешка. Украсить Клубника свежая (2-3 шт.). Посыпать Сахарная пудра. Подавать при 8-12 °C.', 'ai', NULL, 0.0784, 0, 0, 0, 0, 'технологическая карта составлена на основании акта проработки. По физико-химическим показателям соответствует требованиям ГОСТ РФ 50763-2007 "Кулинарная продукция, реализуемая населению". По микробиологическим показателям соответствует требованиям СанПиН 2.3.2 1078-01', 253);
INSERT INTO tech_cards (card_number, dish_name, organization_id, approval_date, application_area, portion_norm, technology, technology_source, serving_requirements, total_output_kg, proteins_per_100g, fats_per_100g, carbs_per_100g, calories_per_100g, note, source_page) VALUES ('00675', 'Заказной торт (предоплата)', (SELECT id FROM organizations WHERE name='Бранч'), '2016-10-21', 'Cake&Coffee', 1.000, '(от ии) Заказной торт — готовится по индивидуальному заказу. Технология согласно утвержденной технико-технологической карте заказа.', 'ai', NULL, 0.0, 0, 0, 0, 0, 'технологическая карта составлена на основании акта проработки. По физико-химическим показателям соответствует требованиям ГОСТ РФ 50763-2007 "Кулинарная продукция, реализуемая населению". По микробиологическим показателям соответствует требованиям СанПиН 2.3.2 1078-01', 254);
INSERT INTO tech_cards (card_number, dish_name, organization_id, approval_date, application_area, portion_norm, technology, technology_source, serving_requirements, total_output_kg, proteins_per_100g, fats_per_100g, carbs_per_100g, calories_per_100g, note, source_page) VALUES ('02134', 'Зефир', (SELECT id FROM organizations WHERE name='Бранч'), '2019-02-19', 'Cake&Coffee', 16.000, '(от ии) Агар-агар (5 г) замочить в воде (30 мл) на 30-60 минут. Яблоки (300 г) запечь в духовке при 180 °C 30-40 минут до мягкости. Протереть через сито (пюре). Агар-агар с водой довести до кипения, добавить Сахар-песок (200 г). Варить сироп до 110 °C (проба на мягкий шарик). Яичный белок (1 шт.) взбить миксером до мягких пиков. Влить горячий сироп тонкой струей, продолжая взбивать. Взбивать до устойчивых пиков и охлаждения массы до 40-45 °C. Добавить яблочное пюре, Сироп глюкозы (20 г). Взбивать до однородности. Отсадить половинки зефира на пергамент через насадку. Сушить при комнатной температуре 24 часа (в сухом месте). Склеить половинки. Посыпать Сахарная пудра/сахаром. Хранить в герметичной таре. Подавать при 18-22 °C.', 'ai', NULL, 2.833, 0, 0, 0, 0, 'технологическая карта составлена на основании акта проработки. По физико-химическим показателям соответствует требованиям ГОСТ РФ 50763-2007 "Кулинарная продукция, реализуемая населению". По микробиологическим показателям соответствует требованиям СанПиН 2.3.2 1078-01', 255);
INSERT INTO tech_cards (card_number, dish_name, organization_id, approval_date, application_area, portion_norm, technology, technology_source, serving_requirements, total_output_kg, proteins_per_100g, fats_per_100g, carbs_per_100g, calories_per_100g, note, source_page) VALUES ('00492', 'Имбирное печенье', (SELECT id FROM organizations WHERE name='Бранч'), '2016-09-18', 'Cake&Coffee', 1.000, '(от ии) Имбирное печенье (готовое) — выложить на тарелку (2-3 шт.). Подавать при комнатной температуре 18-22 °C.', 'ai', NULL, 0.018, 0, 0, 0, 0, 'технологическая карта составлена на основании акта проработки. По физико-химическим показателям соответствует требованиям ГОСТ РФ 50763-2007 "Кулинарная продукция, реализуемая населению". По микробиологическим показателям соответствует требованиям СанПиН 2.3.2 1078-01', 256);
INSERT INTO tech_cards (card_number, dish_name, organization_id, approval_date, application_area, portion_norm, technology, technology_source, serving_requirements, total_output_kg, proteins_per_100g, fats_per_100g, carbs_per_100g, calories_per_100g, note, source_page) VALUES ('01130', 'Имбирное печенье с шоколадом', (SELECT id FROM organizations WHERE name='Бранч'), '2017-02-10', 'Cake&Coffee', 1.000, '(от ии) Имбирное печенье (2 шт.) выложить на тарелку. Плитка бел. шоколад (10 г) растопить на водяной бане до 40-45 °C. Нанести полоски на печенье. Охладить 5 мин. Подавать при 18-22 °C.', 'ai', 'шоколада Хорека', 0.07, 0, 0, 0, 0, 'технологическая карта составлена на основании акта проработки. По физико-химическим показателям соответствует требованиям ГОСТ РФ 50763-2007 "Кулинарная продукция, реализуемая населению". По микробиологическим показателям соответствует требованиям СанПиН 2.3.2 1078-01', 257);
INSERT INTO tech_cards (card_number, dish_name, organization_id, approval_date, application_area, portion_norm, technology, technology_source, serving_requirements, total_output_kg, proteins_per_100g, fats_per_100g, carbs_per_100g, calories_per_100g, note, source_page) VALUES ('01951', 'Кокосовые конфеты', (SELECT id FROM organizations WHERE name='Бранч'), '2019-03-28', 'Cake&Coffee', 1.000, '(от ии) Кокосовые конфеты (готовые) — достать из холодильника. Шоколадная глазурь (20 г) растопить на водяной бане до 40-45 °C. Обмакнуть конфеты наполовину в шоколад. Выложить на пергамент. Посыпать Лепестки миндаля (3-5 шт. на конфету). Охладить 10-15 минут в холодильнике до застывания шоколада. Подавать при 8-12 °C.', 'ai', NULL, 0.074, 0, 0, 0, 0, 'технологическая карта составлена на основании акта проработки. По физико-химическим показателям соответствует требованиям ГОСТ РФ 50763-2007 "Кулинарная продукция, реализуемая населению". По микробиологическим показателям соответствует требованиям СанПиН 2.3.2 1078-01', 258);
INSERT INTO tech_cards (card_number, dish_name, organization_id, approval_date, application_area, portion_norm, technology, technology_source, serving_requirements, total_output_kg, proteins_per_100g, fats_per_100g, carbs_per_100g, calories_per_100g, note, source_page) VALUES ('01949', 'Круассаны с шоколадом', (SELECT id FROM organizations WHERE name='Бранч'), '2018-07-06', 'Cake&Coffee', 1.000, '(от ии) Тесто слоеное (порция 80 г) — если замороженное, разморозить в холодильнике 8-12 часов. Раскатать до толщины 4 мм. Нарезать треугольники (основание 10 см). На основание треугольника выложить Шоколад мол. в (батончик, 15 г). Завернуть, скатывая к вершине. Сформировать полумесяц. Выложить на противень с пергаментом, швом вниз. Смазать Яйцо куриное (1 шт., взболтанное) — яйцевая смазка. Расстойка при комнатной температуре 20-30 минут (круассаны должны увеличиться в объеме). Духовку разогреть до 220 °C. Выпекать 5 минут при 220 °C, затем снизить до 180-190 °C и выпекать еще 15-20 минут до золотистого цвета. Остудить на решетке 10 минут. Подавать при комнатной температуре (18-22 °C).', 'ai', 'галетах Шоколад тем. в галетах', 0.118, 0, 0, 0, 0, 'технологическая карта составлена на основании акта проработки. По физико-химическим показателям соответствует требованиям ГОСТ РФ 50763-2007 "Кулинарная продукция, реализуемая населению". По микробиологическим показателям соответствует требованиям СанПиН 2.3.2 1078-01', 259);
INSERT INTO tech_cards (card_number, dish_name, organization_id, approval_date, application_area, portion_norm, technology, technology_source, serving_requirements, total_output_kg, proteins_per_100g, fats_per_100g, carbs_per_100g, calories_per_100g, note, source_page) VALUES ('02008', 'Лимонный пай', (SELECT id FROM organizations WHERE name='Бранч'), '2018-10-02', 'Cake&Coffee', 1.000, '(от ии) Лимонный пай замес (готовое тесто для основы и лимонный курд) — если охлажденный, разогреть. Выпекать в духовке при 180 °C 15-20 минут до золотистого теста и прогрева начинки до 70-75 °C внутри. Остудить 15 минут. Подавать при 18-22 °C или слегка теплом (30-35 °C).', 'ai', NULL, 0.106, 0, 0, 0, 0, 'технологическая карта составлена на основании акта проработки. По физико-химическим показателям соответствует требованиям ГОСТ РФ 50763-2007 "Кулинарная продукция, реализуемая населению". По микробиологическим показателям соответствует требованиям СанПиН 2.3.2 1078-01', 260);
INSERT INTO tech_cards (card_number, dish_name, organization_id, approval_date, application_area, portion_norm, technology, technology_source, serving_requirements, total_output_kg, proteins_per_100g, fats_per_100g, carbs_per_100g, calories_per_100g, note, source_page) VALUES ('02995', 'Макаронс 1 шт.', (SELECT id FROM organizations WHERE name='Бранч'), '2021-11-06', 'Cake&Coffee', 1.000, '(от ии) Тесто для Макаронс (готовые половинки, 2 шт.) — аккуратно отсоединить от пергамента. На нижнюю половину выложить Крем сливочный (10-15 г) маленькой розеткой. Накрыть верхней половиной, слегка прижать. Охладить в холодильнике 30 минут перед подачей (крем застывает, макарон становится мягче). Подавать при 8-12 °C.', 'ai', NULL, 0.045, 0, 0, 0, 0, 'технологическая карта составлена на основании акта проработки. По физико-химическим показателям соответствует требованиям ГОСТ РФ 50763-2007 "Кулинарная продукция, реализуемая населению". По микробиологическим показателям соответствует требованиям СанПиН 2.3.2 1078-01', 261);
INSERT INTO tech_cards (card_number, dish_name, organization_id, approval_date, application_area, portion_norm, technology, technology_source, serving_requirements, total_output_kg, proteins_per_100g, fats_per_100g, carbs_per_100g, calories_per_100g, note, source_page) VALUES ('01286', 'Мильфей', (SELECT id FROM organizations WHERE name='Бранч'), '2017-03-21', 'Cake&Coffee', 1.000, '(от ии) Тесто слоеное (2-3 листа, готовое) выпечь при 200 °C 12-15 минут до золотистого цвета и расслоения. Остудить. Сливочный крем (80 г) — готовый или заварной. На тарелку выложить слой слоеного теста. Сверху — крем из мешка (20-25 г). Накрыть вторым слоем теста. Снова крем. Третий слой теста. Сверху — розетка из Заварной крем (15 г). Посыпать Сахарная пудра. Подавать при 18-22 °C.', 'ai', NULL, 0.12, 0, 0, 0, 0, 'технологическая карта составлена на основании акта проработки. По физико-химическим показателям соответствует требованиям ГОСТ РФ 50763-2007 "Кулинарная продукция, реализуемая населению". По микробиологическим показателям соответствует требованиям СанПиН 2.3.2 1078-01', 262);
INSERT INTO tech_cards (card_number, dish_name, organization_id, approval_date, application_area, portion_norm, technology, technology_source, serving_requirements, total_output_kg, proteins_per_100g, fats_per_100g, carbs_per_100g, calories_per_100g, note, source_page) VALUES ('00852', 'Морковный пирог', (SELECT id FROM organizations WHERE name='Бранч'), '2017-12-19', 'Cake&Coffee', 1.000, '(от ии) Морковный пирог (готовый) — нарезать порцию (кусок 80-100 г). Подавать при комнатной температуре 18-22 °C.', 'ai', NULL, 0.055, 0, 0, 0, 0, 'технологическая карта составлена на основании акта проработки. По физико-химическим показателям соответствует требованиям ГОСТ РФ 50763-2007 "Кулинарная продукция, реализуемая населению". По микробиологическим показателям соответствует требованиям СанПиН 2.3.2 1078-01', 263);
INSERT INTO tech_cards (card_number, dish_name, organization_id, approval_date, application_area, portion_norm, technology, technology_source, serving_requirements, total_output_kg, proteins_per_100g, fats_per_100g, carbs_per_100g, calories_per_100g, note, source_page) VALUES ('02247', 'Морковный пирог ПП', (SELECT id FROM organizations WHERE name='Бранч'), '2019-06-17', 'Cake&Coffee', 1.000, '(от ии) ПП морковный пирог (готовый, без глютена/сахарозаменитель) — нарезать порцию. Подавать при 18-22 °C.', 'ai', NULL, 0.1, 0, 0, 0, 0, 'технологическая карта составлена на основании акта проработки. По физико-химическим показателям соответствует требованиям ГОСТ РФ 50763-2007 "Кулинарная продукция, реализуемая населению". По микробиологическим показателям соответствует требованиям СанПиН 2.3.2 1078-01', 264);
INSERT INTO tech_cards (card_number, dish_name, organization_id, approval_date, application_area, portion_norm, technology, technology_source, serving_requirements, total_output_kg, proteins_per_100g, fats_per_100g, carbs_per_100g, calories_per_100g, note, source_page) VALUES ('00692', 'Мороженое шарик', (SELECT id FROM organizations WHERE name='Бранч'), '2018-11-30', 'Cake&Coffee', 1.000, '(от ии) Мороженое (1 шарик, ~50 г) — набрать мороженым совком (сферическим лопаткой). Выложить в креманку/стакан. Подавать немедленно при -14...-18 °C.', 'ai', NULL, 0.05, 0, 0, 0, 0, 'технологическая карта составлена на основании акта проработки. По физико-химическим показателям соответствует требованиям ГОСТ РФ 50763-2007 "Кулинарная продукция, реализуемая населению". По микробиологическим показателям соответствует требованиям СанПиН 2.3.2 1078-01', 265);
INSERT INTO tech_cards (card_number, dish_name, organization_id, approval_date, application_area, portion_norm, technology, technology_source, serving_requirements, total_output_kg, proteins_per_100g, fats_per_100g, carbs_per_100g, calories_per_100g, note, source_page) VALUES ('02996', 'Муссовый Эскимо', (SELECT id FROM organizations WHERE name='Бранч'), '2021-11-10', 'Cake&Coffee', 1.000, '(от ии) Желатин пищевой (5 г) замочить в холодной воде (30 мл) на 10 минут. Ягода клубника (50 г) пюрировать блендером. Сахар-песок (30 г), Крахмал кукурузный (10 г) и Молоко 3,2% (100 мл) — довести до кипения, варить 2 минуты, помешивая, до загустения. Снять с огня, добавить набухший желатин, размешать до растворения. Добавить пюре клубники. Сливки 33% (100 г) взбить до мягких пиков. Аккуратно вмешать в клубничную массу. Разлить по формочкам для эскимо (или силиконовым). Заморозить минимум 4 часа. Шоколад (30 г) растопить при 40-45 °C. Окунуть эскимо в шоколад, дать застыть. Подавать при -14...-18 °C.', 'ai', 'морожен. Сыр творожный креметта Посыпка кондитерская', 0.1565, 0, 0, 0, 0, 'технологическая карта составлена на основании акта проработки. По физико-химическим показателям соответствует требованиям ГОСТ РФ 50763-2007 "Кулинарная продукция, реализуемая населению". По микробиологическим показателям соответствует требованиям СанПиН 2.3.2 1078-01', 266);
INSERT INTO tech_cards (card_number, dish_name, organization_id, approval_date, application_area, portion_norm, technology, technology_source, serving_requirements, total_output_kg, proteins_per_100g, fats_per_100g, carbs_per_100g, calories_per_100g, note, source_page) VALUES ('02649', 'Ореховое пралине', (SELECT id FROM organizations WHERE name='Бранч'), '2020-11-23', 'Cake&Coffee', 1.000, '(от ии) Тирамису (готовое, порция 30 г) — подать в формочке/на тарелке. Посыпать какао. Подавать при 8-12 °C.', 'ai', NULL, 0.243, 0, 0, 0, 0, 'технологическая карта составлена на основании акта проработки. По физико-химическим показателям соответствует требованиям ГОСТ РФ 50763-2007 "Кулинарная продукция, реализуемая населению". По микробиологическим показателям соответствует требованиям СанПиН 2.3.2 1078-01', 267);
INSERT INTO tech_cards (card_number, dish_name, organization_id, approval_date, application_area, portion_norm, technology, technology_source, serving_requirements, total_output_kg, proteins_per_100g, fats_per_100g, carbs_per_100g, calories_per_100g, note, source_page) VALUES ('02239', 'ПП конферты из смородины', (SELECT id FROM organizations WHERE name='Бранч'), '2020-12-23', 'Cake&Coffee', 5.000, '(от ии) Ягода заморозка (черная смородина, 100 г) разморозить, слить лишнюю жидкость. Смешать с Мед (20 г) и Хлопья овсяные (40 г). Сформировать шарики d=2,5 см. Обвалять в Кокосовая стружка (20 г) и Семена чиа (5 г). Убрать в холодильник на 30 минут для застывания. Подавать при 5-10 °C.', 'ai', NULL, 0.215, 5, 12, 31, 246, 'технологическая карта составлена на основании акта проработки. По физико-химическим показателям соответствует требованиям ГОСТ РФ 50763-2007 "Кулинарная продукция, реализуемая населению". По микробиологическим показателям соответствует требованиям СанПиН 2.3.2 1078-01', 268);
INSERT INTO tech_cards (card_number, dish_name, organization_id, approval_date, application_area, portion_norm, technology, technology_source, serving_requirements, total_output_kg, proteins_per_100g, fats_per_100g, carbs_per_100g, calories_per_100g, note, source_page) VALUES ('02241', 'ПП чиа', (SELECT id FROM organizations WHERE name='Бранч'), '2019-06-12', 'Cake&Coffee', 8.000, '(от ии) Семена чиа (20 г) залить Молоко кокосовое (150 мл). Перемешать. Убрать в холодильник минимум на 4 часа (или на ночь). Чиа набухнет и образует пудинг. Абрикосы (30 г) нарезать дольками. Выложить сверху пудинга. Подавать при 5-10 °C.', 'ai', NULL, 1.39, 4, 5, 9, 98, 'технологическая карта составлена на основании акта проработки. По физико-химическим показателям соответствует требованиям ГОСТ РФ 50763-2007 "Кулинарная продукция, реализуемая населению". По микробиологическим показателям соответствует требованиям СанПиН 2.3.2 1078-01', 269);
INSERT INTO tech_cards (card_number, dish_name, organization_id, approval_date, application_area, portion_norm, technology, technology_source, serving_requirements, total_output_kg, proteins_per_100g, fats_per_100g, carbs_per_100g, calories_per_100g, note, source_page) VALUES ('02171', 'Протеиновые батончики', (SELECT id FROM organizations WHERE name='Бранч'), '2019-03-15', 'Cake&Coffee', 5.000, '(от ии) Хлопья овсяные (60 г) измельчить в блендере до крупной крошки. Добавить протеин (30 г, порошок). П/йогурт DANON (30 г) и Миндаль (20 г, рубленый) — добавить в сухую смесь. Перемешать до образования липкого теста (при необходимости добавить немного воды). Выложить на пергамент, разровнять в прямоугольник толщиной 1 см. Заморозить 1 час. Нарезать на батончики (3х8 см). Хранить в холодильнике. Подавать при 5-10 °C.', 'ai', 'Какао Красный октябрь Шоколад тем. в галетах', 0.36, 24, 12, 25, 305, 'технологическая карта составлена на основании акта проработки. По физико-химическим показателям соответствует требованиям ГОСТ РФ 50763-2007 "Кулинарная продукция, реализуемая населению". По микробиологическим показателям соответствует требованиям СанПиН 2.3.2 1078-01', 270);
INSERT INTO tech_cards (card_number, dish_name, organization_id, approval_date, application_area, portion_norm, technology, technology_source, serving_requirements, total_output_kg, proteins_per_100g, fats_per_100g, carbs_per_100g, calories_per_100g, note, source_page) VALUES ('00460', 'Профитроль', (SELECT id FROM organizations WHERE name='Бранч'), '2016-09-18', 'Cake&Coffee', 1.000, '(от ии) Профитроль: Заварное (2-3 шт., готовые, диаметром 3-4 см) — заполнить Заварной крем (20 г) через отверстие снизу с помощью кондитерского мешка. Выложить на тарелку. Сверху посыпать Сахарная пудра. Подавать при 8-15 °C.', 'ai', NULL, 0.126, 0, 0, 0, 0, 'технологическая карта составлена на основании акта проработки. По физико-химическим показателям соответствует требованиям ГОСТ РФ 50763-2007 "Кулинарная продукция, реализуемая населению". По микробиологическим показателям соответствует требованиям СанПиН 2.3.2 1078-01', 271);
INSERT INTO tech_cards (card_number, dish_name, organization_id, approval_date, application_area, portion_norm, technology, technology_source, serving_requirements, total_output_kg, proteins_per_100g, fats_per_100g, carbs_per_100g, calories_per_100g, note, source_page) VALUES ('02467', 'Профитрольный пирог', (SELECT id FROM organizations WHERE name='Бранч'), '2020-05-02', 'Cake&Coffee', 8.000, '(от ии) Заварное тесто (см. Шу): отсадить на пергамент кольцом d=20 см, или выложить отдельные профитроли (d=3 см, 15-20 шт.) на противень. Выпекать при 200 °C 10 мин, затем 170 °C 20-25 мин. Остудить. Сыр творожный (100 г) смешать со Сливки 33% (50 г, взбитыми) и Сахарная пудра (20 г). Заполнить профитроли кремом из мешка. Выложить горкой на тарелку. Полить Топинг (15 мл) и Сахарная пудра. Подавать при 8-12 °C.', 'ai', 'креметта', 2.168, 0, 0, 0, 0, 'технологическая карта составлена на основании акта проработки. По физико-химическим показателям соответствует требованиям ГОСТ РФ 50763-2007 "Кулинарная продукция, реализуемая населению". По микробиологическим показателям соответствует требованиям СанПиН 2.3.2 1078-01', 272);
INSERT INTO tech_cards (card_number, dish_name, organization_id, approval_date, application_area, portion_norm, technology, technology_source, serving_requirements, total_output_kg, proteins_per_100g, fats_per_100g, carbs_per_100g, calories_per_100g, note, source_page) VALUES ('03103', 'Рафаэлло', (SELECT id FROM organizations WHERE name='Бранч'), '2022-02-26', 'Cake&Coffee', 1.000, '(от ии) Яйцо куриное (2 шт., белки) взбить до мягких пиков. Добавить Сахар-песок (80 г) по ложке, взбивать до жестких пиков. Добавить Кокосовая стружка (100 г), Крахмал кукурузный (15 г), Миндаль (30 г, измельченный), Масло сливочное (30 г, размягченное), Ваниль (2 г). Аккуратно перемешать лопаткой. Сформировать шарики (d=3 см). Выложить на пергамент. Выпекать при 150 °C 15-18 минут до легкого золотистого цвета (не пересушить — внутри должны быть мягкими). Остудить. Обвалять в Кокосовая стружка. Подавать при 18-22 °C.', 'ai', 'Шоколад белый в галетах', 1.982, 0, 0, 0, 0, 'технологическая карта составлена на основании акта проработки. По физико-химическим показателям соответствует требованиям ГОСТ РФ 50763-2007 "Кулинарная продукция, реализуемая населению". По микробиологическим показателям соответствует требованиям СанПиН 2.3.2 1078-01', 273);
INSERT INTO tech_cards (card_number, dish_name, organization_id, approval_date, application_area, portion_norm, technology, technology_source, serving_requirements, total_output_kg, proteins_per_100g, fats_per_100g, carbs_per_100g, calories_per_100g, note, source_page) VALUES ('02121', 'Свежая голубика', (SELECT id FROM organizations WHERE name='Бранч'), '2019-02-13', 'Cake&Coffee', 1.000, '(от ии) Свежая голубика (порция 50 г) — промыть, обсушить. Выложить в креманку. Подавать при 5-10 °C.', 'ai', NULL, 0.125, 0, 0, 0, 0, 'технологическая карта составлена на основании акта проработки. По физико-химическим показателям соответствует требованиям ГОСТ РФ 50763-2007 "Кулинарная продукция, реализуемая населению". По микробиологическим показателям соответствует требованиям СанПиН 2.3.2 1078-01', 274);
INSERT INTO tech_cards (card_number, dish_name, organization_id, approval_date, application_area, portion_norm, technology, technology_source, serving_requirements, total_output_kg, proteins_per_100g, fats_per_100g, carbs_per_100g, calories_per_100g, note, source_page) VALUES ('02120', 'Свежая клубника', (SELECT id FROM organizations WHERE name='Бранч'), '2019-02-13', 'Cake&Coffee', 1.000, '(от ии) Свежая клубника (порция 50 г) — промыть, обсушить, удалить плодоножки. Выложить на тарелку. Подавать при 5-10 °C.', 'ai', NULL, 0.25, 0, 0, 0, 0, 'технологическая карта составлена на основании акта проработки. По физико-химическим показателям соответствует требованиям ГОСТ РФ 50763-2007 "Кулинарная продукция, реализуемая населению". По микробиологическим показателям соответствует требованиям СанПиН 2.3.2 1078-01', 275);
INSERT INTO tech_cards (card_number, dish_name, organization_id, approval_date, application_area, portion_norm, technology, technology_source, serving_requirements, total_output_kg, proteins_per_100g, fats_per_100g, carbs_per_100g, calories_per_100g, note, source_page) VALUES ('03099', 'Сладкая "Валентинка"', (SELECT id FROM organizations WHERE name='Бранч'), '2022-02-14', 'Cake&Coffee', 1.000, '(от ии) Торт сердечко (готовый, полуфабрикат) — разморозить при комнатной температуре 20-30 минут. Нарезать на порции (по 2-3 см). Выложить на тарелку. При желании украсить Сахарная пудра. Подавать при 8-12 °C.', 'ai', NULL, 0.2325, 0, 0, 0, 0, 'технологическая карта составлена на основании акта проработки. По физико-химическим показателям соответствует требованиям ГОСТ РФ 50763-2007 "Кулинарная продукция, реализуемая населению". По микробиологическим показателям соответствует требованиям СанПиН 2.3.2 1078-01', 276);
INSERT INTO tech_cards (card_number, dish_name, organization_id, approval_date, application_area, portion_norm, technology, technology_source, serving_requirements, total_output_kg, proteins_per_100g, fats_per_100g, carbs_per_100g, calories_per_100g, note, source_page) VALUES ('02417', 'Сладкая "Валентинка"', (SELECT id FROM organizations WHERE name='Бранч'), '2020-02-13', 'Cake&Coffee', 1.000, '(от ии) Торт сердечко (готовый, полуфабрикат) — разморозить при комнатной температуре 20-30 минут. Нарезать на порции (по 2-3 см). Выложить на тарелку. При желании украсить Сахарная пудра. Подавать при 8-12 °C.', 'ai', NULL, 0.2325, 0, 0, 0, 0, 'технологическая карта составлена на основании акта проработки. По физико-химическим показателям соответствует требованиям ГОСТ РФ 50763-2007 "Кулинарная продукция, реализуемая населению". По микробиологическим показателям соответствует требованиям СанПиН 2.3.2 1078-01', 277);
INSERT INTO tech_cards (card_number, dish_name, organization_id, approval_date, application_area, portion_norm, technology, technology_source, serving_requirements, total_output_kg, proteins_per_100g, fats_per_100g, carbs_per_100g, calories_per_100g, note, source_page) VALUES ('03100', 'Сладкая "Валентинка"', (SELECT id FROM organizations WHERE name='Бранч'), '2022-02-14', 'Cake&Coffee', 1.000, '(от ии) Торт сердечко (готовый, полуфабрикат) — разморозить при комнатной температуре 20-30 минут. Нарезать на порции (по 2-3 см). Выложить на тарелку. При желании украсить Сахарная пудра. Подавать при 8-12 °C.', 'ai', NULL, 0.2325, 0, 0, 0, 0, 'технологическая карта составлена на основании акта проработки. По физико-химическим показателям соответствует требованиям ГОСТ РФ 50763-2007 "Кулинарная продукция, реализуемая населению". По микробиологическим показателям соответствует требованиям СанПиН 2.3.2 1078-01', 278);
INSERT INTO tech_cards (card_number, dish_name, organization_id, approval_date, application_area, portion_norm, technology, technology_source, serving_requirements, total_output_kg, proteins_per_100g, fats_per_100g, carbs_per_100g, calories_per_100g, note, source_page) VALUES ('02240', 'Творожный суфле', (SELECT id FROM organizations WHERE name='Бранч'), '2019-06-12', 'Cake&Coffee', 1.000, '(от ии) Творог 5% (150 г) протереть через сито. Яйцо куриное (2 шт.) разделить. Белки взбить до жестких пиков. Желтки растереть с сахаром (если есть), соединить с творогом. Аккуратно вмешать белки в творожную массу. Выложить в формочки (керамические, смазанные маслом). Выпекать на водяной бане в духовке при 160 °C 25-30 минут до подъема и легкого золотистого цвета. Подавать немедленно (суфле оседает через 5-10 минут). Температура подачи 55-65 °C.', 'ai', 'стевия (заменитель сахара) Сироп Rioba клубничный', 0.1385, 0, 0, 0, 0, 'технологическая карта составлена на основании акта проработки. По физико-химическим показателям соответствует требованиям ГОСТ РФ 50763-2007 "Кулинарная продукция, реализуемая населению". По микробиологическим показателям соответствует требованиям СанПиН 2.3.2 1078-01', 279);
INSERT INTO tech_cards (card_number, dish_name, organization_id, approval_date, application_area, portion_norm, technology, technology_source, serving_requirements, total_output_kg, proteins_per_100g, fats_per_100g, carbs_per_100g, calories_per_100g, note, source_page) VALUES ('00463', 'Тирамису', (SELECT id FROM organizations WHERE name='Бранч'), '2016-09-18', 'Cake&Coffee', 1.000, '(от ии) Тирамису (порция, готовый) — достать из холодильника за 5-10 минут до подачи. Перевернуть на тарелку. Посыпать какао-порошком. Подавать при 8-12 °C.', 'ai', NULL, 0.243, 0, 0, 0, 0, 'технологическая карта составлена на основании акта проработки. По физико-химическим показателям соответствует требованиям ГОСТ РФ 50763-2007 "Кулинарная продукция, реализуемая населению". По микробиологическим показателям соответствует требованиям СанПиН 2.3.2 1078-01', 280);
INSERT INTO tech_cards (card_number, dish_name, organization_id, approval_date, application_area, portion_norm, technology, technology_source, serving_requirements, total_output_kg, proteins_per_100g, fats_per_100g, carbs_per_100g, calories_per_100g, note, source_page) VALUES ('02413', 'Торт Антраме', (SELECT id FROM organizations WHERE name='Бранч'), '2020-02-11', 'Cake&Coffee', 8.000, '(от ии) Бисквит шоколадный: Сахар-песок (120 г), Сахарная пудра (30 г), Мука хлебопекарная (80 г), Яйцо куриное (4 шт.), Крахмал (20 г), Какао (30 г), Масло сливочное (80 г), Разрыхлитель (3 г) — взбить яйца с сахаром до пышности, добавить масло, затем сухие ингредиенты. Выпекать при 170 °C 30-35 мин. Остудить. Ганаш: Шоколад темный (200 г) растопить с Сливки 33% (200 г) при 60 °C. Остудить до 25-30 °C. Бисквит разрезать на 2 коржа. Пропитать кофейным сиропом. Собрать: корж → ганаш → корж → ганаш (обмазать бока и верх). Украсить шоколадной стружкой/какао. Охладить минимум 4 часа. Подавать при 8-12 °C.', 'ai', 'Ягода клубника морожен. Сыр творожный креметта Шоколад белый в галетах', 1.59, 0, 0, 0, 0, 'технологическая карта составлена на основании акта проработки. По физико-химическим показателям соответствует требованиям ГОСТ РФ 50763-2007 "Кулинарная продукция, реализуемая населению". По микробиологическим показателям соответствует требованиям СанПиН 2.3.2 1078-01', 281);
INSERT INTO tech_cards (card_number, dish_name, organization_id, approval_date, application_area, portion_norm, technology, technology_source, serving_requirements, total_output_kg, proteins_per_100g, fats_per_100g, carbs_per_100g, calories_per_100g, note, source_page) VALUES ('02315', 'Черешня', (SELECT id FROM organizations WHERE name='Бранч'), '2019-07-22', 'Cake&Coffee', 1.000, '(от ии) Черешня (порция 50 г) — промыть, удалить косточки при необходимости. Выложить на тарелку. Подавать при 5-10 °C.', 'ai', NULL, 0.3, 0, 0, 0, 0, 'технологическая карта составлена на основании акта проработки. По физико-химическим показателям соответствует требованиям ГОСТ РФ 50763-2007 "Кулинарная продукция, реализуемая населению". По микробиологическим показателям соответствует требованиям СанПиН 2.3.2 1078-01', 282);
INSERT INTO tech_cards (card_number, dish_name, organization_id, approval_date, application_area, portion_norm, technology, technology_source, serving_requirements, total_output_kg, proteins_per_100g, fats_per_100g, carbs_per_100g, calories_per_100g, note, source_page) VALUES ('00465', 'Чизкейк', (SELECT id FROM organizations WHERE name='Бранч'), '2016-09-18', 'Cake&Coffee', 1.000, '(от ии) Чизкейк: Основа на чизкейк (1 порция). Выложить Сливочный крем (60 г) из мешка. Украсить ягодами/топпингом. Подавать при 8-12 °C.', 'ai', NULL, 0.153, 0, 0, 0, 0, 'технологическая карта составлена на основании акта проработки. По физико-химическим показателям соответствует требованиям ГОСТ РФ 50763-2007 "Кулинарная продукция, реализуемая населению". По микробиологическим показателям соответствует требованиям СанПиН 2.3.2 1078-01', 283);
INSERT INTO tech_cards (card_number, dish_name, organization_id, approval_date, application_area, portion_norm, technology, technology_source, serving_requirements, total_output_kg, proteins_per_100g, fats_per_100g, carbs_per_100g, calories_per_100g, note, source_page) VALUES ('00878', 'Чизкейк мусс в стакнчике с собой', (SELECT id FROM organizations WHERE name='Бранч'), '2016-11-08', 'Cake&Coffee', 1.000, '(от ии) Основа на чизкейк (1 шт.) в стакан/контейнер с собой. Добавить Сливочный крем с (60 г) из мешка. Топинг (10 мл). Закрыть крышкой. Выдать гостю. Подавать при 8-12 °C.', 'ai', 'йогуртом', 0.28, 0, 0, 0, 0, 'технологическая карта составлена на основании акта проработки. По физико-химическим показателям соответствует требованиям ГОСТ РФ 50763-2007 "Кулинарная продукция, реализуемая населению". По микробиологическим показателям соответствует требованиям СанПиН 2.3.2 1078-01', 284);
INSERT INTO tech_cards (card_number, dish_name, organization_id, approval_date, application_area, portion_norm, technology, technology_source, serving_requirements, total_output_kg, proteins_per_100g, fats_per_100g, carbs_per_100g, calories_per_100g, note, source_page) VALUES ('02415', 'Шок. конфеты', (SELECT id FROM organizations WHERE name='Бранч'), '2020-02-11', 'Cake&Coffee', 1.000, '(от ии) новые конфеты (готовые, 2-3 шт.) — выложить на тарелку. Подавать при 18-22 °C.', 'ai', NULL, 0.01, 0, 0, 0, 0, 'технологическая карта составлена на основании акта проработки. По физико-химическим показателям соответствует требованиям ГОСТ РФ 50763-2007 "Кулинарная продукция, реализуемая населению". По микробиологическим показателям соответствует требованиям СанПиН 2.3.2 1078-01', 285);
INSERT INTO tech_cards (card_number, dish_name, organization_id, approval_date, application_area, portion_norm, technology, technology_source, serving_requirements, total_output_kg, proteins_per_100g, fats_per_100g, carbs_per_100g, calories_per_100g, note, source_page) VALUES ('00458', 'Шок. шар. из белого бисквита', (SELECT id FROM organizations WHERE name='Бранч'), '2016-09-18', 'Cake&Coffee', 1.000, '(от ии) Шок. шар. из белого бисквита (готовый) — выложить на тарелку. При необходимости — подогреть 10 сек в микроволновке. Подавать при 18-22 °C.', 'ai', NULL, 0.08, 0, 0, 0, 0, 'технологическая карта составлена на основании акта проработки. По физико-химическим показателям соответствует требованиям ГОСТ РФ 50763-2007 "Кулинарная продукция, реализуемая населению". По микробиологическим показателям соответствует требованиям СанПиН 2.3.2 1078-01', 286);
INSERT INTO tech_cards (card_number, dish_name, organization_id, approval_date, application_area, portion_norm, technology, technology_source, serving_requirements, total_output_kg, proteins_per_100g, fats_per_100g, carbs_per_100g, calories_per_100g, note, source_page) VALUES ('02985', 'Шоколадная тарталетка', (SELECT id FROM organizations WHERE name='Бранч'), '2021-10-09', 'Cake&Coffee', 1.000, '(от ии) Шоколадный ганаш (готовый, 30 г) — подогреть до 30-35 °C до мягкой консистенции. Выложить в тарталетку (готовую, из шоколадного теста). Сверху — Безе (1-2 шт., готовые). Подавать при 18-22 °C.', 'ai', NULL, 0.0756, 0, 0, 0, 0, 'технологическая карта составлена на основании акта проработки. По физико-химическим показателям соответствует требованиям ГОСТ РФ 50763-2007 "Кулинарная продукция, реализуемая населению". По микробиологическим показателям соответствует требованиям СанПиН 2.3.2 1078-01', 287);
INSERT INTO tech_cards (card_number, dish_name, organization_id, approval_date, application_area, portion_norm, technology, technology_source, serving_requirements, total_output_kg, proteins_per_100g, fats_per_100g, carbs_per_100g, calories_per_100g, note, source_page) VALUES ('01755', 'Шоколадный блинный торт', (SELECT id FROM organizations WHERE name='Бранч'), '2018-01-12', 'Cake&Coffee', 1.000, '(от ии) шоколадные блины (3-4 шт., готовые). Выкладывать блин, промазывать крем для (30 г). Слои чередовать. Верх украсить кремом и какао/шоколадной стружкой. Подавать при 8-12 °C.', 'ai', 'шоколадных блинов', 0.2426, 0, 0, 0, 0, 'технологическая карта составлена на основании акта проработки. По физико-химическим показателям соответствует требованиям ГОСТ РФ 50763-2007 "Кулинарная продукция, реализуемая населению". По микробиологическим показателям соответствует требованиям СанПиН 2.3.2 1078-01', 288);
INSERT INTO tech_cards (card_number, dish_name, organization_id, approval_date, application_area, portion_norm, technology, technology_source, serving_requirements, total_output_kg, proteins_per_100g, fats_per_100g, carbs_per_100g, calories_per_100g, note, source_page) VALUES ('02186', 'Шоколадный Мафин', (SELECT id FROM organizations WHERE name='Бранч'), '2020-12-23', 'Cake&Coffee', 6.000, '(от ии) Сухие ингредиенты: Мука хлебопекарная (150 г), Сахар-песок (100 г), Разрыхлитель (5 г), Какао-порошок (30 г) — просеять, смешать. Жидкие ингредиенты: Молоко 3,2% (120 мл), Масло сливочное (60 г, растопленное до 40 °C), Яйцо куриное (1 шт.) — смешать. Соединить жидкие и сухие, перемешать лопаткой до однородности (не перестараться — тесто может быть комковатым). Разлить по формочкам для маффинов (заполнять на 2/3). Выпекать при 180-190 °C 20-25 минут до сухой зубочистки. Остудить 5 минут в форме, затем на решетке. Подавать при 18-22 °C.', 'ai', 'Шоколад тем. в галетах', 0.772, 0, 0, 0, 0, 'технологическая карта составлена на основании акта проработки. По физико-химическим показателям соответствует требованиям ГОСТ РФ 50763-2007 "Кулинарная продукция, реализуемая населению". По микробиологическим показателям соответствует требованиям СанПиН 2.3.2 1078-01', 289);
INSERT INTO tech_cards (card_number, dish_name, organization_id, approval_date, application_area, portion_norm, technology, technology_source, serving_requirements, total_output_kg, proteins_per_100g, fats_per_100g, carbs_per_100g, calories_per_100g, note, source_page) VALUES ('01942', 'Шоколадный маффин', (SELECT id FROM organizations WHERE name='Бранч'), '2018-07-02', 'Cake&Coffee', 1.000, '(от ии) Основа на маффин (готовый кекс, 80 г) — разогреть в микроволновке 15-20 секунд при 600 Вт. Сверху выложить Крем на маффин (20 г) из кондитерского мешка. Полить Шоколадная глазурь (10 г), растопленной до 40-45 °C. Подавать при 35-40 °C.', 'ai', NULL, 0.11, 0, 0, 0, 0, 'технологическая карта составлена на основании акта проработки. По физико-химическим показателям соответствует требованиям ГОСТ РФ 50763-2007 "Кулинарная продукция, реализуемая населению". По микробиологическим показателям соответствует требованиям СанПиН 2.3.2 1078-01', 290);
INSERT INTO tech_cards (card_number, dish_name, organization_id, approval_date, application_area, portion_norm, technology, technology_source, serving_requirements, total_output_kg, proteins_per_100g, fats_per_100g, carbs_per_100g, calories_per_100g, note, source_page) VALUES ('02081', 'Шу', (SELECT id FROM organizations WHERE name='Бранч'), '2019-01-31', 'Cake&Coffee', 16.000, '(от ии) Заварное тесто: Воду (60 мл) и Масло сливочное (30 г) довести до кипения. Всыпать Мука хлебопекарная (40 г), вымешать до кома. Остудить до 60 °C. Ввести Яйцо куриное (1-2 шт.) по одному, вымешивая. Отсадить шарики (d=4-5 см) на пергамент. Выпекать при 200 °C 10 минут, затем 170 °C 15-20 минут. Остудить. Заполнить Сливочный крем (15 г) через отверстие снизу. Подавать при 8-12 °C.', 'ai', NULL, 1.69, 0, 0, 0, 0, 'технологическая карта составлена на основании акта проработки. По физико-химическим показателям соответствует требованиям ГОСТ РФ 50763-2007 "Кулинарная продукция, реализуемая населению". По микробиологическим показателям соответствует требованиям СанПиН 2.3.2 1078-01', 291);
INSERT INTO tech_cards (card_number, dish_name, organization_id, approval_date, application_area, portion_norm, technology, technology_source, serving_requirements, total_output_kg, proteins_per_100g, fats_per_100g, carbs_per_100g, calories_per_100g, note, source_page) VALUES ('00589', 'Эклер с вареной сгущенкой', (SELECT id FROM organizations WHERE name='Бранч'), '2018-07-13', 'Cake&Coffee', 1.000, '(от ии) Заварное (1 шт., готовый) — разрезать вдоль пополам. На нижнюю часть выложить Варенка на эклеры (30 г). Накрыть верхней половиной. Полить Шоколадная глазурь (10 г, растопленной до 40-45 °C). Подавать при 8-12 °C.', 'ai', NULL, 0.206, 0, 0, 0, 0, 'технологическая карта составлена на основании акта проработки. По физико-химическим показателям соответствует требованиям ГОСТ РФ 50763-2007 "Кулинарная продукция, реализуемая населению". По микробиологическим показателям соответствует требованиям СанПиН 2.3.2 1078-01', 292);
INSERT INTO tech_cards (card_number, dish_name, organization_id, approval_date, application_area, portion_norm, technology, technology_source, serving_requirements, total_output_kg, proteins_per_100g, fats_per_100g, carbs_per_100g, calories_per_100g, note, source_page) VALUES ('01965', 'Эклеры с вареной сгущенкой мини', (SELECT id FROM organizations WHERE name='Бранч'), '2018-07-12', 'Cake&Coffee', 1.000, '(от ии) Заварное (мини, 2-3 шт.) — заполнить Варенка на эклеры (10 г на шт.) через отверстие снизу. Полить Шоколадная глазурь. Подавать при 8-12 °C.', 'ai', NULL, 0.135, 0, 0, 0, 0, 'технологическая карта составлена на основании акта проработки. По физико-химическим показателям соответствует требованиям ГОСТ РФ 50763-2007 "Кулинарная продукция, реализуемая населению". По микробиологическим показателям соответствует требованиям СанПиН 2.3.2 1078-01', 293);
INSERT INTO tech_cards (card_number, dish_name, organization_id, approval_date, application_area, portion_norm, technology, technology_source, serving_requirements, total_output_kg, proteins_per_100g, fats_per_100g, carbs_per_100g, calories_per_100g, note, source_page) VALUES ('02233', 'Яблочный зефир', (SELECT id FROM organizations WHERE name='Бранч'), '2019-05-23', 'Cake&Coffee', 1.000, '(от ии) яблочный зефир (готовый, 2-3 шт.) — выложить на тарелку. Подавать при 18-22 °C. Хранить в герметичной таре.', 'ai', NULL, 0.05, 0, 0, 0, 0, 'технологическая карта составлена на основании акта проработки. По физико-химическим показателям соответствует требованиям ГОСТ РФ 50763-2007 "Кулинарная продукция, реализуемая населению". По микробиологическим показателям соответствует требованиям СанПиН 2.3.2 1078-01', 294);
