INSERT INTO tech_cards (card_number, dish_name, organization_id, approval_date, application_area, portion_norm, technology, technology_source, serving_requirements, total_output_kg, proteins_per_100g, fats_per_100g, carbs_per_100g, calories_per_100g, note, source_page) VALUES ('03088', 'Блинный торт.', (SELECT id FROM organizations WHERE name='Бранч'), '2022-01-07', 'Cake&Coffee', 1.000, '(от ии) блины (3-4 шт., готовые). Выкладывать блин, промазывать Крем маскарпоне (30 г). Слои. Верх украсить кремом. Подавать при 8-12 °C.', 'ai', NULL, 1.0, 0, 0, 0, 0, 'технологическая карта составлена на основании акта проработки. По физико-химическим показателям соответствует требованиям ГОСТ РФ 50763-2007 "Кулинарная продукция, реализуемая населению". По микробиологическим показателям соответствует требованиям СанПиН 2.3.2 1078-01', 321);
INSERT INTO tech_cards (card_number, dish_name, organization_id, approval_date, application_area, portion_norm, technology, technology_source, serving_requirements, total_output_kg, proteins_per_100g, fats_per_100g, carbs_per_100g, calories_per_100g, note, source_page) VALUES ('03085', 'Медовик', (SELECT id FROM organizations WHERE name='Бранч'), '2022-01-07', 'Cake&Coffee', 1.000, '(от ии) Медовые коржи (2 шт., готовые) пропитать Сгущенка вареная (10 мл) смешанной с водой (10 мл). Промазать Крем сметанный (40 г) между коржами. Обсыпать бока и верх крошкой из коржа. Украсить кремом. Подавать при 8-12 °C.', 'ai', NULL, 1.0032, 0, 0, 0, 0, 'технологическая карта составлена на основании акта проработки. По физико-химическим показателям соответствует требованиям ГОСТ РФ 50763-2007 "Кулинарная продукция, реализуемая населению". По микробиологическим показателям соответствует требованиям СанПиН 2.3.2 1078-01', 322);
INSERT INTO tech_cards (card_number, dish_name, organization_id, approval_date, application_area, portion_norm, technology, technology_source, serving_requirements, total_output_kg, proteins_per_100g, fats_per_100g, carbs_per_100g, calories_per_100g, note, source_page) VALUES ('03086', 'Наполеон', (SELECT id FROM organizations WHERE name='Бранч'), '2022-01-07', 'Cake&Coffee', 1.000, '(от ии) Корж на Наполеон (2 шт.) пропитать заварным кремом. Крем Заварной (50 г) выложить на первый корж, накрыть вторым. Сверху — крем (розетка). Посыпать Сливки 33% (взбитыми, 20 г) и Сахарная пудра. Подавать при 8-12 °C.', 'ai', NULL, 1.039, 0, 0, 0, 0, 'технологическая карта составлена на основании акта проработки. По физико-химическим показателям соответствует требованиям ГОСТ РФ 50763-2007 "Кулинарная продукция, реализуемая населению". По микробиологическим показателям соответствует требованиям СанПиН 2.3.2 1078-01', 323);
INSERT INTO tech_cards (card_number, dish_name, organization_id, approval_date, application_area, portion_norm, technology, technology_source, serving_requirements, total_output_kg, proteins_per_100g, fats_per_100g, carbs_per_100g, calories_per_100g, note, source_page) VALUES ('03087', 'Чизкейк.', (SELECT id FROM organizations WHERE name='Бранч'), '2022-01-07', 'Cake&Coffee', 1.000, '(от ии) Печенье савоярди (200 г) выложить на дно формы. Сливки 33% (200 г) взбить миксером с Сахарная пудра (30 г) до устойчивых пиков (не перебить!). Выложить половину сливок на печенье. Слой печенья. Вторая половина сливок. Верх украсить тертым шоколадом/какао. Охладить в холодильнике минимум 4 часа (лучше на ночь). Нарезать порции. Подавать при 8-12 °C.', 'ai', 'Сыр творожный креметта', 1.0029, 0, 0, 0, 0, 'технологическая карта составлена на основании акта проработки. По физико-химическим показателям соответствует требованиям ГОСТ РФ 50763-2007 "Кулинарная продукция, реализуемая населению". По микробиологическим показателям соответствует требованиям СанПиН 2.3.2 1078-01', 324);
INSERT INTO tech_cards (card_number, dish_name, organization_id, approval_date, application_area, portion_norm, technology, technology_source, serving_requirements, total_output_kg, proteins_per_100g, fats_per_100g, carbs_per_100g, calories_per_100g, note, source_page) VALUES ('03055', 'Голубика', (SELECT id FROM organizations WHERE name='Бранч'), '2021-12-28', 'Cake&Coffee', 1.000, '(от ии) Голубика свежая (10 г) — промыть, обсушить. Выложить на десерт. Подавать при 5-10 °C.', 'ai', NULL, 0.05, 0, 0, 0, 0, 'технологическая карта составлена на основании акта проработки. По физико-химическим показателям соответствует требованиям ГОСТ РФ 50763-2007 "Кулинарная продукция, реализуемая населению". По микробиологическим показателям соответствует требованиям СанПиН 2.3.2 1078-01', 325);
INSERT INTO tech_cards (card_number, dish_name, organization_id, approval_date, application_area, portion_norm, technology, technology_source, serving_requirements, total_output_kg, proteins_per_100g, fats_per_100g, carbs_per_100g, calories_per_100g, note, source_page) VALUES ('03382', 'Ежевика 50 гр', (SELECT id FROM organizations WHERE name='Бранч'), '2023-02-02', 'Cake&Coffee', 1.000, '(от ии) Ежевика свежая (50 г) — промыть, обсушить. Выложить в креманку. Подавать при 5-10 °C.', 'ai', NULL, 0.05, 0, 0, 0, 0, 'технологическая карта составлена на основании акта проработки. По физико-химическим показателям соответствует требованиям ГОСТ РФ 50763-2007 "Кулинарная продукция, реализуемая населению". По микробиологическим показателям соответствует требованиям СанПиН 2.3.2 1078-01', 326);
INSERT INTO tech_cards (card_number, dish_name, organization_id, approval_date, application_area, portion_norm, technology, technology_source, serving_requirements, total_output_kg, proteins_per_100g, fats_per_100g, carbs_per_100g, calories_per_100g, note, source_page) VALUES ('03054', 'Клубника', (SELECT id FROM organizations WHERE name='Бранч'), '2021-12-28', 'Cake&Coffee', 1.000, '(от ии) Клубника свежая (50 г) — промыть, обсушить, удалить плодоножки. Нарезать при необходимости. Подавать при 5-10 °C.', 'ai', NULL, 0.05, 0, 0, 0, 0, 'технологическая карта составлена на основании акта проработки. По физико-химическим показателям соответствует требованиям ГОСТ РФ 50763-2007 "Кулинарная продукция, реализуемая населению". По микробиологическим показателям соответствует требованиям СанПиН 2.3.2 1078-01', 327);
INSERT INTO tech_cards (card_number, dish_name, organization_id, approval_date, application_area, portion_norm, technology, technology_source, serving_requirements, total_output_kg, proteins_per_100g, fats_per_100g, carbs_per_100g, calories_per_100g, note, source_page) VALUES ('03056', 'Малина', (SELECT id FROM organizations WHERE name='Бранч'), '2021-12-28', 'Cake&Coffee', 1.000, '(от ии) Малина свежая (50 г) — промыть аккуратно (ягоды хрупкие). Подавать при 5-10 °C.', 'ai', NULL, 0.1, 0, 0, 0, 0, 'технологическая карта составлена на основании акта проработки. По физико-химическим показателям соответствует требованиям ГОСТ РФ 50763-2007 "Кулинарная продукция, реализуемая населению". По микробиологическим показателям соответствует требованиям СанПиН 2.3.2 1078-01', 328);
INSERT INTO tech_cards (card_number, dish_name, organization_id, approval_date, application_area, portion_norm, technology, technology_source, serving_requirements, total_output_kg, proteins_per_100g, fats_per_100g, carbs_per_100g, calories_per_100g, note, source_page) VALUES ('03067', 'Корекс Большой', (SELECT id FROM organizations WHERE name='Бранч'), '2021-12-28', 'Cake&Coffee', 1.000, '(от ии) Десерт Корекс (полуфабрикат) — разморозить при комнатной температуре 10-15 минут. Подавать при 8-12 °C.', 'ai', 'контейнеры т-312 И РЕАЛИЗАЦИИ крышка', 1.0, 0, 0, 0, 0, 'технологическая карта составлена на основании акта проработки. По физико-химическим показателям соответствует требованиям ГОСТ РФ 50763-2007 "Кулинарная продукция, реализуемая населению". По микробиологическим показателям соответствует требованиям СанПиН 2.3.2 1078-01', 329);
INSERT INTO tech_cards (card_number, dish_name, organization_id, approval_date, application_area, portion_norm, technology, technology_source, serving_requirements, total_output_kg, proteins_per_100g, fats_per_100g, carbs_per_100g, calories_per_100g, note, source_page) VALUES ('03066', 'Корекс Маленький', (SELECT id FROM organizations WHERE name='Бранч'), '2021-12-28', 'Cake&Coffee', 1.000, '(от ии) Десерт Корекс (полуфабрикат) — разморозить при комнатной температуре 10-15 минут. Подавать при 8-12 °C.', 'ai', 'контейнеры т-310 И РЕАЛИЗАЦИИ крышка', 1.0, 0, 0, 0, 0, 'технологическая карта составлена на основании акта проработки. По физико-химическим показателям соответствует требованиям ГОСТ РФ 50763-2007 "Кулинарная продукция, реализуемая населению". По микробиологическим показателям соответствует требованиям СанПиН 2.3.2 1078-01', 330);
INSERT INTO tech_cards (card_number, dish_name, organization_id, approval_date, application_area, portion_norm, technology, technology_source, serving_requirements, total_output_kg, proteins_per_100g, fats_per_100g, carbs_per_100g, calories_per_100g, note, source_page) VALUES ('03428', 'Блинчики с бананом и карамелью', (SELECT id FROM organizations WHERE name='Бранч'), '2023-02-15', 'Cake&Coffee', 1.000, 'банан разрезать вдоль, посыпать сахарной образования карамельной корочки на топленым сливочным маслом.', 'original', 'банан выложить на тарелку, рядом стопку блинчиков, полить карамелью, на банан ряблм с блинами отсадить взбитую сметану, посыпать взрывной карамелью.', 0.329, 0, 0, 0, 0, 'технологическая карта составлена на основании акта проработки. По физико-химическим показателям соответствует требованиям ГОСТ РФ 50763-2007 "Кулинарная продукция, реализуемая населению". По микробиологическим показателям соответствует требованиям СанПиН 2.3.2 1078-01', 331);
INSERT INTO tech_cards (card_number, dish_name, organization_id, approval_date, application_area, portion_norm, technology, technology_source, serving_requirements, total_output_kg, proteins_per_100g, fats_per_100g, carbs_per_100g, calories_per_100g, note, source_page) VALUES ('03426', 'Блинчики с икрой', (SELECT id FROM organizations WHERE name='Бранч'), '2023-02-15', 'Cake&Coffee', 1.000, 'прогреть блинчики.', 'original', 'выложить 2 блинчика на тарелку стопкой, положить кусочек сливочного масла, аккуратно выложить сверху на блины кнелю', 0.13, 0, 0, 0, 0, 'технологическая карта составлена на основании акта проработки. По физико-химическим показателям соответствует требованиям ГОСТ РФ 50763-2007 "Кулинарная продукция, реализуемая населению". По микробиологическим показателям соответствует требованиям СанПиН 2.3.2 1078-01', 332);
INSERT INTO tech_cards (card_number, dish_name, organization_id, approval_date, application_area, portion_norm, technology, technology_source, serving_requirements, total_output_kg, proteins_per_100g, fats_per_100g, carbs_per_100g, calories_per_100g, note, source_page) VALUES ('03427', 'Блинчики с лососем', (SELECT id FROM organizations WHERE name='Бранч'), '2023-02-15', 'Cake&Coffee', 1.000, 'сметану соединить с креметтой и зеленью,', 'original', 'блинчики выложить стопкой, рядом отсадить соус из корнета, выложить лосось Сыр творожный сбрызнуть зеленым маслом. креметта', 0.17, 0, 0, 0, 0, 'технологическая карта составлена на основании акта проработки. По физико-химическим показателям соответствует требованиям ГОСТ РФ 50763-2007 "Кулинарная продукция, реализуемая населению". По микробиологическим показателям соответствует требованиям СанПиН 2.3.2 1078-01', 333);
INSERT INTO tech_cards (card_number, dish_name, organization_id, approval_date, application_area, portion_norm, technology, technology_source, serving_requirements, total_output_kg, proteins_per_100g, fats_per_100g, carbs_per_100g, calories_per_100g, note, source_page) VALUES ('03425', 'Медовые блинчики', (SELECT id FROM organizations WHERE name='Бранч'), '2023-02-15', 'Cake&Coffee', 1.000, 'масло сливочное растопить с медом на блинчика промазать медовомаслянной', 'original', 'три блинчика выложить друг на друга стопкой, рядом аккуратно выложить ложку сметаны, сметану посыпать сублимированной клубникой, на блинчики клубнику.', 0.207, 0, 0, 0, 0, 'технологическая карта составлена на основании акта проработки. По физико-химическим показателям соответствует требованиям ГОСТ РФ 50763-2007 "Кулинарная продукция, реализуемая населению". По микробиологическим показателям соответствует требованиям СанПиН 2.3.2 1078-01', 334);
INSERT INTO tech_cards (card_number, dish_name, organization_id, approval_date, application_area, portion_norm, technology, technology_source, serving_requirements, total_output_kg, proteins_per_100g, fats_per_100g, carbs_per_100g, calories_per_100g, note, source_page) VALUES ('03018', 'Запеченый лосось', (SELECT id FROM organizations WHERE name='Бранч'), '2021-12-24', 'Cake&Coffee', 1.000, '(от ии) Семга филе (150 г) промокнуть бумажным полотенцем. Соль пищевая, Перец молотый по вкусу. Цукини (30 г) и Баклажан (20 г) нарезать кружочками 0,5 см. Томаты (30 г) — дольками. Масло оливковое (5 мл) смешать с Мед (5 г) и Соевый соус (5 мл) — глазурь. Противень застелить пергаментом. Выложить овощи, сбрызнуть маслом, Соль, Перец. Семгу выложить на овощи, полить глазурью. Запекать в духовке при 190-200 °C 12-15 минут (до внутренней температуры 52-55 °C — medium). При подаче выложить на тарелку с овощами. Украсить Микрозелень. Температура подачи 55-60 °C.', 'ai', NULL, 1.5148, 0, 0, 0, 0, 'технологическая карта составлена на основании акта проработки. По физико-химическим показателям соответствует требованиям ГОСТ РФ 50763-2007 "Кулинарная продукция, реализуемая населению". По микробиологическим показателям соответствует требованиям СанПиН 2.3.2 1078-01', 335);
INSERT INTO tech_cards (card_number, dish_name, organization_id, approval_date, application_area, portion_norm, technology, technology_source, serving_requirements, total_output_kg, proteins_per_100g, fats_per_100g, carbs_per_100g, calories_per_100g, note, source_page) VALUES ('03318', 'Имбирный пряник новый', (SELECT id FROM organizations WHERE name='Бранч'), '2022-12-13', 'Cake&Coffee', 1.000, '(от ии) Имбирное тесто (готовое, 60 г) — раскатать до толщины 5-7 мм. Вырезать фигурки формочками. Выложить на пергамент. Выпекать при 170-180 °C 8-12 минут до твердости (зависит от размера). Остудить. Айсинг новый (готовая глазурь) — нанести узоры с помощью кондитерского мешка с тонкой насадкой. Дать глазури высохнуть 1-2 часа при комнатной температуре. Подавать при 18-22 °C.', 'ai', NULL, 0.07, 0, 0, 0, 0, 'технологическая карта составлена на основании акта проработки. По физико-химическим показателям соответствует требованиям ГОСТ РФ 50763-2007 "Кулинарная продукция, реализуемая населению". По микробиологическим показателям соответствует требованиям СанПиН 2.3.2 1078-01', 336);
INSERT INTO tech_cards (card_number, dish_name, organization_id, approval_date, application_area, portion_norm, technology, technology_source, serving_requirements, total_output_kg, proteins_per_100g, fats_per_100g, carbs_per_100g, calories_per_100g, note, source_page) VALUES ('02395', 'Оливье Новый Год', (SELECT id FROM organizations WHERE name='Бранч'), '2021-12-22', 'Cake&Coffee', 1.000, '(от ии) Картофель (80 г), Морковь (30 г) — отварить в мундире до готовности (20-25 мин при 95-98 °C), охладить, очистить, нарезать кубиком 0,5 см. Яйцо куриное (1 шт.) — сварить вкрутую (10 мин), нарезать кубиком. Горошек заморозка (20 г) — разморозить. Лук репчатый (10 г) — мелкий кубик. Колбаса/ветчина (40 г) — нарезать кубиком. Огурец соленый (20 г) — кубик 0,5 см, отжать лишнюю жидкость. Смешать все ингредиенты. Заправить Домашний майонез (40 г). Соль, Перец. Выложить на тарелку горкой. Украсить зеленью. Подавать при 5-10 °C, охладив.', 'ai', 'Огурцы маринованные', 0.6, 0, 0, 0, 0, 'технологическая карта составлена на основании акта проработки. По физико-химическим показателям соответствует требованиям ГОСТ РФ 50763-2007 "Кулинарная продукция, реализуемая населению". По микробиологическим показателям соответствует требованиям СанПиН 2.3.2 1078-01', 337);
INSERT INTO tech_cards (card_number, dish_name, organization_id, approval_date, application_area, portion_norm, technology, technology_source, serving_requirements, total_output_kg, proteins_per_100g, fats_per_100g, carbs_per_100g, calories_per_100g, note, source_page) VALUES ('03020', 'Плов Новый Год с говядиной', (SELECT id FROM organizations WHERE name='Бранч'), '2021-12-24', 'Cake&Coffee', 1.000, '(от ии) Говядина внутренняя (100 г) нарезать кубиком 3-4 см. Соль, Перец, Зира (3 г), Куркума (2 г). Казан/глубокую сковороду раскалить с Масло подсолнечное (15 мл) при 200-220 °C. Обжарить мясо 4-5 минут до корочки со всех сторон. Выложить на тарелку. В том же масле обжарить Лук репчатый (30 г, полукольца) 3-4 минуты до золотистого цвета. Добавить Морковь очищеная (40 г, соломка), обжарить 3-4 минуты. Чеснок (5 г, целые зубчики), Барбарис (2 г). Вернуть мясо. Залить водой (200 мл), добавить Соль. Довести до кипения, убавить огонь. Тушить 40 минут при 95-98 °C. Рис Арборио (80 г) промыть до прозрачной воды. Выложить ровным слоем на мясо. Втыкнуть чеснок (головку, нечищеную) в рис. Залить водой на 1 см выше риса. Накрыть крышкой, варить на минимальном огне 20-25 минут до впитывания воды. Выключить огонь, перемешать, накрыть крышкой на 10 минут. Подавать на блюде, украсить зернами граната и зеленью. Температура подачи 65-70 °C.', 'ai', 'вырезка', 2.2348, 0, 0, 0, 0, 'технологическая карта составлена на основании акта проработки. По физико-химическим показателям соответствует требованиям ГОСТ РФ 50763-2007 "Кулинарная продукция, реализуемая населению". По микробиологическим показателям соответствует требованиям СанПиН 2.3.2 1078-01', 338);
INSERT INTO tech_cards (card_number, dish_name, organization_id, approval_date, application_area, portion_norm, technology, technology_source, serving_requirements, total_output_kg, proteins_per_100g, fats_per_100g, carbs_per_100g, calories_per_100g, note, source_page) VALUES ('03317', 'Пряничный домик', (SELECT id FROM organizations WHERE name='Бранч'), '2022-12-13', 'Cake&Coffee', 1.000, '(от ии) Пряничный домик: Имбирное тесто (200 г) раскатать до 4-5 мм. Вырезать детали домика (стены, крыша) по шаблону. Выпекать при 170-180 °C 10-15 минут. Остудить полностью (детали должны быть твердыми). Айсинг новый (глазурь) — использовать как ''клей'' для сборки домика. Склеить стены и крышу. Украсить айсингом — окна, дверь, снежный узор на крыше. Дать высохнуть 2-3 часа. Корекс Маленький — установить домик на подложку. Украсить вокруг Краситель пищевой (сахарный снег). Подавать как декоративный десерт при 18-22 °C.', 'ai', 'Посыпка кондитерская', 1.741, 0, 0, 0, 0, 'технологическая карта составлена на основании акта проработки. По физико-химическим показателям соответствует требованиям ГОСТ РФ 50763-2007 "Кулинарная продукция, реализуемая населению". По микробиологическим показателям соответствует требованиям СанПиН 2.3.2 1078-01', 339);
INSERT INTO tech_cards (card_number, dish_name, organization_id, approval_date, application_area, portion_norm, technology, technology_source, serving_requirements, total_output_kg, proteins_per_100g, fats_per_100g, carbs_per_100g, calories_per_100g, note, source_page) VALUES ('03021', 'Ростбиф Новый год', (SELECT id FROM organizations WHERE name='Бранч'), '2021-12-24', 'Cake&Coffee', 1.000, '(от ии) Мясо (говядина, вырезка/строганов, 500 г) промокнуть, обвязать кулинарной нитью для формы. Смешать Масло оливковое (20 мл) с Паприка копченая (3 г), Сахар-песок (5 г), Соль (5 г), измельченным Чеснок (5 г) и Розмарин свежий (3 г). Натереть мясо маринадом со всех сторон. Оставить при комнатной температуре 30 минут. Духовку разогреть до 230 °C. Сковороду (чугунную) раскалить на сильном огне до 230 °C с маслом (10 мл). Обжарить мясо со всех сторон до корочки, по 1,5-2 минуты на сторону (всего 6-8 минут). Переложить в духовку на решетку (под решетку — противень с водой). Запекать при 200 °C: для medium (внутри 55-57 °C) — примерно 25-30 минут. Проверять термощупом. Достать мясо, накрыть фольгой, дать отдохнуть 15-20 минут (температура внутри поднимется еще на 3-5 °C). Нарезать ломтиками толщиной 1,5 см. Подавать с соусом из противня и гарниром. Температура подачи 50-55 °C.', 'ai', 'Бальзамический Картофель очищеный', 1.873, 0, 0, 0, 0, 'технологическая карта составлена на основании акта проработки. По физико-химическим показателям соответствует требованиям ГОСТ РФ 50763-2007 "Кулинарная продукция, реализуемая населению". По микробиологическим показателям соответствует требованиям СанПиН 2.3.2 1078-01', 340);
INSERT INTO tech_cards (card_number, dish_name, organization_id, approval_date, application_area, portion_norm, technology, technology_source, serving_requirements, total_output_kg, proteins_per_100g, fats_per_100g, carbs_per_100g, calories_per_100g, note, source_page) VALUES ('02662', 'Сельдь под шубой', (SELECT id FROM organizations WHERE name='Бранч'), '2021-12-22', 'Cake&Coffee', 1.000, '(от ии) Картофель отварной (80 г), Морковь (30 г), Свекла запеченая (40 г) — нарезать мелким кубиком (0,5 см). Лук репчатый (15 г) — мелкий кубик. Сельдь (60 г) — филе без костей, нарезать кубиком 0,5 см. Яйцо куриное (1 шт.) — сварить вкрутую (10 мин в кипятке), нарезать кубиком. Смешать все ингредиенты. Заправить Домашний майонез (30 г) и Сметана 30% (15 г). Соль, Перец по вкусу. Выложить горкой на тарелку. Сверху — майонезная сетка. Украсить зеленью. Подавать при 5-10 °C (предварительно охладив 30 мин в холодильнике).', 'ai', NULL, 0.6162, 0, 0, 0, 0, 'технологическая карта составлена на основании акта проработки. По физико-химическим показателям соответствует требованиям ГОСТ РФ 50763-2007 "Кулинарная продукция, реализуемая населению". По микробиологическим показателям соответствует требованиям СанПиН 2.3.2 1078-01', 341);
INSERT INTO tech_cards (card_number, dish_name, organization_id, approval_date, application_area, portion_norm, technology, technology_source, serving_requirements, total_output_kg, proteins_per_100g, fats_per_100g, carbs_per_100g, calories_per_100g, note, source_page) VALUES ('03315', 'Утка по пекински', (SELECT id FROM organizations WHERE name='Бранч'), '2022-12-13', 'Cake&Coffee', 1.000, '(от ии) Готовую утку (охлажденную/замороженную) разогреть. Для замороженной — разморозить в холодильнике 12-24 часа. Разогреть духовку с вентилятором до 200 °C. Утку выложить на решетку (под — противень с водой). Запекать 25-35 минут до хрустящей кожи, поливая соус Хойсин каждые 10 минут. Огурец (30 г) нарезать тонкой соломкой (julienne). Лук порей (20 г) — тонкими кольцами. Утку нарезать тонкими ломтиками. Подавать с блинчиками (пресными лепешками), огурцом, луком-пореем и соусом Хойсин. Гость собирает блинчик: блин + соус + утка + огурец + лук. Температура подачи 55-65 °C.', 'ai', NULL, 1.15, 0, 0, 0, 0, 'технологическая карта составлена на основании акта проработки. По физико-химическим показателям соответствует требованиям ГОСТ РФ 50763-2007 "Кулинарная продукция, реализуемая населению". По микробиологическим показателям соответствует требованиям СанПиН 2.3.2 1078-01', 342);
INSERT INTO tech_cards (card_number, dish_name, organization_id, approval_date, application_area, portion_norm, technology, technology_source, serving_requirements, total_output_kg, proteins_per_100g, fats_per_100g, carbs_per_100g, calories_per_100g, note, source_page) VALUES ('03019', 'Цыпленок запеченый целиком с апельсинами и картофелем "айдахо"', (SELECT id FROM organizations WHERE name='Бранч'), '2021-12-24', 'Cake&Coffee', 1.000, '(от ии) Филе грудки куриная (300 г, или целая курица 1-1,2 кг) промыть, обсушить. Маринад: Соевый соус (30 мл), Мед (20 г), Чеснок (10 г, измельченный), Имбирь корень (5 г, натертый), Горчица Дижонская (10 г), Масло оливковое (20 мл), Соль (5 г), Перец. Смешать. Курицу натереть маринадом, мариновать минимум 2 часа (лучше на ночь) в холодильнике. Апельсин (1 шт.) разрезать на дольки. Картофель (200 г) — крупно нарезать. Противень застелить пергаментом. Выложить картофель и апельсин, сбрызнуть маслом. Курицу выложить поверх овощей. Сверху — веточки Розмарин и Тимьян. Духовку разогреть до 200 °C. Запекать: для филе — 25-30 минут (до внутренней температуры 74 °C); для целой курицы — 1 час 15 минут (до 74 °C в толстой части бедра). Дать отдохнуть 10 минут. Нарезать, подать с овощами и соком из противня. Температура подачи 60-65 °C.', 'ai', 'Картофель очищеный', 2.9528, 0, 0, 0, 0, 'технологическая карта составлена на основании акта проработки. По физико-химическим показателям соответствует требованиям ГОСТ РФ 50763-2007 "Кулинарная продукция, реализуемая населению". По микробиологическим показателям соответствует требованиям СанПиН 2.3.2 1078-01', 343);
INSERT INTO tech_cards (card_number, dish_name, organization_id, approval_date, application_area, portion_norm, technology, technology_source, serving_requirements, total_output_kg, proteins_per_100g, fats_per_100g, carbs_per_100g, calories_per_100g, note, source_page) VALUES ('03022', 'Щеки Новый год', (SELECT id FROM organizations WHERE name='Бранч'), '2021-12-24', 'Cake&Coffee', 1.000, '(от ии) Телячьи щеки (150 г) промыть, обсушить. Соль, Перец. Сковороду раскалить до 200 °C. Масло подсолнечное (5 мл). Обжарить щеки со всех сторон до корочки, 3-4 минуты. Выложить. В той же сковороде: Лук репчатый (30 г), Морковь очищеная (20 г), Сельдерей стебель (15 г) — нарезать крупно. Обжарить 3-4 минуты при 170 °C. Добавить Чеснок (5 г), Томатная паста (10 г). Обжарить 1 минуту. Добавить Вино красное (50 мл), выпарить наполовину. Добавить Бульон говяжий (150 мл), Томатный соус (20 г), Травы прованские. Вернуть щеки. Довести до кипения. Накрыть крышкой и поставить в духовку при 150-160 °C на 2,5-3 часа до мягкости (вилка должна входить без сопротивления). Достать щеки. Соус процедить, уварить до загустения на среднем огне. Пюре картофельное (150 г) подогреть. Выложить пюре на тарелку, сверху — щеки, полить соусом. Украсить Микрозелень. Температура подачи 60-65 °C.', 'ai', NULL, 2.638, 0, 0, 0, 0, 'технологическая карта составлена на основании акта проработки. По физико-химическим показателям соответствует требованиям ГОСТ РФ 50763-2007 "Кулинарная продукция, реализуемая населению". По микробиологическим показателям соответствует требованиям СанПиН 2.3.2 1078-01', 344);
INSERT INTO tech_cards (card_number, dish_name, organization_id, approval_date, application_area, portion_norm, technology, technology_source, serving_requirements, total_output_kg, proteins_per_100g, fats_per_100g, carbs_per_100g, calories_per_100g, note, source_page) VALUES ('03211', 'Баклажан запеченый с опалеными томатами', (SELECT id FROM organizations WHERE name='Бранч'), '2022-09-23', 'Cake&Coffee', 1.000, 'Баклажан разрезать пополам, сделать посолить, поперчить, сбрысзнуть маслом, Черри слегка запечь. Заготовки хранить в', 'original', 'В центр плоской большой тарелки баклажан, на баклажан выложить черри. базиликом, соль, перец, зеленое масло.', 0.241, 0, 0, 0, 0, 'технологическая карта составлена на основании акта проработки. По физико-химическим показателям соответствует требованиям ГОСТ РФ 50763-2007 "Кулинарная продукция, реализуемая населению". По микробиологическим показателям соответствует требованиям СанПиН 2.3.2 1078-01', 345);
INSERT INTO tech_cards (card_number, dish_name, organization_id, approval_date, application_area, portion_norm, technology, technology_source, serving_requirements, total_output_kg, proteins_per_100g, fats_per_100g, carbs_per_100g, calories_per_100g, note, source_page) VALUES ('03213', 'Батат печеный с соусом чимичурри', (SELECT id FROM organizations WHERE name='Бранч'), '2022-09-23', 'Cake&Coffee', 1.000, 'Батат помыть с губкой, не чистить. Разрезать пополам, сбрызнуть маслом, послоить. Запечь на пергаменте до Заготовку хранить в холодильнике.', 'original', 'Прогреть черри и батат в парике. На большую плоскую тарелку выложить батат по центру рядом положить ложку сметаны, на батат выложить три ложки чимичурри. украсит опаленными черри и микрозеленью. соль, перец.', 0.3013, 0, 0, 0, 0, 'технологическая карта составлена на основании акта проработки. По физико-химическим показателям соответствует требованиям ГОСТ РФ 50763-2007 "Кулинарная продукция, реализуемая населению". По микробиологическим показателям соответствует требованиям СанПиН 2.3.2 1078-01', 346);
INSERT INTO tech_cards (card_number, dish_name, organization_id, approval_date, application_area, portion_norm, technology, technology_source, serving_requirements, total_output_kg, proteins_per_100g, fats_per_100g, carbs_per_100g, calories_per_100g, note, source_page) VALUES ('03225', 'Латте "Халва"', (SELECT id FROM organizations WHERE name='Бранч'), '2022-09-27', 'Cake&Coffee', 1.000, '(от ии) В кофемашине прогреть портafiльтр (15-20 секунд). Отмерить Эспрессо кейк/кук 18-20 г в холдер, утрамбовать тампером давлением ~15 кг. Экстракция при 9 бар, температура воды 90-94 °C, время экстракции 25-30 секунд. Объем одной порции эспрессо ~30 мл. Молоко 3,2% взбить капучинатором (паровой стержень) до температуры 65 °C, микропена — однородная глянцевая текстура без крупных пузырей. Взбивать погружая сопло на 1 см ниже поверхности молока до появления микропены, затем опустить глубже для нагрева.Халва (15-20 г) раскрошить в чашку. Налить эспрессо (30 мл), размешать до растворения халвы. Добавить Сахарный сироп (10 мл). Влить взбитое молоко, перемешать. Температура подачи 60-65 °C.', 'ai', 'Латте Халва. Только 340 мл Аналогично, как Арахисовое. Только вместо пасты - халва.', 0.385, 0, 0, 0, 0, 'технологическая карта составлена на основании акта проработки. По физико-химическим показателям соответствует требованиям ГОСТ РФ 50763-2007 "Кулинарная продукция, реализуемая населению". По микробиологическим показателям соответствует требованиям СанПиН 2.3.2 1078-01', 347);
INSERT INTO tech_cards (card_number, dish_name, organization_id, approval_date, application_area, portion_norm, technology, technology_source, serving_requirements, total_output_kg, proteins_per_100g, fats_per_100g, carbs_per_100g, calories_per_100g, note, source_page) VALUES ('03221', 'Сырники с облепиховой сгущенкой', (SELECT id FROM organizations WHERE name='Бранч'), '2022-09-23', 'Cake&Coffee', 1.000, 'Обжарить три сырника.', 'original', 'сгущенка Сырники выложить на большую плоскую тарелку в линию, посыпать пудрой и слегка общечь горелкой, для придания карамельной корочки, рядом с сырниками отсадить сметану из кремера, полить вокруг', 0.27, 0, 0, 0, 0, 'технологическая карта составлена на основании акта проработки. По физико-химическим показателям соответствует требованиям ГОСТ РФ 50763-2007 "Кулинарная продукция, реализуемая населению". По микробиологическим показателям соответствует требованиям СанПиН 2.3.2 1078-01', 348);
INSERT INTO tech_cards (card_number, dish_name, organization_id, approval_date, application_area, portion_norm, technology, technology_source, serving_requirements, total_output_kg, proteins_per_100g, fats_per_100g, carbs_per_100g, calories_per_100g, note, source_page) VALUES ('03218', 'Телячьи щеки с птитимом', (SELECT id FROM organizations WHERE name='Бранч'), '2022-09-23', 'Cake&Coffee', 1.000, 'Шеки 80 грамм одним куском прогреть в смазав маслом. должен хорошо выпариться)', 'original', 'в центр большой плоской тарелки выложить щеку, украсить микрозеленью(мелкой) и', 0.184, 0, 0, 0, 0, 'технологическая карта составлена на основании акта проработки. По физико-химическим показателям соответствует требованиям ГОСТ РФ 50763-2007 "Кулинарная продукция, реализуемая населению". По микробиологическим показателям соответствует требованиям СанПиН 2.3.2 1078-01', 349);
INSERT INTO tech_cards (card_number, dish_name, organization_id, approval_date, application_area, portion_norm, technology, technology_source, serving_requirements, total_output_kg, proteins_per_100g, fats_per_100g, carbs_per_100g, calories_per_100g, note, source_page) VALUES ('03216', 'Томатный суп с чикенболами', (SELECT id FROM organizations WHERE name='Бранч'), '2022-09-23', 'Cake&Coffee', 1.000, 'Куриный фарш обжарить неровными томатного соуса и прогреть.', 'original', 'Вылить суп в тарелку, выложить кинзу, сбрызнуть зеленым маслом. Перец консерв. отдельно подать крутоны, сметану и Халапеньо халапеньо.', 0.39, 0, 0, 0, 0, 'технологическая карта составлена на основании акта проработки. По физико-химическим показателям соответствует требованиям ГОСТ РФ 50763-2007 "Кулинарная продукция, реализуемая населению". По микробиологическим показателям соответствует требованиям СанПиН 2.3.2 1078-01', 350);
INSERT INTO tech_cards (card_number, dish_name, organization_id, approval_date, application_area, portion_norm, technology, technology_source, serving_requirements, total_output_kg, proteins_per_100g, fats_per_100g, carbs_per_100g, calories_per_100g, note, source_page) VALUES ('03224', 'Чай "Яблоко с карамелью" 300', (SELECT id FROM organizations WHERE name='Бранч'), '2022-09-27', 'Cake&Coffee', 1.000, '(от ии) Заварочный чайник ополоснуть горячей водой. Положить Чай весовой. Добавить нарезанное дольками Яблоки и Цедра апельсина. Залить водой температурой 92-95 °C. Настаивать 5-7 минут. Добавить Сироп Herbarista (карамельный). Размешать. Процедить в подогретый стакан. Температура подачи 70-80 °C.', 'ai', 'Апельсин нарезать кружками и выдавиь сок,яблоко нарезать полукольцами. Добавиь сироп и чай. Добавить кипятка и вскипятить.', 0.1125, 0, 0, 0, 0, 'технологическая карта составлена на основании акта проработки. По физико-химическим показателям соответствует требованиям ГОСТ РФ 50763-2007 "Кулинарная продукция, реализуемая населению". По микробиологическим показателям соответствует требованиям СанПиН 2.3.2 1078-01', 351);
INSERT INTO tech_cards (card_number, dish_name, organization_id, approval_date, application_area, portion_norm, technology, technology_source, serving_requirements, total_output_kg, proteins_per_100g, fats_per_100g, carbs_per_100g, calories_per_100g, note, source_page) VALUES ('03223', 'Чай "Яблоко с карамелью" 600', (SELECT id FROM organizations WHERE name='Бранч'), '2022-09-27', 'Cake&Coffee', 1.000, '(от ии) Заварочный чайник ополоснуть горячей водой. Положить Чай весовой. Добавить нарезанное дольками Яблоки и Цедра апельсина. Залить водой температурой 92-95 °C. Настаивать 5-7 минут. Добавить Сироп Herbarista (карамельный). Размешать. Процедить в подогретый стакан. Температура подачи 70-80 °C.', 'ai', 'Апельсин нарезать кружками и выдавиь сок,яблоко нарезать полукольцами. Добавиь сироп и чай. Добавить кипятка и вскипятить.', 0.115, 0, 0, 0, 0, 'технологическая карта составлена на основании акта проработки. По физико-химическим показателям соответствует требованиям ГОСТ РФ 50763-2007 "Кулинарная продукция, реализуемая населению". По микробиологическим показателям соответствует требованиям СанПиН 2.3.2 1078-01', 352);
INSERT INTO tech_cards (card_number, dish_name, organization_id, approval_date, application_area, portion_norm, technology, technology_source, serving_requirements, total_output_kg, proteins_per_100g, fats_per_100g, carbs_per_100g, calories_per_100g, note, source_page) VALUES ('03215', 'Шакшука', (SELECT id FROM organizations WHERE name='Бранч'), '2022-09-23', 'Cake&Coffee', 1.000, 'Томатный соус и яйца пашот прогреть.', 'original', 'В белую глубокую тарелку аккуратно выложить соус, в центр 2 яйца. Украсить обильно кинзой, сбрызнуть зеленым Перец консерв. Халапеньо крутоны и халапеньо в соусничке.', 0.3, 0, 0, 0, 0, 'технологическая карта составлена на основании акта проработки. По физико-химическим показателям соответствует требованиям ГОСТ РФ 50763-2007 "Кулинарная продукция, реализуемая населению". По микробиологическим показателям соответствует требованиям СанПиН 2.3.2 1078-01', 353);
INSERT INTO tech_cards (card_number, dish_name, organization_id, approval_date, application_area, portion_norm, technology, technology_source, serving_requirements, total_output_kg, proteins_per_100g, fats_per_100g, carbs_per_100g, calories_per_100g, note, source_page) VALUES ('03445', 'Овсяная каша с медовой грушой', (SELECT id FROM organizations WHERE name='Бранч'), '2023-02-27', 'Cake&Coffee', 1.000, 'Овсяную кашу сварить на воде с солью и сердцевину, мед развести с небольшим в вакуумный покет и завакуумировать, кашу выложить в большую глубокую белую сахарной пудрой и обжечь горелкой до корочки, выложить в центр тарелки и посыпать кашу жареными лепестками', 'original', NULL, 0.442, 0, 0, 0, 0, 'технологическая карта составлена на основании акта проработки. По физико-химическим показателям соответствует требованиям ГОСТ РФ 50763-2007 "Кулинарная продукция, реализуемая населению". По микробиологическим показателям соответствует требованиям СанПиН 2.3.2 1078-01', 354);
INSERT INTO tech_cards (card_number, dish_name, organization_id, approval_date, application_area, portion_norm, technology, technology_source, serving_requirements, total_output_kg, proteins_per_100g, fats_per_100g, carbs_per_100g, calories_per_100g, note, source_page) VALUES ('03447', 'Печеные овощи с тофу сметаной', (SELECT id FROM organizations WHERE name='Бранч'), '2023-02-27', 'Cake&Coffee', 1.000, 'Томат запечь при 160 целиком, цукини нарезать длинными дольками, болгарский пере длинными треугольниками, шампиньон пополам, все овощи обжарить на масле с добавлением чеснока, тимьяна. выложить на большую плоскую белую тарелку, отсадить три капли тофу сметаны, сбрызнуть зеленым маслом.', 'original', NULL, 0.3383, 0, 0, 0, 0, 'технологическая карта составлена на основании акта проработки. По физико-химическим показателям соответствует требованиям ГОСТ РФ 50763-2007 "Кулинарная продукция, реализуемая населению". По микробиологическим показателям соответствует требованиям СанПиН 2.3.2 1078-01', 355);
INSERT INTO tech_cards (card_number, dish_name, organization_id, approval_date, application_area, portion_norm, technology, technology_source, serving_requirements, total_output_kg, proteins_per_100g, fats_per_100g, carbs_per_100g, calories_per_100g, note, source_page) VALUES ('03444', 'Печеный картофель с грибной икрой и тофу сметаной', (SELECT id FROM organizations WHERE name='Бранч'), '2023-02-27', 'Cake&Coffee', 1.000, 'Картофель помыть, запечь его в кожуре в фольге, грибы обжарить с луком, посолить, поперчить и пробить блендером до тарелки выложить грибную икру, и выложить сверху на икру, полить тофу сметаной, сбрызнуть зеленым маслом и посыпать МЕЛКО нарезанными ножками', 'original', NULL, 0.3623, 0, 0, 0, 0, 'технологическая карта составлена на основании акта проработки. По физико-химическим показателям соответствует требованиям ГОСТ РФ 50763-2007 "Кулинарная продукция, реализуемая населению". По микробиологическим показателям соответствует требованиям СанПиН 2.3.2 1078-01', 356);
INSERT INTO tech_cards (card_number, dish_name, organization_id, approval_date, application_area, portion_norm, technology, technology_source, serving_requirements, total_output_kg, proteins_per_100g, fats_per_100g, carbs_per_100g, calories_per_100g, note, source_page) VALUES ('03446', 'Соба с овощами и соусом хойсин', (SELECT id FROM organizations WHERE name='Бранч'), '2023-02-27', 'Cake&Coffee', 1.000, 'Собу отварить 3 минуты, овощи нарезать тонокой соломкой и слегка обжарить, добавить собу к овощам, добавить соус хойсин, прогреть. Выложить на большую глубокую белую тарелку и посыпать', 'original', NULL, 0.231, 0, 0, 0, 0, 'технологическая карта составлена на основании акта проработки. По физико-химическим показателям соответствует требованиям ГОСТ РФ 50763-2007 "Кулинарная продукция, реализуемая населению". По микробиологическим показателям соответствует требованиям СанПиН 2.3.2 1078-01', 357);
INSERT INTO tech_cards (card_number, dish_name, organization_id, approval_date, application_area, portion_norm, technology, technology_source, serving_requirements, total_output_kg, proteins_per_100g, fats_per_100g, carbs_per_100g, calories_per_100g, note, source_page) VALUES ('03017', 'Имбирный пряник', (SELECT id FROM organizations WHERE name='Бранч'), '2021-12-24', 'Cake&Coffee', 1.000, '(от ии) Имбирное тесто (готовое, 80-100 г) — раскатать, вырезать пряник (d=10-12 см). Выпекать при 170-180 °C 10-15 минут. Остудить. Помадка на (готовая) — нанести ровным слоем на пряник. Дать застыть 30 мин. Упаковать в Пакеты, закрепить липкая лента. Подавать при 18-22 °C.', 'ai', 'имбирный пряник', 0.0415, 0, 0, 0, 0, 'технологическая карта составлена на основании акта проработки. По физико-химическим показателям соответствует требованиям ГОСТ РФ 50763-2007 "Кулинарная продукция, реализуемая населению". По микробиологическим показателям соответствует требованиям СанПиН 2.3.2 1078-01', 358);
INSERT INTO tech_cards (card_number, dish_name, organization_id, approval_date, application_area, portion_norm, technology, technology_source, serving_requirements, total_output_kg, proteins_per_100g, fats_per_100g, carbs_per_100g, calories_per_100g, note, source_page) VALUES ('03025', 'Набор приборов', (SELECT id FROM organizations WHERE name='Бранч'), '2021-12-25', 'Cake&Coffee', 1.000, '(от ии) Набор приборов — положить в пакет: Ложки одноразовые (1 шт.), вилки одноразовые (1 шт.), Наклейки на стаканы (2 шт.). Выдать гостю.', 'ai', 'Мешки для фасовки Салфетки маленькие', 0.0, 0, 0, 0, 0, 'технологическая карта составлена на основании акта проработки. По физико-химическим показателям соответствует требованиям ГОСТ РФ 50763-2007 "Кулинарная продукция, реализуемая населению". По микробиологическим показателям соответствует требованиям СанПиН 2.3.2 1078-01', 359);
INSERT INTO tech_cards (card_number, dish_name, organization_id, approval_date, application_area, portion_norm, technology, technology_source, serving_requirements, total_output_kg, proteins_per_100g, fats_per_100g, carbs_per_100g, calories_per_100g, note, source_page) VALUES ('02934', 'Меренговый рулет порция', (SELECT id FROM organizations WHERE name='Бранч'), '2021-07-31', 'Cake&Coffee', 1.000, '(от ии) Меренговый Рулет (готовый) — нарезать порцию 2-3 см. Выложить на тарелку. Подавать при 8-12 °C.', 'ai', NULL, 0.1663, 0, 0, 0, 0, 'технологическая карта составлена на основании акта проработки. По физико-химическим показателям соответствует требованиям ГОСТ РФ 50763-2007 "Кулинарная продукция, реализуемая населению". По микробиологическим показателям соответствует требованиям СанПиН 2.3.2 1078-01', 360);
INSERT INTO tech_cards (card_number, dish_name, organization_id, approval_date, application_area, portion_norm, technology, technology_source, serving_requirements, total_output_kg, proteins_per_100g, fats_per_100g, carbs_per_100g, calories_per_100g, note, source_page) VALUES ('02992', 'Торт тирамису', (SELECT id FROM organizations WHERE name='Бранч'), '2021-11-03', 'Cake&Coffee', 1.000, '(от ии) Желток (3 шт.) взбить с Сахарная пудра (60 г) до белой массы (5-7 минут миксером). Добавить Маскарпоне (250 г), перемешать до однородности. Сливки 33% (150 г) взбить до устойчивых пиков. Аккуратно вмешать в маскарпонную массу. Эспрессо кейк (200 мл, остывший) смешать с Коньяк для кухни (15 мл). Печенье савоярди (200 г) быстро обмакнуть в кофейную смесь (1-2 секунды, не замачивать!). Выложить слой печенья на дно формы. Сверху — слой крема (1/3). Снова печенье. Снова крем. Верхний слой — крем. Какао-порошок просеять через сито сверху. Охладить в холодильнике минимум 6 часов (лучше ночь). Нарезать порции. Подавать при 8-12 °C.', 'ai', NULL, 1.8302, 0, 0, 0, 0, 'технологическая карта составлена на основании акта проработки. По физико-химическим показателям соответствует требованиям ГОСТ РФ 50763-2007 "Кулинарная продукция, реализуемая населению". По микробиологическим показателям соответствует требованиям СанПиН 2.3.2 1078-01', 361);
INSERT INTO tech_cards (card_number, dish_name, organization_id, approval_date, application_area, portion_norm, technology, technology_source, serving_requirements, total_output_kg, proteins_per_100g, fats_per_100g, carbs_per_100g, calories_per_100g, note, source_page) VALUES ('02990', 'Чизкейк мусс', (SELECT id FROM organizations WHERE name='Бранч'), '2021-11-02', 'Cake&Coffee', 1.000, '(от ии) Печенье савоярди (100 г) измельчить в крошку. Смешать с Масло сливочное (40 г, растопленным). Выложить на дно формы (d=16-18 см) с пергаментом, утрамбовать. Охладить 30 минут. Сливки 33% (300 г) взбить с Сахарная пудра (40 г) до устойчивых пиков. Сыр сливочный (филадельфия/маскарпоне, 250 г) взбить до мягкости. Аккуратно соединить со сливками. Выложить крем на основу. Разровнять. Охладить в холодильнике минимум 4 часа (лучше ночь). При подаче: нарезать на порции, полить Сироп Монин (10 мл), украсить Клубника свежая. Подавать при 8-12 °C.', 'ai', NULL, 0.1838, 0, 0, 0, 0, 'технологическая карта составлена на основании акта проработки. По физико-химическим показателям соответствует требованиям ГОСТ РФ 50763-2007 "Кулинарная продукция, реализуемая населению". По микробиологическим показателям соответствует требованиям СанПиН 2.3.2 1078-01', 362);
INSERT INTO tech_cards (card_number, dish_name, organization_id, approval_date, application_area, portion_norm, technology, technology_source, serving_requirements, total_output_kg, proteins_per_100g, fats_per_100g, carbs_per_100g, calories_per_100g, note, source_page) VALUES ('01607', 'Cut Cut Beef', (SELECT id FROM organizations WHERE name='Бранч'), '2021-07-30', 'Cake&Coffee', 1.000, '(от ии) Говяжья вырезка (150 г) нарезать брусочками 1х1х5 см. Соль пищевая, Перец молотый. Сковороду раскалить до 220 °C. Добавить Масло оливковое (10 мл). Обжарить мясо 2-3 минуты, помешивая, до сильной корочки (stir-fry). Тортилья (1 шт.) нарезать полосками, добавить к мясу, обжарить 1 минуту. Добавить Соус Чеддер (30 мл) и Соус барбекю (10 мл), перемешать. Выложить на тарелку. Сверху — Микрозелень. Подавать при 55-65 °C.', 'ai', NULL, 0.2015, 0, 0, 0, 0, 'технологическая карта составлена на основании акта проработки. По физико-химическим показателям соответствует требованиям ГОСТ РФ 50763-2007 "Кулинарная продукция, реализуемая населению". По микробиологическим показателям соответствует требованиям СанПиН 2.3.2 1078-01', 363);
INSERT INTO tech_cards (card_number, dish_name, organization_id, approval_date, application_area, portion_norm, technology, technology_source, serving_requirements, total_output_kg, proteins_per_100g, fats_per_100g, carbs_per_100g, calories_per_100g, note, source_page) VALUES ('01002', 'Лосось су-вид', (SELECT id FROM organizations WHERE name='Бранч'), '2021-07-29', 'Cake&Coffee', 1.000, '(от ии) Семга (120 г, филе без кожи) промокнуть. Соль пищевая и Перец молотый по вкусу. Вакуумировать с Масло подсолнечное (5 мл). Готовить су-вид при 48 °C в течение 30-35 минут (medium). Киноа (30 г) — промыть, залить водой 1:2, довести до кипения, варить 12-15 минут до мягкости. Гуакамоле (30 г) — готовый. Соус чуррос (10 мл) — подогреть. Семгу достать из пакета, обсушить. Обжарить на раскаленной сковороде (220 °C) по 30-40 секунд с каждой стороны для корочки. Выложить киноа на тарелку, рядом — семгу. Полить соусом чуррос, рядом — гуакамоле. Температура подачи 48-52 °C.', 'ai', 'Сыр творожный креметта', 0.1854, 0, 0, 0, 0, 'технологическая карта составлена на основании акта проработки. По физико-химическим показателям соответствует требованиям ГОСТ РФ 50763-2007 "Кулинарная продукция, реализуемая населению". По микробиологическим показателям соответствует требованиям СанПиН 2.3.2 1078-01', 364);
INSERT INTO tech_cards (card_number, dish_name, organization_id, approval_date, application_area, portion_norm, technology, technology_source, serving_requirements, total_output_kg, proteins_per_100g, fats_per_100g, carbs_per_100g, calories_per_100g, note, source_page) VALUES ('01691', 'Медальоны из вырезки с картофельным пюре', (SELECT id FROM organizations WHERE name='Бранч'), '2021-07-30', 'Cake&Coffee', 1.000, '(от ии) Мясо (вырезка говяжья, 150 г) нарезать медальонами толщиной 2,5-3 см. Соль пищевая, Перец молотый по вкусу. Сковороду (желательно чугунную) раскалить на сильном огне до 220-230 °C. Добавить масло (растительное, 10 мл). Выложить медальоны, обжарить 2-3 минуты с каждой стороны до образования корочки (searing). Убавить огонь до среднего (180 °C), добавить Масло сливочное (15 г), тимьян, чеснок. Поливать медальоны растопленным маслом ложкой (basting) 1-2 минуты. Для medium (внутри 55-58 °C): общее время жарки ~5-6 минут. Дать мясу отдохнуть 3-5 минут при комнатной температуре под фольгой. На тарелку выложить картофельное пюре (150 г), рядом — медальоны. Украсить Микрозелень. Подавать при 55-60 °C.', 'ai', 'Говядина внутренняя вырезка Горчично-медовая завправка', 0.242, 0, 0, 0, 0, 'технологическая карта составлена на основании акта проработки. По физико-химическим показателям соответствует требованиям ГОСТ РФ 50763-2007 "Кулинарная продукция, реализуемая населению". По микробиологическим показателям соответствует требованиям СанПиН 2.3.2 1078-01', 365);
INSERT INTO tech_cards (card_number, dish_name, organization_id, approval_date, application_area, portion_norm, technology, technology_source, serving_requirements, total_output_kg, proteins_per_100g, fats_per_100g, carbs_per_100g, calories_per_100g, note, source_page) VALUES ('02937', 'Салат с тунцом и авокадо', (SELECT id FROM organizations WHERE name='Бранч'), '2021-08-03', 'Cake&Coffee', 1000, '(от ии) Авокадо (1 шт.) разрезать пополам, удалить косточку, нарезать дольками, сбрызнуть соком лайма. Тунец консерв. (80 г) — слить жидкость, разломить на крупные куски. Огурец (30 г) нарезать полукольцами. Базилик (5 г) — свежие листья. Выложить на тарелку: рукколу, затем авокадо, тунец, огурец. Полить Масло оливковое (10 мл) и Лимонный сок (5 мл). Посыпать Кунжут (3 г). Украсить Базилик. Соль, Перец. Подавать при 5-10 °C.', 'ai', NULL, NULL, 0, 0, 0, 0, 'технологическая карта составлена на основании акта проработки. По физико-химическим показателям соответствует требованиям ГОСТ РФ 50763-2007 "Кулинарная продукция, реализуемая населению". По микробиологическим показателям соответствует требованиям СанПиН 2.3.2 1078-01', 366);
INSERT INTO tech_cards (card_number, dish_name, organization_id, approval_date, application_area, portion_norm, technology, technology_source, serving_requirements, total_output_kg, proteins_per_100g, fats_per_100g, carbs_per_100g, calories_per_100g, note, source_page) VALUES ('01240', 'Слабосоленый лосось с васаби', (SELECT id FROM organizations WHERE name='Бранч'), '2021-07-30', 'Cake&Coffee', 1.000, '(от ии) Семга слабо соленая (80 г) — нарезать тонкими ломтиками (sashimi-style, толщина 3-4 мм). Огурец (30 г) нарезать тонкими продольными пластинами (с помощью овощечистки). Лук красный (10 г) — тонкие полукольца. Салат Руккола (15 г) выложить на тарелку. Сверху — лосось (разложив ломтики веером). Рядом — огуречные ленты и Лук красный. Васаби (3 г) — подать отдельно в розетке. Сбрызнуть Масло оливковое (5 мл) и соевый соус (5 мл). Подавать при 5-10 °C.', 'ai', NULL, 0.139, 0, 0, 0, 0, 'технологическая карта составлена на основании акта проработки. По физико-химическим показателям соответствует требованиям ГОСТ РФ 50763-2007 "Кулинарная продукция, реализуемая населению". По микробиологическим показателям соответствует требованиям СанПиН 2.3.2 1078-01', 367);
INSERT INTO tech_cards (card_number, dish_name, organization_id, approval_date, application_area, portion_norm, technology, technology_source, serving_requirements, total_output_kg, proteins_per_100g, fats_per_100g, carbs_per_100g, calories_per_100g, note, source_page) VALUES ('03474', 'Кулич большой ВИТРИНА', (SELECT id FROM organizations WHERE name='Бранч'), '2023-04-14', 'Cake&Coffee', 1.000, '(от ии) Тесто на куличи (готовое, большой, витрина) — если замороженное, разморозить при комнатной температуре 2-3 часа. Выпекать при 170-180 °C 35-45 минут (малый) / 45-55 минут (средний) / 55-65 минут (большой) до золотистого цвета и сухой зубочистки. Если верх подрумянивается быстро — накрыть фольгой. Остудить в форме 15 мин, затем на решетке полностью. Итальянская меренга (белковая глазурь) — покрыть верх кулича и бока. Украсить Лепестки миндаля и Изюм (вдавить в глазурь до застывания). Дать глазури застыть 1-2 часа. Подавать при 18-22 °C.', 'ai', 'Глазурь Карамельная', 0.57, 0, 0, 0, 0, 'технологическая карта составлена на основании акта проработки. По физико-химическим показателям соответствует требованиям ГОСТ РФ 50763-2007 "Кулинарная продукция, реализуемая населению". По микробиологическим показателям соответствует требованиям СанПиН 2.3.2 1078-01', 368);
