INSERT INTO tech_cards (card_number, dish_name, organization_id, approval_date, application_area, portion_norm, technology, technology_source, serving_requirements, total_output_kg, proteins_per_100g, fats_per_100g, carbs_per_100g, calories_per_100g, note, source_page) VALUES ('03411', 'БАНАН ПЕРСОНАЛУ', (SELECT id FROM organizations WHERE name='Бранч'), '2023-02-10', 'Cake&Coffee', 1.000, '(от ии) Бананы (1-2 шт.) — вымыть, подать.', 'ai', NULL, 0.06, 0, 0, 0, 0, 'технологическая карта составлена на основании акта проработки. По физико-химическим показателям соответствует требованиям ГОСТ РФ 50763-2007 "Кулинарная продукция, реализуемая населению". По микробиологическим показателям соответствует требованиям СанПиН 2.3.2 1078-01', 374);
INSERT INTO tech_cards (card_number, dish_name, organization_id, approval_date, application_area, portion_norm, technology, technology_source, serving_requirements, total_output_kg, proteins_per_100g, fats_per_100g, carbs_per_100g, calories_per_100g, note, source_page) VALUES ('03412', 'ВАРЕНЬЕ ПЕРСОНАЛУ', (SELECT id FROM organizations WHERE name='Бранч'), '2023-02-10', 'Cake&Coffee', 1.000, '(от ии) Варенье малиновое (порция) — подать в розетке.', 'ai', NULL, 0.05, 0, 0, 0, 0, 'технологическая карта составлена на основании акта проработки. По физико-химическим показателям соответствует требованиям ГОСТ РФ 50763-2007 "Кулинарная продукция, реализуемая населению". По микробиологическим показателям соответствует требованиям СанПиН 2.3.2 1078-01', 375);
INSERT INTO tech_cards (card_number, dish_name, organization_id, approval_date, application_area, portion_norm, technology, technology_source, serving_requirements, total_output_kg, proteins_per_100g, fats_per_100g, carbs_per_100g, calories_per_100g, note, source_page) VALUES ('03405', 'ГЛАЗУНЬЯ/ПАШОТ ПЕРСОНАЛУ 2ШТ', (SELECT id FROM organizations WHERE name='Бранч'), '2023-02-10', 'Cake&Coffee', 1.000, '(от ии) Глазунья: Яйцо куриное (2 шт.) разбить на разогретую сковороду с Масло подсолнечное (5 г) при 150-160 °C. Жарить 2-3 минуты до белка, схватившегося, но жидкого желтка. Соль, Перец. Температура подачи 60-65 °C. Пашот — варить в кипятке с уксусом 3-3,5 мин при 90-95 °C.', 'ai', NULL, 0.0808, 0, 0, 0, 0, 'технологическая карта составлена на основании акта проработки. По физико-химическим показателям соответствует требованиям ГОСТ РФ 50763-2007 "Кулинарная продукция, реализуемая населению". По микробиологическим показателям соответствует требованиям СанПиН 2.3.2 1078-01', 376);
INSERT INTO tech_cards (card_number, dish_name, organization_id, approval_date, application_area, portion_norm, technology, technology_source, serving_requirements, total_output_kg, proteins_per_100g, fats_per_100g, carbs_per_100g, calories_per_100g, note, source_page) VALUES ('03407', 'КАША ОВСЯНАЯ ПЕРСОНАЛУ', (SELECT id FROM organizations WHERE name='Бранч'), '2023-02-10', 'Cake&Coffee', 1.000, '(от ии) Хлопья овсяные (60 г) засыпать в кипящее Молоко 3,2% (150 мл). Варить 5-7 минут при 90 °C, помешивая. Добавить Сахар-песок, Соль. Масло сливочное (10 г) в конце.', 'ai', NULL, 0.375, 0, 0, 0, 0, 'технологическая карта составлена на основании акта проработки. По физико-химическим показателям соответствует требованиям ГОСТ РФ 50763-2007 "Кулинарная продукция, реализуемая населению". По микробиологическим показателям соответствует требованиям СанПиН 2.3.2 1078-01', 377);
INSERT INTO tech_cards (card_number, dish_name, organization_id, approval_date, application_area, portion_norm, technology, technology_source, serving_requirements, total_output_kg, proteins_per_100g, fats_per_100g, carbs_per_100g, calories_per_100g, note, source_page) VALUES ('03406', 'ОМЛЕТ/СКРЕМБЛ ПЕРСОНАЛУ', (SELECT id FROM organizations WHERE name='Бранч'), '2023-02-10', 'Cake&Coffee', 1.000, '(от ии) Яйцо куриное (3 шт.) взбить со Сливки 22% (20 мл), Соль, Перец. Сковороду с Масло подсолнечное (5 г) разогреть до 160-170 °C. Вылить смесь, готовить 2-3 мин, помешивая лопаткой (скрембл) или не помешивая (омлет). Температура подачи 60-65 °C.', 'ai', NULL, 0.0813, 0, 0, 0, 0, 'технологическая карта составлена на основании акта проработки. По физико-химическим показателям соответствует требованиям ГОСТ РФ 50763-2007 "Кулинарная продукция, реализуемая населению". По микробиологическим показателям соответствует требованиям СанПиН 2.3.2 1078-01', 378);
INSERT INTO tech_cards (card_number, dish_name, organization_id, approval_date, application_area, portion_norm, technology, technology_source, serving_requirements, total_output_kg, proteins_per_100g, fats_per_100g, carbs_per_100g, calories_per_100g, note, source_page) VALUES ('03506', 'ПАНКЕЙКИ/ВАФЛИ ПЕРСОНАЛУ', (SELECT id FROM organizations WHERE name='Бранч'), '2023-04-30', 'Cake&Coffee', 1.000, '(от ии) Панкейки/Вафли (готовые) — подогреть в тостере/духовке при 180 °C 2-3 минуты. Подать с топпингом/сиропом.', 'ai', NULL, 0.1, 0, 0, 0, 0, 'технологическая карта составлена на основании акта проработки. По физико-химическим показателям соответствует требованиям ГОСТ РФ 50763-2007 "Кулинарная продукция, реализуемая населению". По микробиологическим показателям соответствует требованиям СанПиН 2.3.2 1078-01', 379);
INSERT INTO tech_cards (card_number, dish_name, organization_id, approval_date, application_area, portion_norm, technology, technology_source, serving_requirements, total_output_kg, proteins_per_100g, fats_per_100g, carbs_per_100g, calories_per_100g, note, source_page) VALUES ('03409', 'ПАСТА С БЕКОНОМ ПЕРСОНАЛУ', (SELECT id FROM organizations WHERE name='Бранч'), '2023-02-10', 'Cake&Coffee', 1.000, '(от ии) Спагетти (80 г) — отварить в кипящей подсоленной воде 8-10 мин до аль денте. Откинуть. Бекон нарезка (30 г) и Лук репчатый (20 г) обжарить на сковороде при 170 °C 3-4 мин. Добавить Сливки 22% (50 г), Соль, Перец, перемешать. Добавить спагетти, прогреть 1 мин. Температура подачи 60-65 °C.', 'ai', NULL, 0.1563, 0, 0, 0, 0, 'технологическая карта составлена на основании акта проработки. По физико-химическим показателям соответствует требованиям ГОСТ РФ 50763-2007 "Кулинарная продукция, реализуемая населению". По микробиологическим показателям соответствует требованиям СанПиН 2.3.2 1078-01', 380);
INSERT INTO tech_cards (card_number, dish_name, organization_id, approval_date, application_area, portion_norm, technology, technology_source, serving_requirements, total_output_kg, proteins_per_100g, fats_per_100g, carbs_per_100g, calories_per_100g, note, source_page) VALUES ('03408', 'ПАСТА С КУРИЦЕЙ ПЕРСОНАЛУ', (SELECT id FROM organizations WHERE name='Бранч'), '2023-02-10', 'Cake&Coffee', 1.000, '(от ии) Спагетти (80 г) — отварить 8-10 мин. Филе куриное су-вид (50 г) нарезать, разогреть. Лук репчатый (15 г) обжарить. Добавить Сливки 22% (50 г), Соль, Перец, Карри. Добавить спагетти и курицу, прогреть. Температура подачи 60-65 °C.', 'ai', NULL, 0.1563, 0, 0, 0, 0, 'технологическая карта составлена на основании акта проработки. По физико-химическим показателям соответствует требованиям ГОСТ РФ 50763-2007 "Кулинарная продукция, реализуемая населению". По микробиологическим показателям соответствует требованиям СанПиН 2.3.2 1078-01', 381);
