INSERT INTO tech_cards (card_number, dish_name, organization_id, approval_date, application_area, portion_norm, technology, technology_source, serving_requirements, total_output_kg, proteins_per_100g, fats_per_100g, carbs_per_100g, calories_per_100g, note, source_page) VALUES ('03329', 'Набор 2 пряника', (SELECT id FROM organizations WHERE name='Бранч'), '2022-12-21', 'Cake&Coffee', 1.000, '(от ии) Набор 2 пряника (готовые, упакованные) — выдать гостю. Подавать при 18-22 °C.', 'ai', 'упаковка для И РЕАЛИЗАЦИИ печенья бумажный наполнитель', 0.14, 0, 0, 0, 0, 'технологическая карта составлена на основании акта проработки. По физико-химическим показателям соответствует требованиям ГОСТ РФ 50763-2007 "Кулинарная продукция, реализуемая населению". По микробиологическим показателям соответствует требованиям СанПиН 2.3.2 1078-01', 421);
