INSERT INTO tech_cards (card_number, dish_name, organization_id, approval_date, application_area, portion_norm, technology, technology_source, serving_requirements, total_output_kg, proteins_per_100g, fats_per_100g, carbs_per_100g, calories_per_100g, note, source_page) VALUES ('03330', 'Набор Шоколадная бомбочка', (SELECT id FROM organizations WHERE name='Бранч'), '2022-12-21', 'Cake&Coffee', 3.000, '(от ии) Шоколадная бомбочка (готовая, упакованная) — выдать гостю. При подаче — залить горячим молоком (200 мл, 70-75 °C).', 'ai', 'Какао Красный И РЕАЛИЗАЦИИ октябрь Маршмелоу маленькие', 0.24, 0, 0, 0, 0, 'технологическая карта составлена на основании акта проработки. По физико-химическим показателям соответствует требованиям ГОСТ РФ 50763-2007 "Кулинарная продукция, реализуемая населению". По микробиологическим показателям соответствует требованиям СанПиН 2.3.2 1078-01', 423);
INSERT INTO tech_cards (card_number, dish_name, organization_id, approval_date, application_area, portion_norm, technology, technology_source, serving_requirements, total_output_kg, proteins_per_100g, fats_per_100g, carbs_per_100g, calories_per_100g, note, source_page) VALUES ('03424', 'овощи фрукты средний себес', (SELECT id FROM organizations WHERE name='Бранч'), '2023-02-13', 'Cake&Coffee', 1.000, '(от ии) овощи фрукты средний себес — ингредиенты для подготовки заготовок/полуфабрикатов. Подготовить согласно технологическим картам заготовок (ttk_zagotovki).', 'ai', NULL, 26.0, 0, 0, 0, 0, 'технологическая карта составлена на основании акта проработки. По физико-химическим показателям соответствует требованиям ГОСТ РФ 50763-2007 "Кулинарная продукция, реализуемая населению". По микробиологическим показателям соответствует требованиям СанПиН 2.3.2 1078-01', 424);
INSERT INTO tech_cards (card_number, dish_name, organization_id, approval_date, application_area, portion_norm, technology, technology_source, serving_requirements, total_output_kg, proteins_per_100g, fats_per_100g, carbs_per_100g, calories_per_100g, note, source_page) VALUES ('03517', 'тесто для мотти', (SELECT id FROM organizations WHERE name='Бранч'), '2023-04-30', 'Cake&Coffee', 1000, '(от ии) Мука рисовая (100 г), Сахар-песок (20 г), Молоко 3,2% (80 мл), Вода (30 мл), Масло подсолнечное (10 мл), Яйцо куриное (1 шт.) — смешать до однородного теста (консистенция густой сметаны). Дать отдохнуть 15 минут. Использовать для жарки моти/окономияки на сковороде при 180 °C по 3-4 минуты с каждой стороны.', 'ai', NULL, NULL, 0, 0, 0, 0, 'технологическая карта составлена на основании акта проработки. По физико-химическим показателям соответствует требованиям ГОСТ РФ 50763-2007 "Кулинарная продукция, реализуемая населению". По микробиологическим показателям соответствует требованиям СанПиН 2.3.2 1078-01', 426);
INSERT INTO tech_cards (card_number, dish_name, organization_id, approval_date, application_area, portion_norm, technology, technology_source, serving_requirements, total_output_kg, proteins_per_100g, fats_per_100g, carbs_per_100g, calories_per_100g, note, source_page) VALUES ('03514', 'Чиа пуддинг с манго', (SELECT id FROM organizations WHERE name='Бранч'), '2023-04-30', 'Cake&Coffee', 1.000, 'Консервированный манго гомогенезировать необходимости скорректировать вкус - одноразовый стаканчик выложить пуддинг, на пудинг выложить манговое пюре и посыпать миндальными лепестками.', 'original', NULL, 0.192, 0, 0, 0, 0, 'технологическая карта составлена на основании акта проработки. По физико-химическим показателям соответствует требованиям ГОСТ РФ 50763-2007 "Кулинарная продукция, реализуемая населению". По микробиологическим показателям соответствует требованиям СанПиН 2.3.2 1078-01', 427);
INSERT INTO tech_cards (card_number, dish_name, organization_id, approval_date, application_area, portion_norm, technology, technology_source, serving_requirements, total_output_kg, proteins_per_100g, fats_per_100g, carbs_per_100g, calories_per_100g, note, source_page) VALUES ('03327', 'Шоколадная бомбочка с какао', (SELECT id FROM organizations WHERE name='Бранч'), '2022-12-21', 'Cake&Coffee', 3.000, '(от ии) Сахар-песок (100 г) расплавить в сотейнике на среднем огне до карамели (180-190 °C, цвет — медный/золотистый). Добавить Молоко 3,2% (50 мл) — ОСТОРОЖНО, сильно брызгается! Перемешать. Разлить карамель по силиконовым полусферам d=6-8 см, создавая ''чашечки''. Дать застыть 30 мин. Внутрь поместить какао-порошок (5 г) и маршмеллоу (1 шт.). Накрыть второй половинкой, склеив растопленным шоколадом. Подавать бомбочку в чашке. Гость заливает горячим молоком (200 мл, 70-75 °C) — бомбочка тает, раскрывая начинку. Температура подачи молока 70-75 °C.', 'ai', 'Какао Красный И РЕАЛИЗАЦИИ октябрь Маршмелоу маленькие', 1.29, 0, 0, 0, 0, 'технологическая карта составлена на основании акта проработки. По физико-химическим показателям соответствует требованиям ГОСТ РФ 50763-2007 "Кулинарная продукция, реализуемая населению". По микробиологическим показателям соответствует требованиям СанПиН 2.3.2 1078-01', 428);
